  ui_story_5051_50510101_71_dialog_content = "(งานเลี้ยงวันครอบครัวดูเหมือนจะเป็นเหตุการณ์ที่สำคัญจริงๆ จะไม่สุ่มนำคนที่อ้างว่าเป็น Schwartz เป็นแบบ...)",
  ui_story_5051_50510101_72_dialog_content = "(ไม่เพียงแค่นั้น งานเลี้ยงทั้งหมดจะพังหากบาบายากะปรากฏตัวโดยไม่คาดคิด!)",
