  ui_story_5051_50510101_80_dialog_content = "เมื่อใดก็ตามที่มีปัญหา Baba Yaga มักจะเป็นคนที่จัดการกับมัน",
  ui_story_5051_50510101_81_dialog_content = "ฉันจะปฏิเสธคุณได้อย่างไรในเมื่อคุณเห็นได้ชัดว่าพยายามอย่างหนัก?",
