  ui_story_5051_50510101_95_dialog_content = "แต่ไม่เป็นไร ลูกแก้วน้อยน่ารักของฉันหาทางเจอเสมอ!",
  ui_story_5051_50510101_96_dialog_content = "แน่นอนว่าบางครั้งมันอาจทำให้ฉันตกหน้าผา...",
  ui_story_5051_50510101_97_dialog_content = "แต่การเดินทางคือความตื่นเต้นและความตื่นเต้น! อย่างน้อยนั่นคือสิ่งที่ Lady Jeriah พูด!",
  ui_story_5051_50510101_98_dialog_content = "เมื่อกี้ฉันพูดอะไรออกไปน่ะ? ใช่แล้ว อัมบราตัน!",
  ui_story_5051_50510101_99_dialog_content = "ถนนใน Umbraton ดูเหมือนยุ่งเหยิง แต่ก็ปฏิบัติตามหลักการของตนเอง",
  ui_story_5051_50510101_X99_dialog_content = "คนที่เข้าใจหลักการเหล่านี้ย่อมรู้ดีว่าควรตั้งร้านตรงไหนเพื่อความเป็นสิริมงคล",
  ui_story_5051_50510101_100_dialog_content = "อา ฉันได้ยินมาจากนักเดินทางที่ฉันพบระหว่างทาง",
  ui_story_5051_50510101_101_dialog_content = "ฉันชอบที่จะเรียนรู้เพิ่มเติมบางครั้งเมื่อฉันว่าง... เฮ้ มันคืออะไรบิน?!",
  ui_story_5051_50510101_102_dialog_content = "เอ่อ ขอโทษนะ...",
  ui_story_5051_50510101_103_dialog_content = "คุณเป็นใครอีกครั้ง?",
  ui_story_5051_50510101_104_dialog_content = "อ๊ะ! ฉันโง่ ฉันลืมแนะนำตัวเอง!",
  ui_story_5051_50510101_105_dialog_content = "ชื่อของฉันคือ <color=#FFB400>จาคีน</color>. ฉันคือทูตจากนอร์ธแลนด์!",
  ui_story_5051_50510101_106_dialog_content = "ขออภัยที่ช้าไปหน่อย แต่คุณก็รู้ว่าพวกเขาพูดว่าอย่างไร: ฮีโร่ที่ยิ่งใหญ่ที่สุดมักจะมาช้าเสมอ!",
  ui_story_5051_50510101_107_dialog_content = "<size=45>... ฉันคิดว่าคุณทำเกินกว่าที่ใคร ๆ จะมองว่า \"ตามสมัยนิยม\" มาไกลมากแล้ว!</size>",
  ui_story_5051_50510101_X107_dialog_content = "คุณก็รู้ว่าพวกเขาพูดอะไร ตัวเอกปรากฏตัวเป็นคนสุดท้ายเสมอ!",
  ui_story_5051_50510101_X108_dialog_content = "อะแฮ่ม สวัสดีท่านลอร์ดและสุภาพสตรี!",
  ui_story_5051_50510101_X109_dialog_content = "คืนนี้เรามารวมกันที่นี่ภายใต้หลังคาเดียวกัน...",
