  ui_story_5051_50510101_X111_dialog_content = "เพลิดเพลินกับอาหารเลิศรส",
  ui_story_5051_50510101_X112_dialog_content = "แต่ถึงแม้ว่าการเสิร์ฟจะอิ่มเอมในท้ายที่สุด",
  ui_story_5051_50510101_X113_dialog_content = "และการดื่มสุราจะหมดลง",
  ui_story_5051_50510101_X114_dialog_content = "เรายังคลุกคลีและขลุกขลักได้",
  ui_story_5051_50510101_X115_dialog_content = "พร้อมเพลิดเพลินบันเทิงเริงรมย์.",
  ui_story_5051_50510101_108_dialog_content = "สวัสดีแขกผู้มีเกียรติ",
  ui_story_5051_50510101_109_dialog_content = "พวกเราคือคณะนักร้องประสานเสียง Keating",
  ui_story_5051_50510101_110_dialog_content = "และตอนนี้เราจะร้องเพลง",
  ui_story_5051_50510101_111_dialog_content = "เราเรียกมันว่า Ode to Lumopolis",
  ui_story_5051_50510101_112_dialog_content = "เราหวังว่าคุณจะสนุกกับมัน!",
