  ui_story_5051_50510101_115_dialog_content = "โล่อันแน่วแน่ของเรา! ♪",
  ui_story_5051_50510101_116_dialog_content = "หอกที่ไม่มีใครหยุดยั้งของเรา! ♪",
  ui_story_5051_50510101_117_dialog_content = "ความรุ่งโรจน์และความสูงส่ง บทพิสูจน์แห่งศรัทธา! ♪",
  ui_story_5051_50510101_118_dialog_content = "ความสง่างามที่ดังกึกก้องเพื่อขับไล่ความมืดมิดออกไป! ♪",
  ui_story_5051_50510101_119_dialog_content = "ปราสาทบนที่สูงที่จะคงอยู่ตลอดไป! ♪",
  ui_story_5051_50510101_120_dialog_content = "แบบอักษรแห่งความทรงจำอันแสนหวาน! ♪",
  ui_story_5051_50510101_121_dialog_content = "เป้าหมายของการสรรเสริญของเรา! ♪",
  ui_story_5051_50510101_122_dialog_content = "ความสดใสของมันเอาชนะความมืดได้ ♪",
  ui_story_5051_50510101_123_dialog_content = "และนำวันที่สนุกสนานไม่รู้จบมาให้เรา! ♪",
  ui_story_5051_50510101_124_dialog_content = "ไวท์ไนท์อัพไฮ! ขอบคุณทุกคน.",
