  ui_story_5051_50510101_X125_dialog_content = "เด็กเหล่านี้มีความสามารถพิเศษด้านศิลปะ!",
  ui_story_5051_50510101_126_dialog_content = "พวกเขารู้วิธีทำความสะอาดและแสดงได้ดีจริง ๆ เหรอ?",
  ui_story_5051_50510101_127_dialog_content = "อย่างเป็นธรรมชาติ มิฉะนั้นใครจะเชิญพวกเขาไปงานที่สำคัญเช่นนี้?",
  ui_story_5051_50510101_128_dialog_content = "ถ้ายังประพฤติดีอยู่อย่างนี้ตลอดไป...",
  ui_story_5051_50510101_129_dialog_content = "...",
  ui_story_5051_50510101_130_dialog_content = "อืม? โอ้ฉันเดาว่าไมเคิลเห็นด้วย!",
  ui_story_5051_50510101_131_dialog_content = "\"ความสง่างามที่ก้องกังวาน ขับไล่ความมืดมน ปราสาทบนที่สูงที่จะคงอยู่ตลอดไป\"",
  ui_story_5051_50510101_132_dialog_content = "- วิกฤตความมืดมิด",
  ui_story_5051_50510101_133_dialog_content = "ภัยพิบัติที่น่าหวาดเสียวนั้นเป็นเพียงส่วนหนึ่งของประวัติศาสตร์ของเราในตอนนี้",
  ui_story_5051_50510101_134_dialog_content = "วิกฤต Darkover... พ่อ... แม่...",
  ui_story_5051_50510101_135_dialog_content = "อา! หยุด หยุด หยุด! นี่ควรจะเป็นงานเลี้ยงที่มีความสุข ดังนั้นไม่ต้องคิดอะไรให้เศร้าหมองอีกต่อไป!",
  ui_story_5051_50510101_136_dialog_content = "...",
  ui_story_5051_50510101_137_dialog_content = "ดู? แม้แต่ไมเคิลก็พยักหน้าเห็นด้วย!",
  ui_story_5051_50510101_138_dialog_content = "ยกโทษให้ฉัน ยูริเอล ฉันพูดผิดเมื่อกี้",
  ui_story_5051_50510101_139_dialog_content = "ไม่เป็นไร ฉันชินกับความเจ็บปวดแบบนี้แล้ว สิ่งที่ฉันไม่คุ้นเคยคืองานเลี้ยง",
  ui_story_5051_50510101_140_dialog_content = "ย-ใช่ ไม่ล้อเล่น! มันน่าเบื่อที่นี่กับคนเหล่านี้!",
  ui_story_5051_50510101_141_dialog_content = "มาเลย ไปซื้อไอศกรีมกันเถอะ!",
  ui_story_5051_50510101_142_dialog_content = "<size=30>อย่ายืนอยู่ตรงนั้น ไมเคิล! ช่วยฉันด้วย Uriel!</size>",
  ui_story_5051_50510101_143_dialog_content = "...",
  ui_story_5051_50510101_144_dialog_content = "ของฉันเด็กซนอะไร ฉันมองไปทางอื่นและไม่เห็นพวกเขา",
  ui_story_5051_50510101_145_dialog_content = "แต่ความทุกข์ทรมานที่ตามมานั้นยังคงลบล้างและคงอยู่เช่นเดิม",
  ui_story_5051_50510101_146_dialog_content = "ผู้ที่รอดชีวิตจากการทดสอบจะไม่มีทางละทิ้งความเจ็บปวดนั้นได้ แม้แต่ Four Angels ที่ทรงพลังก็ไม่มีข้อยกเว้น",
  ui_story_5051_50510101_147_dialog_content = "มาเดี๋ยวนี้ อิริดอน! ทำไมไม่ให้กำลังใจกันหน่อย",
  ui_story_5051_50510101_148_dialog_content = "งานเลี้ยงคืนนี้จะไม่ยาวนัก",
  ui_story_5051_50510101_149_dialog_content = "ทำแบบนี้ไปเรื่อย ๆ แล้วคุณจะพลาดส่วนที่เหลือ!",
  ui_story_5051_50510101_150_dialog_content = "Schwartz Family Day เดิมทีเป็นการระลึกถึงความสำเร็จมากมายของครอบครัว Schwartz",
  ui_story_5051_50510101_151_dialog_content = "ในวันนี้ <color=#FFB400>เมื่อสิบสองปีที่แล้ว</color>ลอร์ดเมืองคนปัจจุบันได้เอาชนะสถานการณ์อันตรายต่างๆ มากมาย และท้ายที่สุดก็พิสูจน์ให้เห็นถึงอำนาจของตระกูลชวาร์ตษ์ต่อชาวลูโมโพลิสทั้งหมด",
  ui_story_5051_50510101_152_dialog_content = "แต่ตั้งแต่วิกฤต Darkover Crisis งานเลี้ยงฉลองก็ลดขนาดลงทั้งขนาดและความยิ่งใหญ่",
  ui_story_5051_50510101_153_dialog_content = "ฉันยังจำช่วงเวลาที่วงโยธวาทิตและขบวนพาเหรดถือเป็นเรื่องปกติสำหรับวันหยุดนี้",
  ui_story_5051_50510101_154_dialog_content = "อย่างนั้นเหรอ? ฉันจำได้ไม่ชัดเจนทั้งหมด",
  ui_story_5051_50510101_155_dialog_content = "แต่ฉันจำได้ว่าผู้คนบ่นเกี่ยวกับ Schwartz Family Day ทุกปี",
  ui_story_5051_50510101_156_dialog_content = "คำพูดของพวกเขาคืออะไรอีกครั้ง... โอ้ใช่",
  ui_story_5051_50510101_157_dialog_content = "\"โอกาสเช่นนี้ต้องการการเฉลิมฉลองที่เหมาะสม พิธีที่สื่อถึงความจงรักภักดีและความเคารพในความสามารถของเยาวชนของ Lumopolis ต่อเจ้าเมือง\" หรืออะไรทำนองนั้น!",
  ui_story_5051_50510101_158_dialog_content = "ซึ่งเป็นเหตุผลว่าทำไมงานเลี้ยงรุ่นที่ไม่โอ้อวดจึงได้รับการเก็บรักษาไว้ในท้ายที่สุด",
  ui_story_5051_50510101_159_dialog_content = "ฉันเห็นด้วยอย่างเต็มที่กับการตัดสินใจของ City Lord ที่จะทำให้ทุกอย่างง่ายขึ้น ในแง่ของแรงงานและต้นทุนทางการเงิน นี่เป็นทางเลือกที่สมเหตุสมผลกว่ามาก",
  ui_story_5051_50510101_160_dialog_content = "แต่การเฉลิมฉลองทำให้คนที่ทำงานหนักหลายคนมีโอกาสพักผ่อนที่จำเป็นมาก",
  ui_story_5051_50510101_161_dialog_content = "และติดตามข่าวซุบซิบล่าสุด!",
  ui_story_5051_50510101_162_dialog_content = "เรื่องนั้นไม่จำเป็นหรอก",
  ui_story_5051_50510101_163_dialog_content = "เราได้รับอนุญาตให้เข้าไปตอนนี้หรือไม่?",
  ui_story_5051_50510101_164_dialog_content = "แน่นอนเราเป็น!",
  ui_story_5051_50510101_165_dialog_content = "ว่าแต่ ทำไมเราไม่เข้าไปข้างในตอนที่คณะนักร้องประสานเสียงกำลังร้องเพลงอยู่ล่ะ?",
  ui_story_5051_50510101_166_dialog_content = "ทุกคนกำลังเพลิดเพลินกับการแสดงของคณะนักร้องประสานเสียงอย่างเงียบๆ ดังนั้นฉันจึงไม่อยากรบกวนใครด้วยการเข้าไปยุ่ง มันคงเป็นการหยาบคาย",
  ui_story_5051_50510101_167_dialog_content = "ฮะ? นั่นคือสิ่งที่?",
  ui_story_5051_50510101_168_dialog_content = "ก็... ใช่... การขัดจังหวะการแสดงค่อนข้างหยาบคาย",
  ui_story_5051_50510101_169_dialog_content = "มีอา ถ้าเธอใส่ชุดนี้ แล้วบอกว่าเธอเป็นพี่สาวของคาร์ลีน...",
  ui_story_5051_50510101_170_dialog_content = "ฉันจะเชื่อคุณโดยสิ้นเชิงในทันที",
  ui_story_5051_50510101_171_dialog_content = "ตอนนี้คุณดูเหมือนเจ้าหญิง Lumopolis เลย!",
  ui_story_5051_50510101_172_dialog_content = "ท-นี่แค่ชุดธรรมดานะ ฉันแค่แต่งตัวให้ดูเป็นส่วนหนึ่งของงานเลี้ยงเท่านั้น...",
  ui_story_5051_50510101_173_dialog_content = "สามครั้งแล้ว! คุณพูดสิ่งเดิมสามครั้งระหว่างทางที่นี่!",
  ui_story_5051_50510101_174_dialog_content = "คุณจะหยุดการจ้องจับผิดเธอเหมือนตัวประหลาดไหม?",
  ui_story_5051_50510101_175_dialog_content = "ฉันไม่ได้ ogling! ฉันแค่ประหลาดใจคือทั้งหมด!",
  ui_story_5051_50510101_176_dialog_content = "ฉันไม่ซื้อ! นอกจากนี้ คุณไม่ได้สัญญากับผู้หญิงคนอื่นว่าคุณจะพาเธอไปงานเลี้ยง? คนในชุดสีม่วง?",
  ui_story_5051_50510101_177_dialog_content = "คุณจะทิ้งเธอไปหาผู้หญิงอื่นอย่างง่ายดายได้อย่างไร!",
  ui_story_5051_50510101_178_dialog_content = "คุณกำลังพูดถึงอะไร หญิงสาวในชุดสีม่วงบน Colossus คือ Mia! ตอนนี้เธอเพิ่งสวมชุดสีขาว!",
  ui_story_5051_50510101_179_dialog_content = "คุณกำลังล้อเล่นฉัน? ฉันไม่สามารถบอกได้! เธอใช้ Luminatics ที่มีมนต์ขลังแบบไหน!",
  ui_story_5051_50510101_180_dialog_content = "ฮะ?! ทะ-ทำไมคุณถึงเข้ามาใกล้จัง จู่ๆ...?",
  ui_story_5051_50510101_181_dialog_content = "คุณอยู่กับเราตลอดเวลา! ไม่สังเกตได้ยังไง!",
  ui_story_5051_50510101_182_dialog_content = "ฮี่ฮี่ เดาว่าฉันฟุ้งซ่านเกินไปกับทิวทัศน์ของลูโมโปลิส!",
  ui_story_5051_50510101_183_dialog_content = "เราไม่ควรเข้าไปข้างในตอนนี้ คุณสองคน...?",
  ui_story_5051_50510101_184_dialog_content = "จ-จริงด้วย นั่นสินะ",
  ui_story_5051_50510101_185_dialog_content = "เราควรตรวจสอบของขวัญของเราเพื่อความปลอดภัย เราทุกคนจำได้ว่าต้องนำมาด้วยใช่ไหม",
  ui_story_5051_50510101_186_dialog_content = "แต่แน่นอน! ในฐานะทูตของราชินี ฉันนำของขวัญที่ยากจะลืมเลือนมาให้!",
  ui_story_5051_50510101_187_dialog_content = "ฉันเอามาด้วย แต่...",
  ui_story_5051_50510101_188_dialog_content = "(น้ำผึ้งดอกแดนดิไลอันหนึ่งขวดอาจดูโทรมเกินไปสำหรับเหตุการณ์แบบนี้...)",
  ui_story_5051_50510101_189_dialog_content = "(เป็นชุดที่ดีที่สุดของปี แต่ดูเหมือนจะไม่เหมาะกับคฤหาสน์หลังนี้)",
  ui_story_5051_50510101_190_dialog_content = "น้ำผึ้งขวดนั้นดูน่าทึ่ง ฉันพนันได้เลยว่ามันคงจะอร่อยเมื่อได้ดื่มชาสักถ้วย",
  ui_story_5051_50510101_191_dialog_content = "ใครจะรู้? มันอาจจะเริ่มกระแสใหม่ในหมู่ขุนนาง!",
  ui_story_5051_50510101_192_dialog_content = "(มีอามองทะลุฉัน! เธอพยายามปลอบใจฉันอยู่แล้ว!)",
  ui_story_5051_50510101_193_dialog_content = "ฉันแค่หวังว่าเจ้าเมืองจะชอบมัน ยังไงฉันก็พร้อมทุกเมื่อนะพวกนาย! ไปกันเถอะ!",
  ui_story_5051_50510101_194_dialog_content = "ถึงแขกผู้มีเกียรติทุกท่าน ขอต้อนรับสู่วันครอบครัวชวาร์ตษ์ปีนี้",
  ui_story_5051_50510101_195_dialog_content = "โปรดเตรียมคำเชิญของคุณและลงชื่อเข้าใช้ที่นี่",
  ui_story_5051_50510101_196_dialog_content = "คำเชิญ คำเชิญ... มีของฉันที่นี่! ตอนนี้แค่เซ็นชื่อ!",
  ui_story_5051_50510101_197_dialog_content = "ทูตจากแดนเหนือ? ใช่ คุณดูเหมือนจะอยู่ในรายชื่อ",
  ui_story_5051_50510101_198_dialog_content = "เพื่อความปลอดภัยของคนรอบข้าง ฉันขอให้คุณดูแลสัตว์เลี้ยงของคุณอย่างใกล้ชิด เพลิดเพลินกับงานเลี้ยง",
  ui_story_5051_50510101_199_dialog_content = "ไม่ใช่ปัญหา! Whisper ประพฤติดีอย่างสมบูรณ์ ใช่ไหม?",
  ui_story_5051_50510101_200_dialog_content = "ฟ่อ!",
  ui_story_5051_50510101_X200_dialog_content = "ขอให้สนุกกับงานฉลองในค่ำคืนนี้",
  ui_story_5051_50510101_X201_dialog_content = "แน่นอน. ขอบคุณ!",
  ui_story_5051_50510101_201_dialog_content = "นี่คือคำเชิญของฉัน",
  ui_story_5051_50510101_202_dialog_content = "PlayerName ของ Eraveil เรารู้สึกเป็นเกียรติที่มีคุณอยู่ที่นี่ในวันนี้",
  ui_story_5051_50510101_203_dialog_content = "ขอขอบคุณที่สละเวลาช่วงเย็นมาร่วมงาน Schwartz Family Day ขอให้สนุกกับค่ำคืนนี้",
  ui_story_5051_50510101_204_dialog_content = "คนรับใช้ของเราพร้อมให้คุณโทรหา หากคุณต้องการอะไร เรายินดีให้บริการที่ดีที่สุดแก่คุณเท่านั้น",
  ui_story_5051_50510101_205_dialog_content = "เฮ้ ให้อะไร? ทำไมพวกเขาถึงปฏิบัติต่อคุณเหมือนเจ้านายแทน? ฉันคิดว่าฉันเป็นทูตจากนอร์ธแลนด์!",
  ui_story_5051_50510101_206_dialog_content = "และฉันคือ Caelestite คนสุดท้าย!",
  ui_story_5051_50510101_207_dialog_content = "(ฉันไม่รู้เลยว่าฉันได้รับความเคารพนับถือที่นี่!)",
  ui_story_5051_50510101_208_dialog_content = "ขออภัย มิสซิส แต่เธอเป็นใคร? คุณมีคำเชิญหรือไม่?",
  ui_story_5051_50510101_209_dialog_content = "!",
  ui_story_5051_50510101_210_dialog_content = "(มีอาสบายใจที่จาคีนกับฉันคุยกับเรา แต่เธอก็ยังขี้อายเกินกว่าจะคุยกับคนแปลกหน้า)",
  ui_story_5051_50510101_211_dialog_content = "(เธอทำตัวแปลกๆ ตั้งแต่เรามาถึง ราวกับว่าเธอกลัวผู้คนที่มารวมตัวกันที่นี่ในวันนี้)",
  ui_story_5051_50510101_212_dialog_content = "ช-เธอเป็นเพื่อนของฉัน!",
  ui_story_5051_50510101_213_dialog_content = "ฉันเห็น. เพื่อนของคุณไม่ต้องการคำเชิญ",
  ui_story_5051_50510101_214_dialog_content = "เข้ามาได้เลยครับ",
  ui_story_5051_50510101_215_dialog_content = "(เขาต้องพูดแบบนั้นจริง ๆ เหรอ หรือนี่เป็นเพียงวิธีพูดของคนชั้นสูง?)",
  ui_story_5051_50510101_216_dialog_content = "ขอบคุณนะ PlayerName...",
  ui_story_5051_50510101_217_dialog_content = "เค้กชิ้น! ฉันได้คุณ",
  ui_story_5051_50510101_218_dialog_content = "ชิ! ทุกคนยุ่งกันมาก PlayerName ที่พวกเขาลืมฉันไปหมดแล้ว!",
  ui_story_5051_50510101_219_dialog_content = "ขอโทษนะ แต่คุณคือคุณจาคิน ทูตจากนอร์ธแลนด์เหรอ?",
  ui_story_5051_50510101_220_dialog_content = "ถูกตัอง! ฉันคือหนึ่งเดียว ผู้ส่งสารคนใหม่ล่าสุดของ Queen of the North, Jakine!",
  ui_story_5051_50510101_221_dialog_content = "ฉันเห็น. ดังนั้นข่าวลือจึงเป็นจริง—ทูตคนใหม่ของ Northland มีผมสีแดงเข้มที่สวยงามเช่นเดียวกับรุ่นก่อนของเธอ",
  ui_story_5051_50510101_222_dialog_content = "เดี๋ยวก็เจอแล้ว <color=#FFB400>โบอาส</color> ก่อน? นั่นคือแม่ของฉัน คุณรู้ไหม!",
  ui_story_5051_50510101_223_dialog_content = "เยี่ยมเลย...",
  ui_story_5051_50510101_224_dialog_content = "ขออนุญาตแนะนำตัวเอง. ฉันชื่อคาเลบ ขุนนางชาวลูโมโปลิส เช่นเดียวกับคุณ ฉันมาที่นี่ตามคำเชิญของลอร์ดชวาร์ตษ์",
  ui_story_5051_50510101_225_dialog_content = "ฉันกำลังเดินทางไปหาเขา คุณสนใจที่จะไปกับฉันไหม",
  ui_story_5051_50510101_226_dialog_content = "อืม...",
  ui_story_5051_50510101_227_dialog_content = "เราสามารถพูดคุยเกี่ยวกับแม่ของคุณระหว่างทาง ถ้าคุณต้องการ?",
  ui_story_5051_50510101_228_dialog_content = "R-จริงเหรอ? เยี่ยมมาก!",
  ui_story_5051_50510101_X225_dialog_content = "คุณให้เกียรติ? คิดที่จะใส่ในภาษาธรรมดา?",
  ui_story_5051_50510101_X226_dialog_content = "ฮ่าฮ่าฮ่า... พูดง่ายๆ ก็คือ เจ้าเมืองส่งข้ามาเพื่อเจ้าโดยเฉพาะ",
  ui_story_5051_50510101_X227_dialog_content = "เขาส่งคนมาคุ้มกันฉัน?!",
  ui_story_5051_50510101_X228_dialog_content = "ฉันรู้แล้ว! นักการฑูตแห่งแดนเหนือจะไม่มีอิทธิพลได้อย่างไร?",
  ui_story_5051_50510101_X229_dialog_content = "เดี๋ยวก่อนฉันจะบอกเพื่อนที่มาด้วย!",
  ui_story_5051_50510101_229_dialog_content = "ฮิฮิ! ตรวจสอบออก PlayerName! ขุนนางผู้ดีคนนี้กำลังพาข้าไปพบเจ้าเมือง! บ๊ายบาย!",
  ui_story_5051_50510101_230_dialog_content = "เดี๋ยวก่อน คุณอยู่ไหน—และเธอก็จากไป แบบนั้น",
  ui_story_5051_50510101_231_dialog_content = "เธอเป็นอย่างอื่นจริงๆ เธอหนีไปกับคนแปลกหน้าแบบนั้นได้ยังไง ในเมื่อราชินีเบธเลเฮมขอให้ฉันไปกับเธอโดยเฉพาะ",
  ui_story_5051_50510101_X231_dialog_content = "(ฉันมาที่นี่เพราะฉันไม่ต้องการปฏิเสธคำเชิญเท่านั้น)",
  ui_story_5051_50510101_X232_dialog_content = "(แต่เนื่องจาก Mia คาดหวังให้ฉันติดต่อครอบครัวของเธอ ฉันจึงไม่สามารถทำให้เธอผิดหวังได้)",
  ui_story_5051_50510101_X233_dialog_content = "คุณโอเคไหม มีอา?",
  ui_story_5051_50510101_232_dialog_content = "ฉัน เอ่อ...",
  ui_story_5051_50510101_233_dialog_content = "(ไม่นะ ที่นี่เต็มไปด้วยขุนนางชาวลูโมโปลิส ดูเหมือนว่ามีอาจะถึงขีดจำกัดแล้ว)",
  ui_story_5051_50510101_234_dialog_content = "แล้วเราจะหาที่เงียบๆ กันดีไหม?",
  ui_story_5051_50510101_235_dialog_content = "แต่ฉันยังไม่ได้เห็นคาร์ลีน...",
  ui_story_5051_50510101_236_dialog_content = "ไม่ต้องกังวล! สำหรับตอนนี้เพียงแค่อยู่ที่นี่และพักผ่อน ฉันสัญญาว่าจะพาเธอมาพบคุณเร็วๆ นี้!",
  ui_story_5051_50510101_237_dialog_content = "PlayerName...",
  ui_story_5051_50510101_238_dialog_content = "มีห้องรับแขกอยู่ทางซ้ายมือ...",
  ui_story_5051_50510101_239_dialog_content = "ไปทางซ้าย! เข้าใจแล้ว!",
  ui_story_5051_50510101_240_dialog_content = "ประตูเปิดออกไปอีกด้าน ไม่มีประโยชน์ที่จะดึงมันขึ้นมา...",
  ui_story_5051_50510101_241_dialog_content = "โอ้ใช่! แล้วไปกันเลย!",
  ui_story_5051_50510101_X238_dialog_content = "มีสามประตู ประตูห้องรับรองมีแจกันสีขาวสองใบอยู่ข้าง...",
  ui_story_5051_50510101_X239_dialog_content = "เมื่อ Carleen ยังเด็ก เธอเผลอไปข่วนวงกบประตูโดยไม่ได้ตั้งใจ...",
  ui_story_5051_50510101_X240_dialog_content = "เลี้ยวซ้ายออกจากประตู... คุณถูกแล้ว ที่นี่มีสามประตู",
  ui_story_5051_50510101_X241_dialog_content = "อันที่มีแจกันสีขาวสองอันอยู่ข้าง ๆ คือ... ประตูซ้ายสุด",
  ui_story_5051_50510101_X242_dialog_content = "ใช่ มันคือห้องรับแขกแน่นอน!",
  ui_story_5051_50510101_X243_dialog_content = "(มีรอยขีดข่วนค่อนข้างไม่เด่นที่ด้านในของประตู เหมือนที่ Mia บอก)",
  ui_story_5051_50510101_242_dialog_content = "(ดูเหมือนมีอาจะคุ้นเคยกับที่นี่เป็นอย่างดี ราวกับว่าเธอเคยมาที่นี่มาก่อน)",
  ui_story_5051_50510101_243_dialog_content = "(เธออาจจะเป็นเจ้าหญิงแห่งลูโมโปลิสจริงหรือ...?)",
  ui_story_5051_50510201_1_dialog_content = "การแสดง Ode to Lumopolis ของคณะนักร้องประสานเสียงเสร็จสิ้นแล้ว",
  ui_story_5051_50510201_2_dialog_content = "การแสดงที่เหลือในคืนนี้ส่วนใหญ่เป็นการร้องรำทำเพลงโดยขุนนางหนุ่มผู้มีพรสวรรค์",
  ui_story_5051_50510201_3_dialog_content = "แขกผู้มีเกียรติของเราหลายคนหวังว่าคุณจะปรากฏตัวและเพลิดเพลินไปกับพวกเขา",
  ui_story_5051_50510201_4_dialog_content = "พวกเขาจำนวนหนึ่งต้องการเปลี่ยนแปลงโปรแกรมคืนนี้ด้วย",
  ui_story_5051_50510201_5_dialog_content = "\"การโซโล่เครื่องดนตรีของลูกชายควรเป็นตอนจบ\" \"การเต้นของลูกสาวต้องเลื่อนออกไปจนกว่าจะหาพื้นหลังที่เหมาะสมได้\" และอื่นๆ",
  ui_story_5051_50510201_6_dialog_content = "ฉันได้ดูแลคำขอเหล่านี้อย่างเหมาะสมแล้ว คุณสนใจที่จะดูไหม?",
  ui_story_5051_50510201_7_dialog_content = "ไม่เป็นไร ฉันเชื่อใจคุณ",
  ui_story_5051_50510201_8_dialog_content = "ขอบคุณสำหรับการดูแลการวางแผนงานเลี้ยงและการรักษาความปลอดภัยในกรณีที่คาร์ลีนไม่อยู่",
  ui_story_5051_50510201_9_dialog_content = "ควรเป็นหน้าที่ของคาร์ลีนในการจัดงานวันครอบครัว",
  ui_story_5051_50510201_10_dialog_content = "แต่ตลอดหลายปีที่ผ่านมา เธอเลือกที่จะเพิกเฉยเสมอ",
  ui_story_5051_50510201_11_dialog_content = "สำหรับฉัน วันนี้คือวันที่แม่จากไป",
  ui_story_5051_50510201_12_dialog_content = "ฉันไม่สามารถอยู่กับเธอในวาระสุดท้ายของเธอได้ ดังนั้นฉันจะไม่อยู่ในเมืองตอนนี้",
  ui_story_5051_50510201_13_dialog_content = "เธอพูดแบบเดิมทุกปี แล้วเธอก็หายตัวไปจากลูโมโพลิส",
  ui_story_5051_50510201_14_dialog_content = "แม้ว่าเธอจะไม่ได้อยู่กับเธอนานนัก แต่การสูญเสียแม่ของเธอยังคงทำให้เธอเจ็บปวดจนถึงทุกวันนี้",
  ui_story_5051_50510201_15_dialog_content = "คุณเชื่อหรือไม่ว่าเลดี้คาร์ลีนขาดวุฒิภาวะ?",
  ui_story_5051_50510201_16_dialog_content = "ตรงกันข้าม ทั้งหมดนี้มีรากฐานมาจากความผิดพลาดโง่ๆ ที่ฉันทำในวัยเยาว์",
  ui_story_5051_50510201_17_dialog_content = "ฉันแค่เก็บเกี่ยวสิ่งที่ฉันหว่าน",
  ui_story_5051_50510201_18_dialog_content = "คุณโทษตัวเองมากเกินไป",
  ui_story_5051_50510201_19_dialog_content = "เราเป็นแค่มนุษย์เท่านั้น ท่านลอร์ด สิ่งที่เราทำได้คือมุ่งมั่นที่จะบรรลุความยิ่งใหญ่ด้วยเวลาอันน้อยนิดที่เรามอบให้",
  ui_story_5051_50510201_20_dialog_content = "คุณต้องดูสถานะปัจจุบันของ Lumopolis เท่านั้นเพื่อดูว่าคุณประสบความสำเร็จอะไรบ้าง",
  ui_story_5051_50510201_21_dialog_content = "หากไม่มีคุณ แม้แต่มัคคุเทศก์ที่ดีที่สุดก็ไม่มีทางนำเสนอความรุ่งโรจน์ของลูโมโปลิสแก่ผู้มาเยือนจำนวนมากได้",
  ui_story_5051_50510201_22_dialog_content = "ฉันไม่พูดดีกว่านี้ด้วยตัวเอง คุณบล็องก์!",
  ui_story_5051_50510201_23_dialog_content = "หรือดูจากการแต่งกายของคุณแล้ว ฉันควรจะเรียกคุณว่า คุณโรท แทนดีไหม?",
  ui_story_5051_50510201_24_dialog_content = "สวัสดี ดยุคออตโต งานเลี้ยงวันนี้เป็นการฉลองให้กับลอร์ดชวาร์ตษ์และความสำเร็จมากมายของเขา",
  ui_story_5051_50510201_25_dialog_content = "บทบาทของฉันเล็กน้อยและไม่ได้รับคำชมใดๆ คุณสามารถเรียกฉันตามที่คุณต้องการ",
  ui_story_5051_50510201_26_dialog_content = "เล็ก คุณว่าไหม? ฮ่าฮ่าฮ่า! คุณค่อนข้างมีอารมณ์ขัน คุณร็อตแห่งไนท์วอช",
  ui_story_5051_50510201_27_dialog_content = "ขอโทษที่มาช้า เจ้านายของฉัน ฉันภาวนาว่าฉันไม่ขัดจังหวะความทรงจำของคุณ?",
  ui_story_5051_50510201_28_dialog_content = "ไม่จำเป็นต้องปฏิบัติตามพิธีการตามปกติในคืนนี้ คุณต้องเพลิดเพลินกับงานเลี้ยงเท่านั้น",
  ui_story_5051_50510201_29_dialog_content = "แต่นั่นจะไม่ทำเลย ท่านลอร์ด คืนนี้ขอรำลึกถึงคุณูปการอันยิ่งใหญ่ของคุณในงาน Lumopolis ของเรา",
  ui_story_5051_50510201_30_dialog_content = "น่าเสียดายที่คนใกล้ตัวคุณมองไม่เห็นแบบนั้น",
  ui_story_5051_50510201_31_dialog_content = "นี่คงเป็นความหมายของคำว่า \"เดียวดายบนยอดเขา\"",
  ui_story_5051_50510201_32_dialog_content = "แต่คุณต้องรู้ถึงความรู้สึกนั้นด้วย อ็อตโต้",
  ui_story_5051_50510201_33_dialog_content = "ท้ายที่สุด คุณเสียสละมากในช่วงหลายปีที่ผ่านมาเพื่อเห็นแก่ตระกูลทรอยและสภาผู้อาวุโส",
  ui_story_5051_50510201_34_dialog_content = "คุณประจบฉันเจ้านายของฉัน ความสำเร็จของฉันไม่มีอะไรเทียบได้กับของคุณ",
  ui_story_5051_50510201_35_dialog_content = "ลูกชายของฉันจะกล่าวสุนทรพจน์หลังจากการแสดงปัจจุบันสิ้นสุดลง เขาจะรู้สึกเป็นเกียรติถ้าคุณอยู่ที่นั่นเพื่อรับฟัง",
  ui_story_5051_50510201_36_dialog_content = "น่าเสียดายที่แขกผู้มีเกียรติได้ขอเข้าเฝ้าพร้อมกับฉัน",
  ui_story_5051_50510201_37_dialog_content = "อย่างไรก็ตาม ฉันมั่นใจว่าการแสดงความสามารถเล็กๆ น้อยๆ ของลูกชายคุณจะไม่เป็นที่ชื่นชมของแขกในค่ำคืนนี้",
  ui_story_5051_50510201_38_dialog_content = "สำหรับตอนนี้ ฉันต้องปรากฏตัวที่อื่น",
  ui_story_5051_50510201_39_dialog_content = "นายท่าน คนรับใช้อยู่ที่นี่กับแขกที่มาขอพบท่าน",
  ui_story_5051_50510201_40_dialog_content = "เราก็เพิ่งพูดถึงเหมือนกัน ขอให้มีความสุขกับงานเลี้ยงนะออตโต้",
  ui_story_5051_50510201_41_dialog_content = "ดีมากเจ้านายของฉัน",
  ui_story_5051_50510201_42_dialog_content = "... นี่คือเหตุผลที่ฉันพูดเสมอว่ามังกรเป็นเผ่าพันธุ์ที่มีมนต์ขลัง!",
  ui_story_5051_50510201_43_dialog_content = "พวกมันพอดีกับฝ่ามือของคุณเมื่อพวกมันยังเด็ก แต่พวกมันก็โตขึ้นจนใหญ่เท่ายักษ์ใหญ่!",
  ui_story_5051_50510201_44_dialog_content = "ตอนนี้ฉันคิดเกี่ยวกับมันแล้ว มังกรและ Colossi ดูคล้ายกัน พวกเขาอาจเกี่ยวข้องกันหรือไม่?",
  ui_story_5051_50510201_45_dialog_content = "อะแฮ่ม คุณจาคีน?",
  ui_story_5051_50510201_46_dialog_content = "ใช่มันคืออะไร?",
  ui_story_5051_50510201_47_dialog_content = "มีคนบอกว่าเลดี้โบอาสบรรพบุรุษของคุณค่อนข้างเชี่ยวชาญในการทำนาย",
  ui_story_5051_50510201_48_dialog_content = "ฉันหลงรักศาสตร์การทำนายของนอร์ธแลนด์มาโดยตลอด คุณมีความรู้ในเรื่องนี้โดยบังเอิญหรือไม่?",
  ui_story_5051_50510201_49_dialog_content = "แน่นอนฉันทำ! อันที่จริง ฉันเป็นปรมาจารย์ด้าน—",
  ui_story_5051_50510201_50_dialog_content = "*อะแฮ่ม* ใช่ค่ะ ฉันดูดวงนิดหน่อย",
  ui_story_5051_50510201_51_dialog_content = "ราชินีเบธเลเฮมส่งฉันมาที่นี่โดยเฉพาะเพื่อเติมเต็ม <color=#FFB400>คริสตัลแห่งความทรงจำนิรันดร์</color> ด้วยน้ำจากทะเลสาบมิเรอร์",
  ui_story_5051_50510201_52_dialog_content = "ฉันเชื่อว่าฉันเคยได้ยินเกี่ยวกับวัตถุนี้มาก่อน",
  ui_story_5051_50510201_53_dialog_content = "แต่ทำไม Crystal of Eternal Memory จึงต้องการน้ำจาก Lake Mirror?",
  ui_story_5051_50510201_54_dialog_content = "ฉันรู้สึกว่ามันเป็นแค่ภาชนะสำหรับเก็บลูมิน่า...",
  ui_story_5051_50510201_55_dialog_content = "สวัสดี คุณจาคีน ฉันได้พบคุณในที่สุด",
  ui_story_5051_50510201_56_dialog_content = "โอ้สวัสดี!",
  ui_story_5051_50510201_57_dialog_content = "<size=30>Psst! ผู้หญิงคนนี้ควรจะเป็นใคร คุณคาเลบ?</size>",
  ui_story_5051_50510201_58_dialog_content = "เป็นเวลานานแล้ว คุณบล็องก์",
  ui_story_5051_50510201_59_dialog_content = "มันค่อนข้างนานใช่ ฉันเชื่อว่านี่เป็นครั้งแรกที่ฉันได้พบคุณที่งานเลี้ยงวันครอบครัว ขอบคุณที่ให้เกียรติเราด้วยการเข้าร่วมของคุณ",
  ui_story_5051_50510201_60_dialog_content = "นี่คือคุณบล็องก์ คิดว่าเธอเป็นผู้ช่วยส่วนตัวของ City Lord",
  ui_story_5051_50510201_61_dialog_content = "นั่นสินะ...",
  ui_story_5051_50510201_62_dialog_content = "คุณจาคีน ท่านลอร์ดชวาร์ตษ์กำลังรอคุณอยู่ที่ห้องรับแขก เชิญทางนี้ครับ",
  ui_story_5051_50510201_63_dialog_content = "H-เป็นไงบ้าง! ฉัน Jakine ทูตของราชินีเบธเลเฮม!",
  ui_story_5051_50510201_64_dialog_content = "เป็นเวลากว่าสิบสองปีแล้วที่ทูตจากทางเหนือมาเยี่ยมลูโมโปลิส!",
  ui_story_5051_50510201_65_dialog_content = "ตามคำสั่งของฝ่าบาท ข้ามาเพื่อเติม Crystal of Eternal Memory ด้วย <color=#FFB400>น้ำจากทะเลสาบมิเรอร์</color>.",
  ui_story_5051_50510201_66_dialog_content = "ขอบคุณที่มาที่นี่ในวันนี้ ทูตแห่งนอร์ธแลนด์",
  ui_story_5051_50510201_67_dialog_content = "สมเด็จพระเจ้าอยู่หัวทรงทราบรายละเอียดแล้ว ในนามของ Lumopolis ฉันขอขอบคุณสำหรับการเดินทางไกลเพื่อทำภารกิจของคุณ",
  ui_story_5051_50510201_68_dialog_content = "วันเดียวเสร็จ! มันเป็นความรับผิดชอบของฉันหลังจากทั้งหมด!",
  ui_story_5051_50510201_69_dialog_content = "คุณร็อต คุณช่วยนำคริสตัลแห่งความทรงจำนิรันดร์มาให้เราหน่อยได้ไหม",
  ui_story_5051_50510201_70_dialog_content = "ตามที่เธอปรารถนา",
  ui_story_5051_50510201_71_dialog_content = "...",
  ui_story_5051_50510201_72_dialog_content = "เมื่อฉันจำได้ ฉันได้ขอให้คุณร็อตรับทูตของนอร์ธแลนด์โดยเฉพาะในวันนี้",
  ui_story_5051_50510201_73_dialog_content = "คุณได้ผูกมิตรกับนักการทูตในระหว่างงานเลี้ยงหรือไม่ คาเลบ?",
  ui_story_5051_50510201_74_dialog_content = "ยกโทษให้ฉันเจ้านายของฉัน",
  ui_story_5051_50510201_75_dialog_content = "ในฐานะสมาชิกคนหนึ่งของตระกูล Magnus ฉันคิดง่ายๆ ว่าฉันมีหน้าที่ต้องรักษาไว้ ท้ายที่สุดสิ่งนี้เกี่ยวข้องกับก <color=#FFB400>ของที่ระลึกของน้องสาวของฉัน</color>.",
  ui_story_5051_50510201_76_dialog_content = "ฉันไม่นึกเลยว่าคุณจะคัดค้านการที่ฉันอยู่แบบนี้",
  ui_story_5051_50510201_77_dialog_content = "(เป็นมรดกของพี่สาวของเขา? ตระกูลแม็กนัส? พวกเขากำลังพูดถึงเรื่องอะไรกัน?! แล้วทำไมบรรยากาศถึงรู้สึกกระอักกระอ่วนใจขึ้นมาทันที?!)",
  ui_story_5051_50510201_78_dialog_content = "(ฉันทำพลาด PlayerName, เมีย...)",
  ui_story_5051_50510201_X78_dialog_content = "(ฉันไม่ควรไปคนเดียวเพื่อทำภารกิจนี้ให้สำเร็จ... ใครก็ได้มาช่วยฉันที!)",
  ui_story_5051_50510201_79_dialog_content = "ท่านลอร์ด วันนี้ฉันเชิญคุณคาเลบมาที่นี่",
  ui_story_5051_50510201_80_dialog_content = "เขาต้องการที่จะหาผู้ชมของคุณในเรื่องใดเรื่องหนึ่ง เนื่องจากคุณค่อนข้างยุ่งในเย็นนี้ ฉันจึงคิดว่าเป็นการดีที่สุดที่จะปล่อยให้เขามาที่นี่และพูดความในใจของเขา",
  ui_story_5051_50510201_81_dialog_content = "ในฐานะสมาชิกในครอบครัวของคุณ เขาสมควรได้รับการจัดลำดับความสำคัญ ฉันคิดว่า",
  ui_story_5051_50510201_82_dialog_content = "คุณโรจน์... บางครั้งฉันคิดว่าคุณเก่งงานเกินไป",
  ui_story_5051_50510201_83_dialog_content = "ขอบคุณสำหรับคำชมของคุณ",
  ui_story_5051_50510201_84_dialog_content = "นี่คือคริสตัลแห่งความทรงจำชั่วนิรันดร์ ขอขอบคุณอีกครั้งสำหรับความช่วยเหลือของคุณ",
  ui_story_5051_50510201_85_dialog_content = "เอาล่ะ ปล่อยให้ฉันจัดการเอง!",
  ui_story_5051_50510201_86_dialog_content = "(ฉันรอดแล้ว! โอ้ ขอบคุณ คุณบลองก์!)",
  ui_story_5051_50510201_87_dialog_content = "คุณคาเลบ ไวน์ Umbraton นี้ได้รับมาจากแขกคนหนึ่งในคืนนี้",
  ui_story_5051_50510201_88_dialog_content = "มันมีผลสงบเงียบเป็นพิเศษ ขอสักแก้วนะครับ",
  ui_story_5051_50510201_89_dialog_content = "ขอบคุณมากนะ",
  ui_story_5051_50510201_90_dialog_content = "ถ้าฉันจำไม่ผิด คาเลบ เหตุผลที่คุณมาที่นี่ในวันนี้คือคริสตัลแห่งความทรงจำชั่วนิรันดร์ ฉันถูกไหม?",
  ui_story_5051_50510201_91_dialog_content = "ความพิเศษนี้ <color=#FFB400>อุปกรณ์บันทึก</color> ราชินีแห่งแดนเหนือมอบให้ฉันและโยชูวาเป็นของขวัญ",
  ui_story_5051_50510201_92_dialog_content = "เมื่อ 12 ปีก่อน ภรรยาของผม น้องสาวของคุณ เป็นผู้เปิดใช้งานมันด้วยตัวเธอเอง",
  ui_story_5051_50510201_93_dialog_content = "แต่สิ่งที่มีอยู่คือความทรงจำบางส่วนที่กระจัดกระจายในปีนั้น",
  ui_story_5051_50510201_94_dialog_content = "ฉันแค่ดูแลมันหลังจากที่เธอจากไป แต่ฉันไม่ได้ตั้งใจจะเก็บไว้คนเดียว",
  ui_story_5051_50510201_95_dialog_content = "หากราชินีต้องการคืน ข้าก็ไม่ขัดข้อง",
  ui_story_5051_50510201_96_dialog_content = "... ความทรงจำเกี่ยวกับภรรยาและลูกสาวของคุณมีความหมายเพียงเล็กน้อยสำหรับคุณจริงๆ หรือ?",
  ui_story_5051_50510201_97_dialog_content = "สมเด็จย่าไม่เคยตรัสว่าจะเอาคืนเลยรู้ไหม!",
  ui_story_5051_50510201_98_dialog_content = "นอกจากนี้ โลกภายในคริสตัลนั้นขับเคลื่อนโดย Lumina ของผู้ที่เปิดใช้งานมัน ราชินีเบธเลเฮมจะไม่มีประโยชน์อะไร!",
  ui_story_5051_50510201_99_dialog_content = "โลกภายในคริสตัล?",
  ui_story_5051_50510201_100_dialog_content = "ถูกตัอง! Crystal of Eternal Memory ไม่ใช่อุปกรณ์บันทึกธรรมดา!",
  ui_story_5051_50510201_101_dialog_content = "มีทั้งหมด <color=#FFB400>โลกแห่งความจริง</color> เก็บรักษาไว้ข้างใน!",
  ui_story_5051_50510201_102_dialog_content = "แต่เป็นไปได้อย่างไร?",
  ui_story_5051_50510201_103_dialog_content = "ฉันเดาว่าคุณไม่คุ้นเคยกับมัน คุณคาเลบ",
  ui_story_5051_50510201_104_dialog_content = "ให้ฉันอธิบายวิธีการทำงาน!",
  ui_story_5051_50510201_105_dialog_content = "ประการแรก Crystal of Eternal Memory ต้องการน้ำใน Lake Mirror ในปริมาณที่เพียงพอเพื่อให้ทำงานได้อย่างถูกต้อง",
  ui_story_5051_50510201_106_dialog_content = "เมื่อพร้อมแล้ว คริสตัลจะต้องเปิดใช้งานโดยการผสมเข้ากับ Lumina ของผู้ใช้",
  ui_story_5051_50510201_107_dialog_content = "หลังจากนั้นคริสตัลจะเริ่มบันทึกทุกอย่างที่เกิดขึ้น <color=#FFB400>วันเดียว</color>ภายในรัศมีที่กำหนด",
  ui_story_5051_50510201_108_dialog_content = "มันถูกเก็บรักษาไว้ในคริสตัลแห่งความทรงจำชั่วนิรันดร์",
  ui_story_5051_50510201_109_dialog_content = "เมื่อรวมเข้ากับ Lumina อีกครั้ง ผู้ใช้สามารถเข้าสู่โลกของคริสตัลและสัมผัสกับความทรงจำได้ด้วยตัวเอง!",
  ui_story_5051_50510201_110_dialog_content = "และนั่นคือหลักการทำงานของ Crystal of Eternal Memory และ Pocket Universe",
  ui_story_5051_50510201_111_dialog_content = "แต่มีการจับ! คริสตัลนั้นเปราะบางมาก...",
  ui_story_5051_50510201_112_dialog_content = "เมื่อเข้าไปข้างในแล้ว ผู้ใช้จะต้องซ่อนตัวและหลีกเลี่ยงการโต้ตอบกับใครหรืออะไรก็ตามโดยเสียค่าใช้จ่ายทั้งหมด",
  ui_story_5051_50510201_113_dialog_content = "<size=42>มิฉะนั้น การเปลี่ยนแปลงเพียงเล็กน้อยในเรื่องราวที่สร้างขึ้นอาจส่งผลให้เกิดหายนะที่ไม่อาจจินตนาการได้!</size>",
  ui_story_5051_50510201_114_dialog_content = "นี่คือสิ่งที่ Luminatics ลึกลับของ Northland เป็นเช่นนั้น ...",
  ui_story_5051_50510201_115_dialog_content = "<size=30>ซับซ้อนน่าขยะแขยงเพียงใด</size>",
  ui_story_5051_50510201_116_dialog_content = "วุ้ย เอาล่ะ ตอนนี้คริสตัลเต็มน้ำแล้วและพร้อมที่จะไป!",
  ui_story_5051_50510201_117_dialog_content = "เอาล่ะ ลอร์ดชวาร์ตซ์",
  ui_story_5051_50510201_118_dialog_content = "คุณสามารถใช้งานได้ทุกเมื่อที่คุณต้องการตอนนี้!",
  ui_story_5051_50510201_119_dialog_content = "คุณมีความกตัญญูทูต",
  ui_story_5051_50510201_120_dialog_content = "แต่น่าเสียดาย...คนที่เปิดใช้งานไม่ได้อยู่กับเราแล้ว",
  ui_story_5051_50510201_121_dialog_content = "ก่อนที่เธอจะจากเราไป ไม่มีใครเต็มใจที่จะย้อนอดีตที่บันทึกไว้ในคริสตัล",
  ui_story_5051_50510201_122_dialog_content = "และตอนนี้เมื่อเธอจากไปแล้ว ฉันไม่มีสิทธิ์ที่จะหมกมุ่นอยู่กับความสำนึกผิดของตัวเองอีกต่อไป",
  ui_story_5051_50510201_123_dialog_content = "ฉันเกรงว่าจะไม่มีใครเปิดใช้งานได้อีก",
  ui_story_5051_50510201_124_dialog_content = "เอ่อ...",
  ui_story_5051_50510201_125_dialog_content = "ท-ไม่เป็นไร! ในฐานะผู้ฝึกฝนการทำนายจากดินแดนทางเหนือ ฉันแน่ใจว่าฉันสามารถหาวิธีอื่นที่จะใช้มันได้!",
  ui_story_5051_50510201_126_dialog_content = "ขอดูหน่อย...คาถาว่าดังนี้...",
  ui_story_5051_50510201_127_dialog_content = "...",
  ui_story_5051_50510201_128_dialog_content = "ดูสิ การปลุกเสกจะเป็นแบบนี้...",
  ui_story_5051_50510201_129_dialog_content = "โจชัว เราตกลงที่จะเรียนรู้วิธีใช้ Crystal of Eternal Memory ด้วยกันไม่ใช่หรือ?",
  ui_story_5051_50510201_130_dialog_content = "ฉันรู้ว่าคุณรักการเรียนรู้มากแค่ไหน แต่เมื่อคุณเร่งรีบกับเรื่องแบบนี้ ฉันก็อดไม่ได้ที่จะรู้สึกว่าถูกทิ้งไว้ข้างหลัง",
  ui_story_5051_50510201_131_dialog_content = "โอ้? ฉันไม่รู้ว่าฉันจะทำให้คุณรู้สึกเหงาได้ขนาดนี้",
  ui_story_5051_50510201_132_dialog_content = "ฉันคิดว่าฉันเป็นคนเดียวที่ต้องทนทุกข์ทรมานกับอารมณ์เช่นนี้",
  ui_story_5051_50510201_133_dialog_content = "ยกโทษให้ฉันที่รัก ฉันยุ่งกับงานมากจนละเลยคุณและสาวๆ",
  ui_story_5051_50510201_134_dialog_content = "หึหึ ฉันแค่แกล้งคุณ",
  ui_story_5051_50510201_135_dialog_content = "ต้องขอบคุณความพยายามของคุณเท่านั้นที่ทำให้เรามีความสงบสุขและความเจริญรุ่งเรืองที่จำเป็นในการรู้สึกถึงอารมณ์ทุกประเภท",
  ui_story_5051_50510201_136_dialog_content = "ความสุข ความตื่นเต้น ความรัก... และความเหงาด้วย",
  ui_story_5051_50510201_137_dialog_content = "แต่ตอนนี้ ข้ามีของขวัญชิ้นนี้จากราชินีแห่งแดนเหนือ",
  ui_story_5051_50510201_138_dialog_content = "ถ้าฉันรู้สึกเหงา ฉันมาหาคุณได้เสมอในคริสตัลแห่งความทรงจำชั่วนิรันดร์นี้",
  ui_story_5051_50510201_139_dialog_content = "โจชัว...",
  ui_story_5051_50510201_140_dialog_content = "ดังนั้นโปรดให้ฉันเปิดใช้งานได้ไหม",
  ui_story_5051_50510201_141_dialog_content = "ดีมากที่รัก ตราบใดที่มันทำให้คุณมีความสุข",
  ui_story_5051_50510201_142_dialog_content = "คุณตัดสินใจแล้วหรือยังว่าจะบันทึกวันไหน",
  ui_story_5051_50510201_143_dialog_content = "<color=#FFB400>เวโรนิก้า</color> วันเกิด? หรืออาจจะเป็นการแสดงครั้งแรกของ Carleen? หรือบางที...",
  ui_story_5051_50510201_144_dialog_content = "มันเป็นความลับ!",
  ui_story_5051_50510201_145_dialog_content = "ช่วยบอกฉันหน่อยไม่ได้เหรอ ฉันไม่อยากหลอกตัวเองเมื่อคุณตัดสินใจเปิดใช้งาน",
  ui_story_5051_50510201_146_dialog_content = "สวรรค์ ข้าไม่รู้ว่าเจ้าเมืองลูโมโพลิสสามารถหลอกตัวเองได้!",
  ui_story_5051_50510201_147_dialog_content = "แน่นอน ฉัน... จำตอนที่ฉันเหยียบของเล่นของคาร์ลีนโดยไม่ได้ตั้งใจแล้วทำมันพังได้ไหม?",
  ui_story_5051_50510201_148_dialog_content = "ฉันไม่คิดว่าเธอสนใจมากนักในตอนนั้น เพราะเธอแทบจะไม่ตอบสนองเมื่อมันเกิดขึ้น ฉันรู้น้อยว่าเธอใช้เวลาที่เหลือทั้งวันร้องไห้ในห้องนอนของเธอ...",
  ui_story_5051_50510201_149_dialog_content = "ใช่ ฉันจำได้ว่าคุณยืนอยู่ข้างนอกประตูพร้อมกับของเล่นชิ้นใหม่ ไม่กล้าเข้าไปข้างใน สีหน้าเจ้าหวาดกลัวยิ่งกว่าข้ารับใช้สองสามคนเสียอีก",
  ui_story_5051_50510201_150_dialog_content = "มีกรณีอื่น ๆ อีกไหมที่อยู่ในใจ?",
  ui_story_5051_50510201_151_dialog_content = "... มีอยู่ช่วงหนึ่งที่ฉันทิ้งพวงหรีดดอกกุหลาบที่เวโรนิกามอบให้ฉันไว้ที่ห้องรับแขก",
  ui_story_5051_50510201_152_dialog_content = "วันนั้นฉันยุ่งกับแขกคนหนึ่งมาก จนฉันเผลอวางของขวัญไว้บนโต๊ะ โดยที่เธอไม่รู้ตัวว่าเธอคิดว่าฉันไม่ชอบมันและโยนมันทิ้งไป...",
  ui_story_5051_50510201_153_dialog_content = "จากนั้นคุณสั่งให้ชาวสวนปลูกกุหลาบทั้งสวนเพื่อเธอ",
  ui_story_5051_50510201_154_dialog_content = "น่าเสียดายที่ลูกสาวของเราหมกมุ่นกับการฝึกฝนทำให้เธอไม่มีเวลาหรือความสนใจในการสานพวงหรีดดอกไม้อีกเลย...",
  ui_story_5051_50510201_155_dialog_content = "(ถอนหายใจ)",
  ui_story_5051_50510201_156_dialog_content = "คุณไม่ได้หลอกตัวเองในตอนนั้น แดเนียลที่รักของฉัน",
  ui_story_5051_50510201_157_dialog_content = "โลกนี้ทั้งกว้างใหญ่และซับซ้อน และเราถูกจำกัดอย่างมากในสิ่งที่เรามองเห็นและทำได้",
  ui_story_5051_50510201_158_dialog_content = "ซึ่งเป็นเหตุผลที่ฉันเชื่อว่าคริสตัลแห่งความทรงจำชั่วนิรันดร์นี้เป็นสิ่งที่วิเศษมาก... มันทำให้เรามีโอกาสที่จะบันทึกช่วงเวลาเหล่านั้นในชีวิตของเรา และถนอมมันตราบเท่าที่เรายังมีชีวิตอยู่",
  ui_story_5051_50510201_159_dialog_content = "ความทรงจำอาจไม่น่าเชื่อถือมากนัก แต่ด้วยคริสตัลนี้ ตัวตนที่แท้จริงของเราจะคงอยู่ชั่วนิรันดร์",
  ui_story_5051_50510201_160_dialog_content = "ดี ไม่ดี ถูก ผิด... สักวันครอบครัวเราจะรู้สึกสูญเสียและสับสน",
  ui_story_5051_50510201_161_dialog_content = "เมื่อวันนั้นมาถึง คริสตัลนี้จะแสดงให้เราเห็น <color=#FFB400>คำตอบที่เราต้องการ</color>. ฉันแน่ใจว่ามัน",
  ui_story_5051_50510201_162_dialog_content = "<color=#e8d9bb>แกล๊ง!</color>",
  ui_story_5051_50510201_163_dialog_content = "...",
  ui_story_5051_50510201_164_dialog_content = "คุณอยู่ที่นั่น ซ่อนตัวอยู่ในเงามืด แสดงตัวเอง.",
  ui_story_5051_50510201_165_dialog_content = "ฉัน-ฉันเอง PlayerName! ขอโทษที่ขัดจังหวะ! ฮ่าๆๆ...",
  ui_story_5051_50510201_166_dialog_content = "ให้ฉันดูว่าฉันเข้าใจถูกต้องหรือไม่",
  ui_story_5051_50510201_167_dialog_content = "คุณต้องการที่จะนำเสนอ City Lord ด้วยของขวัญของคุณ คุณจึงบุกเข้าไปในห้องรับรองของเขาโดยไม่ถาม",
  ui_story_5051_50510201_168_dialog_content = "แต่เมื่อลอร์ดชวาร์ตษ์และแขกของเขาเข้ามาในห้อง คุณจะซ่อนตัวโดยสัญชาตญาณแทนที่จะทักทายใครก็ตาม",
  ui_story_5051_50510201_169_dialog_content = "ตั้งแต่นั้นมา คุณแอบฟังจากหลังม่าน",
  ui_story_5051_50510201_170_dialog_content = "ถูกต้องหรือไม่?",
  ui_story_5051_50510201_171_dialog_content = "เออ ใช่ ถูกต้อง ขอโทษ...",
  ui_story_5051_50510201_172_dialog_content = "(ฉันหมายถึง ฉันทำไปเพราะปฏิกิริยาแรกของมีอาคือการซ่อน ฉันก็เลยทำตาม...)",
  ui_story_5051_50510201_173_dialog_content = "(เราไม่น่าพาเธอมาที่นี่เร็วนัก... เธอไม่อยู่ในสภาพที่จะพบปะผู้คนใหม่ๆ ได้ในตอนนี้)",
  ui_story_5051_50510201_174_dialog_content = "ฉันชื่นชมในความซื่อสัตย์และความตั้งใจดีของคุณ หนุ่มน้อย",
  ui_story_5051_50510201_175_dialog_content = "แต่ไม่ชอบธรรมที่จะแอบฟัง",
  ui_story_5051_50510201_176_dialog_content = "อย่าให้มันเกิดขึ้นอีก เข้าใจไหม?",
  ui_story_5051_50510201_177_dialog_content = "เข้าใจ ขอบคุณครับท่าน...",
  ui_story_5051_50510201_178_dialog_content = "ตอนนี้ฉันมีคำถามอื่นสำหรับคุณ",
  ui_story_5051_50510201_179_dialog_content = "อีกฝ่ายที่ซุ่มซ่อนอยู่ในเงามืดเป็นเพื่อนของคุณด้วยหรือไม่?",
  ui_story_5051_50510201_180_dialog_content = "ถ้าไม่ คุณร็อตจะขายทิ้งโดยไม่ลังเล",
  ui_story_5051_50510201_X177_dialog_content = "ถ้าอย่างนั้น ให้ฉันถามคุณอีกคำถามหนึ่ง",
  ui_story_5051_50510201_X178_dialog_content = "หนูที่ซ่อนอยู่ใต้โต๊ะเป็นเพื่อนคุณหรือเปล่า?",
  ui_story_5051_50510201_X179_dialog_content = "ถ้าไม่ฉันจะไล่มันออกไป",
  ui_story_5051_50510201_181_dialog_content = "อะฮ่าฮ่าฮ่า! S-เธอคือ!",
  ui_story_5051_50510201_182_dialog_content = "ออกมาเถอะมีอา อย่ากลัวไปเลย พวกนี้เป็นคนดี",
  ui_story_5051_50510201_183_dialog_content = "ว-เดี๋ยวก่อน! ผ้าคลุมของฉัน... ฉันหาผ้าคลุมของฉันไม่เจอ!",
