  ui_story_5051_50510201_186_dialog_content = "...",
  ui_story_5051_50510201_187_dialog_content = "นี่เป็นอีกหนึ่งความประหลาดใจของคุณสำหรับฉัน คุณร็อท?",
  ui_story_5051_50510201_188_dialog_content = "ไม่เป็นไร เคลียร์ตารางงานของฉันให้เรียบร้อยก่อนที่จะมีอะไรเกิดขึ้น",
  ui_story_5051_50510201_189_dialog_content = "ฉันขอโทษจริงๆ ท่านลอร์ด ฉันจะไปยกเลิกนัดที่เหลือของคุณในวันนี้",
  ui_story_5051_50510201_190_dialog_content = "กรุณาทำ",
  ui_story_5051_50510201_191_dialog_content = "ถ้าฉันใช้อันนี้... และรวมกับอันนี้... บิงโก!",
  ui_story_5051_50510201_192_dialog_content = "ฉันคิดว่าฉันพบคาถาที่เราต้องการแล้วตอนนี้!",
  ui_story_5051_50510201_193_dialog_content = "นั่นไม่จำเป็น กรุณากลับไปงานเลี้ยงด้วย PlayerName และสนุกกับตัวเอง",
  ui_story_5051_50510201_194_dialog_content = "เราสามคนต้องคุยกันเป็นการส่วนตัว...",
