  ui_story_5051_50510201_199_dialog_content = "อะไรใน...?",
  ui_story_5051_50510201_200_dialog_content = "<size=45>อะ-เกิดอะไรขึ้น?!</size>",
  ui_story_5051_50510201_201_dialog_content = "ช่วยฉันด้วย... PlayerName...",
  ui_story_5051_50510201_202_dialog_content = "เมียหลวง! จับมือฉัน!!",
