  ui_story_5051_50510201_236_dialog_content = "ตราบใดที่คุณสามารถใช้ Luminatics ได้ ฉันจะเพิ่มพลังให้คุณได้!",
  ui_story_5051_50510201_237_dialog_content = "เชื่อฉันและเชื่อมั่นในตัวเอง!",
  ui_story_5051_50510201_238_dialog_content = "เชื่อใจคุณ... และตัวฉันเอง?",
  ui_story_5051_50510201_239_dialog_content = "ใช้ได้! ฉันจะทำให้ดีที่สุด!",
  ui_story_5051_50510301_1_dialog_content = "ไม่เป็นไรนะ?",
  ui_story_5051_50510301_2_dialog_content = "ฉันสบายดี. แม้จะยังหวั่นไหว...",
  ui_story_5051_50510301_3_dialog_content = "ฉันคิดว่าตอนนี้ฉันมั่นใจขึ้นนิดหน่อยแล้ว!",
  ui_story_5051_50510301_4_dialog_content = "คุณไม่ได้รับบาดเจ็บในการต่อสู้ทั้งหมดใช่ไหม",
  ui_story_5051_50510301_5_dialog_content = "ไม่เลย ไม่ต้องห่วงฉัน!",
  ui_story_5051_50510301_6_dialog_content = "ฉันต้องบอกว่า Mia นั่นน่าประทับใจมาก! มีคนไม่มากที่สามารถต่อสู้กับ Eclipsites จำนวนมากได้ด้วยตัวเอง",
  ui_story_5051_50510301_7_dialog_content = "ร-จริงเหรอ? แต่ฉันคิดว่าทั้งหมดต้องขอบคุณคุณ",
  ui_story_5051_50510301_8_dialog_content = "พลังของ Last Caeleste เป็นอะไรที่...",
  ui_story_5051_50510301_9_dialog_content = "เมื่อพูดถึง ฉันไม่สามารถรับรู้ถึงใครรอบๆ ตัวเราได้เลยตั้งแต่ฉันตื่นขึ้น",
  ui_story_5051_50510301_10_dialog_content = "เราอยู่ที่ไหนบนโลก? แล้วคนอื่นไปไหนกันหมด?",
  ui_story_5051_50510301_11_dialog_content = "ดูที่นั่นในระยะไกล! ของมัน <color=#FFB400>ลูโมโพลิส</color>!",
  ui_story_5051_50510301_12_dialog_content = "นี่หมายความว่าเรากำลังอยู่บน <color=#FFB400>ชานเมืองลูโมโปลิส</color>?",
  ui_story_5051_50510301_13_dialog_content = "เรามาลงเอยที่นี่ได้อย่างไร...?",
  ui_story_5051_50510301_14_dialog_content = "นี่อาจเป็นโลกภายใน <color=#FFB400>คริสตัลแห่งความทรงจำนิรันดร์</color>?",
  ui_story_5051_50510301_15_dialog_content = "ฉันคิดว่าคุณน่าจะใช่!",
  ui_story_5051_50510301_16_dialog_content = "โฆษณาชวนเชื่อ! โฆษณาชวนเชื่อ! โฆษณาชวนเชื่อ!",
  ui_story_5051_50510301_17_dialog_content = "ย้อนอดีตวันทอง!",
  ui_story_5051_50510301_18_dialog_content = "อับราฮาดะบรา!",
  ui_story_5051_50510301_19_dialog_content = "ฉันจำได้แล้ว... ฉันเดาว่า Jakine เป็นปรมาจารย์ด้านการทำนายจริงๆ",
  ui_story_5051_50510301_20_dialog_content = "แต่ถึงอย่างนั้น ดูเหมือนว่าคราวนี้เธอนำหน้าตัวเองเกินไป",
  ui_story_5051_50510301_21_dialog_content = "นั่นสิ...",
  ui_story_5051_50510301_22_dialog_content = "ฉันจำได้ว่าเธอพูดถึงอย่างอื่นด้วย",
  ui_story_5051_50510301_23_dialog_content = "\"เมื่อเข้าไปข้างในแล้ว ผู้ใช้จะต้องซ่อนตัวและหลีกเลี่ยงการโต้ตอบกับใครหรืออะไรก็ตาม\"",
  ui_story_5051_50510301_24_dialog_content = "\"ไม่เช่นนั้น การเปลี่ยนแปลงเพียงเล็กน้อยในเนื้อเรื่องอาจส่งผลให้เกิดหายนะที่คาดไม่ถึง!\"",
  ui_story_5051_50510301_25_dialog_content = "ไม่นะ... เราเพิ่งต่อสู้กับ Eclipsites จำนวนมาก!",
  ui_story_5051_50510301_26_dialog_content = "เราจะโอเคไหม...?",
  ui_story_5051_50510301_27_dialog_content = "<size=45>อ๊าาา!!</size>",
  ui_story_5051_50510301_28_dialog_content = "S-มีคนเดือดร้อน!",
  ui_story_5051_50510301_29_dialog_content = "นั่นใครน่ะ...?",
  ui_story_5051_50510301_30_dialog_content = "กัปตัน! มี Eclipsites มากเกินไป เราทนไม่ได้อีกแล้ว...",
  ui_story_5051_50510301_31_dialog_content = "โฟกัสผู้ชาย! แม้ว่าเพื่อนทหารของคุณจะล้มลงต่อหน้าต่อตา คุณก็อย่าได้วางอาวุธลง!",
  ui_story_5051_50510301_32_dialog_content = "ด่าให้หมด!!!",
  ui_story_5051_50510301_33_dialog_content = "ยานขนส่งสินค้าที่ได้รับการปกป้องโดยทหารลูโมโปลิส... และพวกเขากำลังถูกโจมตีโดย Eclipsites!",
  ui_story_5051_50510301_34_dialog_content = "แต่ทำไมมี Eclipsites มากมายนอก Lumopolis? เกิดอะไรขึ้น?!",
  ui_story_5051_50510301_35_dialog_content = "เราจำเป็นต้องไปช่วยพวกเขา!",
  ui_story_5051_50510301_36_dialog_content = "รอ! Jakine บอกว่าเราไม่สามารถเข้าไปยุ่งเกี่ยวกับสิ่งใดได้เมื่ออยู่ใน Crystal of Eternal Memory!",
  ui_story_5051_50510301_37_dialog_content = "หากเราใช้ Eclipsites เหล่านั้น ก็ไม่มีใครบอกได้ว่าผลที่ตามมาจะเป็นอย่างไร!",
  ui_story_5051_50510301_38_dialog_content = "แต่กลับ...",
  ui_story_5051_50510301_39_dialog_content = "ต่อต้านจนกว่าเธอจะถูกลากไปลงหลุม!",
  ui_story_5051_50510301_40_dialog_content = "— ?!",
  ui_story_5051_50510301_41_dialog_content = "ตอนนี้ทหารลูโมโปลิสปลอดภัยแล้วครับ เราสามารถดึงออกได้ตลอดเวลา",
  ui_story_5051_50510301_42_dialog_content = "ฉันยังไม่เข้าใจว่าเหตุใดเราจึงช่วยสุนัขที่ซื่อสัตย์ของชวาร์ตษ์ เนื่องจากเขาไม่สนว่าเราจะอยู่หรือตาย",
  ui_story_5051_50510301_43_dialog_content = "แม้แต่ในวันหยุดแบบนี้ เขาก็ไม่ได้ให้เศษอาหารหรือที่พักกับเรามากขนาดนั้น เขาเพิ่งเอาของขวัญของเราไปและเตะพวกเราออกไป",
  ui_story_5051_50510301_44_dialog_content = "ลอร์ดเมืองแบบไหนกันนะ?",
  ui_story_5051_50510301_45_dialog_content = "อย่าปล่อยให้เรื่องเล็ก ๆ น้อย ๆ บดบังการมองเห็นของคุณ เมื่อถึงเวลาคำตอบจะชัดเจนสำหรับคุณเอง",
  ui_story_5051_50510301_46_dialog_content = "ของมัน <color=#FFB400>ลุงอิสท์วาน</color>...!",
  ui_story_5051_50510301_47_dialog_content = "เดี๋ยวก่อน นั่นคือ Istvan?! เขาดูเด็กมาก!",
  ui_story_5051_50510301_48_dialog_content = "หา...?",
  ui_story_5051_50510301_49_dialog_content = "<color=#e8d9bb>Rumble—พัง!</color>",
  ui_story_5051_50510301_50_dialog_content = "(ฟ้าร้อง ฝนจะตกกลางวันที่อากาศแจ่มใสหรือเปล่า)",
  ui_story_5051_50510301_51_dialog_content = "PlayerName! ระวัง!!",
  ui_story_5051_50510301_52_dialog_content = "อย่าบอกนะว่ายังมี Eclipsites อีก?!",
  ui_story_5051_50510301_53_dialog_content = "สัตว์ประหลาดเหล่านี้ไม่มีที่สิ้นสุด!",
  ui_story_5051_50510302_1_dialog_content = "ฮะ...ฮะ...ฮะ...",
  ui_story_5051_50510302_2_dialog_content = "ฉันหวังว่าจะไม่มีพวกเขาอีก ฉันถึงขีดจำกัดแล้ว...",
  ui_story_5051_50510302_3_dialog_content = "เจ้าหญิง <color=#FFB400>เวโรนิก้า</color>! คุณสบายดีหรือเปล่า?",
  ui_story_5051_50510302_4_dialog_content = "เจ้าหญิงเวโรนิก้า! เป็นเจ้าหญิงเวโรนิกาจริงๆ!",
  ui_story_5051_50510302_5_dialog_content = "ทำไมท่านถึงมาอยู่ที่นี่ ฝ่าบาท?!",
  ui_story_5051_50510302_6_dialog_content = "ฉัน เอ่อ ฉันสบายดี",
  ui_story_5051_50510302_7_dialog_content = "ดี",
  ui_story_5051_50510302_8_dialog_content = "แต่ฉันต้องบอกว่าการแสดงความแข็งแกร่งและความกล้าหาญนั้นไม่เหมือนคุณเลย",
  ui_story_5051_50510302_9_dialog_content = "ฉันไม่กล้ายืนยันตัวตนของคุณก่อนหน้านี้ โปรดยกโทษให้กับความโง่เขลาของข้าด้วย ฝ่าบาท",
  ui_story_5051_50510302_10_dialog_content = "พ-ได้โปรดอย่าพูดอย่างนั้น!",
  ui_story_5051_50510302_11_dialog_content = "วันนี้เป็นเพียงโอกาสพิเศษเท่านั้น",
  ui_story_5051_50510302_12_dialog_content = "(ห๊ะ? คุณกำลังมองฉันเพื่ออะไร Mia?)",
  ui_story_5051_50510302_13_dialog_content = "ฉันไม่สามารถตกลงกันได้มากกว่านี้ ซึ่งเป็นเหตุผลว่าทำไมฉันถึงสับสนกับการที่คุณออกมาที่นี่ตั้งแต่แรก",
  ui_story_5051_50510302_14_dialog_content = "แล้วอีกอย่าง... มันไม่ใช่ที่ของฉันที่จะต้องมากังวลเกี่ยวกับเรื่องแบบนี้ โปรดใช้ความระมัดระวังให้มากขึ้นเมื่อย่างเท้าออกไปนอกเมือง ฝ่าบาท",
  ui_story_5051_50510302_15_dialog_content = "Th-ขอบคุณที่เป็นห่วง",
  ui_story_5051_50510302_16_dialog_content = "ท่านลอร์ดชวาร์ตษ์กับข้าพเจ้าเพิ่งเสร็จสิ้นการประชุมเมื่อไม่นานมานี้ เรายุ่งมากจนไม่มีเวลาคุยกับเลดี้โจชัว",
  ui_story_5051_50510302_17_dialog_content = "โปรดขอโทษเธอจากใจจริงที่สุด",
  ui_story_5051_50510302_18_dialog_content = "และถ้าเป็นไปได้... โปรดขอให้พ่อของคุณตอบกลับฉันโดยเร็วที่สุด",
  ui_story_5051_50510302_19_dialog_content = "ดีมาก... ฉันจะส่งข้อความของคุณไปให้พวกเขาอย่างแน่นอน ขอขอบคุณอีกครั้งสำหรับความช่วยเหลือทั้งหมดของคุณ",
  ui_story_5051_50510302_20_dialog_content = "ฉันแค่ทำในสิ่งที่ถูกต้อง ฝ่าบาท ไม่จำเป็นต้องขอบคุณ",
  ui_story_5051_50510302_21_dialog_content = "(มีอาเป็นเจ้าหญิงจริงๆ!)",
  ui_story_5051_50510302_22_dialog_content = "ขอโทษนะพ่อหนุ่ม",
  ui_story_5051_50510302_23_dialog_content = "หืม?",
  ui_story_5051_50510302_24_dialog_content = "ใช่คุณ. ข้าได้แต่สันนิษฐานว่าท่านเป็นเพื่อนสนิทของฝ่าบาท ใช่ไหม?",
  ui_story_5051_50510302_25_dialog_content = "ไม่ใช่แค่ใครก็ตามที่สามารถอ้างสิทธิ์ในการได้รับการปกป้องจากเธอ คุณรู้ไหม",
  ui_story_5051_50510302_26_dialog_content = "คุณควรพึ่งพาพลังของตัวเองเพื่อประสบความสำเร็จในชีวิต",
  ui_story_5051_50510302_27_dialog_content = "มากกว่าที่จะหลบซ่อนอยู่เบื้องหลังคนอื่น",
  ui_story_5051_50510302_28_dialog_content = "ค-ครับ...",
  ui_story_5051_50510302_29_dialog_content = "เอ่อ ขอโทษนะ แต่เราเคยเจอที่ไหนมาก่อนรึเปล่า?",
  ui_story_5051_50510302_30_dialog_content = "ฮ่าฮ่าฮ่า! ฉันไม่คิดว่าจะได้ยินเป็นคำพูดเปิดงานของคุณ เพื่อนของฉัน",
  ui_story_5051_50510302_31_dialog_content = "คำตอบคือไม่",
  ui_story_5051_50510302_32_dialog_content = "แต่หากคุณอยากจะพบกันอีก โปรดอย่าลังเลที่จะมาหาฉันที่ Umbraton",
  ui_story_5051_50510302_33_dialog_content = "ในไม่ช้ามันจะกลายเป็นอาณาจักรแห่งเงา",
  ui_story_5051_50510302_34_dialog_content = "เงาล้อมรอบเราทุกคน แต่คุณจะอยู่รอดในนั้นได้หรือไม่นั้นขึ้นอยู่กับความแข็งแกร่งของคุณเอง",
  ui_story_5051_50510302_35_dialog_content = "เงาล้อมรอบเราทุกคน...",
  ui_story_5051_50510302_36_dialog_content = "ฉันแน่ใจว่า Umbraton จะกลายเป็นที่ที่ดีกว่ามากภายใต้การนำของคุณ ลุง... ฉันหมายถึงคุณอิสต์วาน",
  ui_story_5051_50510302_37_dialog_content = "ฉันรู้สึกเป็นเกียรติที่ได้รับคำชมเช่นนี้จากคุณ คุณหนู",
  ui_story_5051_50510302_38_dialog_content = "เริ่มจะสายแล้ว เราควรจะไปได้แล้ว",
  ui_story_5051_50510302_39_dialog_content = "จนกว่าจะพบกันใหม่ เจ้าหญิงเวโรนิกา คุณก็เช่นกัน เพื่อนสาวที่น่าสนใจของฉัน",
  ui_story_5051_50510302_40_dialog_content = "ระวังตัวด้วย... คุณรู้ไหม Istvan คนนี้ดูดีกว่าคนที่ฉันรู้จักมาก",
  ui_story_5051_50510302_41_dialog_content = "ไม่โกหก มันรู้สึกน่าสนใจทีเดียว",
  ui_story_5051_50510302_42_dialog_content = "ใช่แล้ว ฉันจำได้ว่าลุงอิสต์วานเมื่อก่อนร่าเริงกว่านี้มากเหมือนกัน",
  ui_story_5051_50510302_43_dialog_content = "แต่กับทุกเรื่องตั้งแต่นั้นมา...ไม่แปลกใจเลยว่าทำไมทุกคนถึงเปลี่ยนไปมากขนาดนี้",
  ui_story_5051_50510302_44_dialog_content = "คุณคือเจ้าหญิงเวโรนิกาจริงๆ ใช่ไหม",
  ui_story_5051_50510302_45_dialog_content = "เมื่อ Istvan เรียกคุณแบบนั้น คุณก็ตอบราวกับว่ามันเป็นเรื่องปกติที่สุดในโลก มันแตกต่างอย่างสิ้นเชิงจากการตอบสนองที่เขินอายตามปกติของคุณ",
  ui_story_5051_50510302_46_dialog_content = "จ-จริงเหรอ",
  ui_story_5051_50510302_47_dialog_content = "ฉันยังไม่สามารถปะติดปะต่อความทรงจำทั้งหมดเข้าด้วยกันได้ ตอนนี้ฉันจำได้เพียงเกร็ดเล็กเกร็ดน้อยในอดีตเท่านั้น",
  ui_story_5051_50510302_48_dialog_content = "แต่ด้วยเหตุผลบางอย่าง เมื่อฉันเห็นตัวตนที่อายุน้อยกว่าของลุงอิสต์วาน...",
  ui_story_5051_50510302_49_dialog_content = "ราวกับว่าร่างกายของฉันจำคำพูดและมารยาทที่ถูกต้องก่อนที่สมองของฉันจะตามทัน",
  ui_story_5051_50510302_50_dialog_content = "ขอโทษ ฉันรู้ว่ามันไม่สมเหตุสมผลเลย",
  ui_story_5051_50510302_51_dialog_content = "ไม่ต้องกังวลกับมัน! เรามาหาคำตอบเกี่ยวกับอดีตของคุณ และมีอะไรเกิดขึ้นมากมายเกินคาด เป็นเรื่องปกติที่คุณจะรู้สึกสับสนเล็กน้อย",
  ui_story_5051_50510302_52_dialog_content = "คุณช่วยเล่าเพิ่มเติมเกี่ยวกับเจ้าหญิงเวโรนิกาในความทรงจำของคุณได้ไหม มีอา",
  ui_story_5051_50510302_53_dialog_content = "ได้เลย ไม่มีปัญหา",
  ui_story_5051_50510302_54_dialog_content = "เวโรนิก้าเป็น <color=#FFB400>เจ้าหญิง</color> ของ Lumopolis เช่นเดียวกับของ Lord Schwartz <color=#FFB400>ลูกสาวคนโต</color>.",
  ui_story_5051_50510302_55_dialog_content = "แต่เมื่อหลายปีก่อน Lumopolis ประกาศให้คนทั้งโลกรู้ว่าเธอมี <color=#FFB400>เสียชีวิตแล้ว</color>...",
  ui_story_5051_50510302_56_dialog_content = "เสียชีวิตแล้ว? แต่ทำไม?",
  ui_story_5051_50510302_57_dialog_content = "เพราะเธอทำให้ตระกูลชวาร์ตษ์เสื่อมเสียชื่อเสียง",
  ui_story_5051_50510302_58_dialog_content = "อันเป็นผลมาจากความอัปยศของเธอ Veronica สูญเสียสิทธิ์ในการมีชีวิตอยู่ต่อไป",
  ui_story_5051_50510302_59_dialog_content = "ชื่อเสียง? ความอัปยศ? สิ่งเหล่านี้สำคัญพอที่จะทำให้ใครบางคนเสียชีวิตหรือไม่?",
  ui_story_5051_50510302_60_dialog_content = "นั่นเป็นเพียงวิธีการทำงานของขุนนาง สำหรับพวกเขา ไม่มีอะไรสำคัญไปกว่าการรักษาชื่อเสียง...",
  ui_story_5051_50510302_61_dialog_content = "คุณรู้เกี่ยวกับ <color=#FFB400>ลูมิน่า ซัมม่อน</color>, ขวา PlayerName?",
  ui_story_5051_50510302_62_dialog_content = "นอกจาก Baba Yaga แล้ว ฉันจำได้ว่ามีเพื่อนที่น่ากลัวอีกคนหนึ่งชื่อฮิปโปคา",
  ui_story_5051_50510302_63_dialog_content = "เขาเป็นผู้อัญเชิญ Lumina ของฉัน ตอนเป็นเด็ก ฉันอยากแข็งแกร่งขึ้นมากกว่าสิ่งอื่นใด ฉันจึงฝึกฝนและฝึกฝนให้หนักที่สุดเท่าที่จะทำได้...",
  ui_story_5051_50510302_64_dialog_content = "และผลลัพธ์ของการฝึกของฉันคือฮิปโปคา",
  ui_story_5051_50510302_65_dialog_content = "แต่ทุกคนไม่ชอบวิธีที่เขามอง แมงมุมหัวเป็นม้า... ใครๆ ก็เรียกเขาว่าสัตว์ประหลาด",
  ui_story_5051_50510302_66_dialog_content = "แต่คนที่เกลียดเขาที่สุด...คือพ่อของฉัน เขามักจะพูดเสมอว่าฮิปโปคาวิจารณ์ครอบครัวของเราอย่างไม่มีเหตุผล",
  ui_story_5051_50510302_67_dialog_content = "ฮิปโปคานั้นเป็นลางร้ายและไม่ควรมีอยู่จริง... ไม่นานนัก ฉันก็เริ่มกลัวเขาเช่นกัน",
  ui_story_5051_50510302_68_dialog_content = "ฮิปโปคาเป็นการแสดงพลังของฉันเอง แต่ฉันก็ปฏิเสธเขาเพราะทุกคนไม่ยอมรับ",
  ui_story_5051_50510302_69_dialog_content = "ในที่สุดฉันก็สูญเสียความสามารถในการใช้ Luminatics",
  ui_story_5051_50510302_70_dialog_content = "และบาบายากะซึ่งมีความคล้ายคลึงกันบางอย่างกับฮิปโปคาก็สืบทอดอำนาจของฉันแทน",
  ui_story_5051_50510302_71_dialog_content = "ในทางหนึ่ง ฉันได้รับสิ่งที่สมควรได้รับ",
  ui_story_5051_50510302_72_dialog_content = "เจ้าหญิงเวโรนิก้าผู้น่าสงสาร...",
  ui_story_5051_50510302_73_dialog_content = "แต่เนื่องจากทุกคนที่นี่ยังคงเรียกคุณด้วยชื่อนั้น หมายความว่า...",
  ui_story_5051_50510302_74_dialog_content = "ฝ่าบาท! เราจะตอบแทนท่านที่ช่วยชีวิตพวกเราได้อย่างไร?",
  ui_story_5051_50510302_75_dialog_content = "ฉัน-มันไม่มีอะไรจริงๆ",
  ui_story_5051_50510302_76_dialog_content = "ทุกคนสบายดีไหม",
  ui_story_5051_50510302_77_dialog_content = "ทำใจให้สบายเถิดท่านเจ้าคุณ ต้องขอบคุณคุณ เราได้รับบาดเจ็บเล็กน้อยเท่านั้น และพร้อมที่จะดำเนินการต่อได้ทุกเมื่อ",
  ui_story_5051_50510302_78_dialog_content = "คุณและเพื่อนของคุณสามารถนั่งรถกลับเมืองกับเราได้ ถ้าคุณต้องการ?",
  ui_story_5051_50510302_79_dialog_content = "นั่นคงจะวิเศษมาก ขอบคุณ",
  ui_story_5051_50510302_80_dialog_content = "เอ่อ ขอโทษนะ แต่บอกฉันได้ไหมว่าเป็นปีอะไร?",
  ui_story_5051_50510302_81_dialog_content = "ปีอะไร? ของมัน <color=#FFB400>ปฏิทินภาคเช้า ปี 2531</color>. คุณถามทำไม?",
  ui_story_5051_50510302_82_dialog_content = "(1988? แปลว่า... นี่คือ <color=#FFB400>สิบสองปีที่ผ่านมา</color>!)",
  ui_story_5051_50510302_83_dialog_content = "(ถ้าเป็นเช่นนั้น Eraveil คงจะถูกทำลายไปแล้ว)",
  ui_story_5051_50510302_84_dialog_content = "(นั่นหมายความว่าฉันยังคงไม่พบญาติของฉันใน Crystal of Eternal Memory นี้...)",
  ui_story_5051_50510302_85_dialog_content = "มีอะไรบางอย่างผิดปกติ, PlayerName?",
  ui_story_5051_50510302_86_dialog_content = "ไม่เป็นไร. มีอา คุณช่วยมาที่นี่สักครู่ได้ไหม",
  ui_story_5051_50510302_87_dialog_content = "อะ-อะไรนะ?",
  ui_story_5051_50510302_88_dialog_content = "ดูเหมือนว่าโลกภายในคริสตัลจะเป็น <color=#FFB400>ลูโมโปลิสเมื่อสิบสองปีที่แล้ว</color>.",
  ui_story_5051_50510302_89_dialog_content = "ถ้าลางสังหรณ์ของฉันถูกต้อง คนอื่นๆ ที่อยู่ในห้องรับแขกกับเราก็น่าจะถูกเคลื่อนย้ายมาที่นี่เช่นกัน",
  ui_story_5051_50510302_90_dialog_content = "ฉันรู้ว่า Jakine บอกว่าเราไม่ควรยุ่งเกี่ยวกับโลกรอบตัวเรา",
  ui_story_5051_50510302_91_dialog_content = "แต่ฉันไม่คิดว่าเรามีทางเลือก เราไม่มีทางซ่อนตัวอยู่ที่นี่อีกต่อไป และฉันไม่สามารถสัมผัสถึงคนอื่นๆ ด้วยความสามารถทางจิตของฉัน",
  ui_story_5051_50510302_92_dialog_content = "เราควรใช้สถานะของคุณในฐานะเจ้าหญิงเพื่อค้นหาพวกเขาและหาทางกลับ",
  ui_story_5051_50510302_93_dialog_content = "...",
  ui_story_5051_50510302_94_dialog_content = "เกิดอะไรขึ้นมีอา?",
  ui_story_5051_50510302_95_dialog_content = "อืม PlayerName?",
  ui_story_5051_50510302_96_dialog_content = "ด-จะดีไหมถ้าฉันไปหาแม่เป็นครั้งสุดท้ายก่อนที่เราจะจากไป?",
  ui_story_5051_50510302_97_dialog_content = "ก่อนหน้านี้ตอนที่ฉันซ่อนตัวอยู่ใต้โต๊ะ ฉันได้ยินพวกเขาพูดว่าเธอเสียชีวิตแล้วขณะที่ฉันไม่อยู่",
  ui_story_5051_50510302_98_dialog_content = "ฉันอยากกลับไปที่ลูโมโปลิสเพื่อพบเธอและน้องสาวตัวน้อยของฉัน ฉันมีหลายอย่างที่อยากแบ่งปันกับพวกเขา",
  ui_story_5051_50510302_99_dialog_content = "ฉันต้องการแสดงให้พวกเขาเห็นว่าฉันโตขึ้นและกล้าหาญกว่าเมื่อก่อน และบอกพวกเขาเกี่ยวกับเพื่อนที่ฉันสร้างนอกเมือง",
  ui_story_5051_50510302_100_dialog_content = "และ... อยากบอกแม่ว่าคิดถึงแม่ทุกวัน...",
  ui_story_5051_50510302_101_dialog_content = "แต่มันสายเกินไป",
  ui_story_5051_50510302_102_dialog_content = "... แม่ของคุณเป็นภรรยาของ City Lord",
  ui_story_5051_50510302_103_dialog_content = "หากเราหาเธอพบ ฉันมั่นใจว่าเธอจะต้องช่วยให้เรากลับสู่โลกแห่งความเป็นจริงได้!",
  ui_story_5051_50510302_104_dialog_content = "การไปเยี่ยมเธอจะเป็นผลประโยชน์สูงสุดของทุกคนใช่ไหม?",
  ui_story_5051_50510302_105_dialog_content = "เอ่อ PlayerName? ดูเหมือนว่าคุณกำลังบิดสิ่งต่าง ๆ เพื่อให้เป็นประโยชน์กับเรา ...",
  ui_story_5051_50510302_106_dialog_content = "หึหึหึ แต่มันก็สมเหตุสมผลดีไม่ใช่เหรอ?",
  ui_story_5051_50510302_107_dialog_content = "คุณสามารถขอบคุณเพื่อนๆ ของเราทุกคนบน Colossus ที่สอนฉันถึงวิธีการทำสิ่งนี้!",
  ui_story_5051_50510302_108_dialog_content = "โอเค งั้นฉันจะตามนายไป",
  ui_story_5051_50510302_109_dialog_content = "อย่างใด มันรู้สึกเหมือนฉันกำลังเป็นตัวอย่างที่ไม่ดีสำหรับคุณ มีอา...",
  ui_story_5051_50510302_110_dialog_content = "ขอโทษนะ แต่... คุณพร้อมจะไปหรือยัง? เรามีตารางงานที่แน่นเอี๊ยด",
  ui_story_5051_50510302_111_dialog_content = "อ่า ขออภัยด้วย! เราพร้อมไปเมื่อคุณพร้อม!",
  ui_story_5051_50510302_112_dialog_content = "ดูเหมือนว่าทีมของคุณกำลังรีบ คุณบอกเราได้ไหมว่าคุณกำลังขนส่งอะไร",
  ui_story_5051_50510302_113_dialog_content = "ไม่มีอะไรละเอียดอ่อนเป็นพิเศษ เป็นเพียงรายการพิเศษบางอย่างที่ต้องจัดส่งล่วงหน้า ได้แก่...",
  ui_story_5051_50510302_114_dialog_content = "สิ่งของที่จำเป็นสำหรับปีนี้ <color=#FFB400>วันครอบครัวชวาร์ตษ์</color>.",
  ui_story_5051_50510302_115_dialog_content = "(วันครอบครัว Schwartz นั่นเป็นเรื่องบังเอิญมากเกินไปหน่อย)",
  ui_story_5051_50510302_116_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_5051_50510302_117_dialog_content = "ฟ้าร้องอีก...",
  ui_story_5051_50510302_118_dialog_content = "มีอะไรหรือเปล่า",
  ui_story_5051_50510302_119_dialog_content = "ไม่มีอะไร. เราควรไปก่อนฝนจะตก!",
  ui_story_5051_50510302_120_dialog_content = "ฝน? ฉันไม่นึกเลยว่าวันนี้ฝนจะตก ยังไงพวกเราก็จะออกเดินทางทันที",
  ui_story_5051_50510302_121_dialog_content = "<anim type=Shake><size=32>...ช...</size></anim>",
  ui_story_5051_50510302_122_dialog_content = "<anim type=Shake><size=32>... ชวาตส์...</size></anim>",
  ui_story_5051_50510302_123_dialog_content = "<anim type=Shake><size=32>...</size></anim>",
  ui_story_5051_50510402_1_dialog_content = "...",
  ui_story_5051_50510402_2_dialog_content = "อืม... มี Eclipsites แฝงตัวอยู่ในสถานที่แบบนี้ด้วย",
  ui_story_5051_50510402_3_dialog_content = "Lumopolis กลายเป็นแหล่งเพาะพันธุ์ของเหล่าสัตว์ประหลาดตั้งแต่เมื่อไหร่?",
  ui_story_5051_50510402_4_dialog_content = "วุ้ย ฉันรอดแล้ว!",
  ui_story_5051_50510402_5_dialog_content = "ขอบคุณ คุณคาเลบ! ถ้าไม่ใช่เพราะคุณปรากฏตัวเร็ว ๆ นี้ ฉันคงอดกินอาหารเย็นสำหรับ Eclipsites พวกนั้น...",
  ui_story_5051_50510402_6_dialog_content = "ไม่ เดี๋ยวก่อน ทำอาหารกลางวันให้! มันยังเป็นเวลากลางวันอยู่",
  ui_story_5051_50510402_7_dialog_content = "ฉันสับสนเล็กน้อยเกี่ยวกับเรื่องนี้เช่นกัน",
  ui_story_5051_50510402_8_dialog_content = "เห็นได้ชัดว่าเป็นเวลากลางคืนที่เรายังกลับมาที่วัง คุณจาคิน",
  ui_story_5051_50510402_9_dialog_content = "แต่ตอนนี้เป็นเวลากลางวันแล้ว เราพบว่าตัวเองอยู่กลางป่า",
  ui_story_5051_50510402_10_dialog_content = "เป็นไปได้ไหมว่าเราถูกส่งไปยัง Crystal of Eternal Memory?",
  ui_story_5051_50510402_11_dialog_content = "ถูกตัอง! แม้ว่าพูดตามตรง ฉันไม่คิดว่าการร่ายมนตร์หลายๆ ครั้งพร้อมกันจะได้ผลดีขนาดนี้!",
  ui_story_5051_50510402_12_dialog_content = "บางทีฉันอาจจะเป็นอัจฉริยะก็ได้...",
  ui_story_5051_50510402_13_dialog_content = "(โอ้ ใช่ มีเพียงอัจฉริยะเท่านั้นที่สามารถทำสิ่งนี้ได้...)",
  ui_story_5051_50510402_14_dialog_content = "พิจารณาจากสิ่งก่อสร้างเหล่านั้นในระยะไกล ดูเหมือนว่าเราอยู่ที่ไหนสักแห่งในเขตชานเมืองของลูโมโพลิสตอนล่าง",
  ui_story_5051_50510402_15_dialog_content = "ส่วนลังนั้นที่คุณนั่งทับมัน—",
  ui_story_5051_50510402_16_dialog_content = "ฉลากระบุว่าจัดทำขึ้นเฉพาะสำหรับ Schwartz Family Day",
  ui_story_5051_50510402_17_dialog_content = "ใช่และตอนนี้ฉันกลัวโง่!",
  ui_story_5051_50510402_18_dialog_content = "มันดูแข็งแรงพอควร แต่เมื่อฉันลงน้ำหนักลงไป มันพังทันที!",
  ui_story_5051_50510402_19_dialog_content = "ฉันจะรู้ได้อย่างไรว่า Eclipsites จำนวนมากกำลังจะหมดลง!",
  ui_story_5051_50510402_20_dialog_content = "เกิดอะไรขึ้นแถวนี้? อย่าบอกนะว่าคนในลูโมโปลิสชอบเลี้ยงของพวกนี้เป็นสัตว์เลี้ยง?!",
  ui_story_5051_50510402_21_dialog_content = "ฉันรับรองกับคุณได้ว่าคนของฉันไม่สนใจที่จะเลี้ยงสัตว์ที่มีความรุนแรงและไร้สติแบบนี้อย่างแน่นอน",
  ui_story_5051_50510402_22_dialog_content = "Eclipsites จัดทำขึ้นสำหรับ Schwartz Family Day เท่านั้น... ฉันเข้าใจแล้ว นี่ต้องเป็นลูโมโพลิสเมื่อสิบสองปีที่แล้ว",
  ui_story_5051_50510402_23_dialog_content = "การเก็บลัง Eclipsites ในการขนส่งที่เต็มไปด้วยสินค้าสำหรับตระกูล Schwartz... การดำเนินการอย่างกล้าหาญในส่วนของผู้ร้ายที่อยู่เบื้องหลังการโจมตีครั้งนี้",
  ui_story_5051_50510402_24_dialog_content = "เดี๋ยวก่อน... นั่นหมายความว่า Eclipsites สามารถบุก Lumopolis เมื่อ 12 ปีก่อนได้หรือไม่?",
  ui_story_5051_50510402_25_dialog_content = "ถูกตัอง. ในขณะที่ฉันไม่รู้แน่ชัดว่าคนทั้งโลกมองป้อมปราการของเราบนท้องฟ้าอย่างไร...",
  ui_story_5051_50510402_26_dialog_content = "ในความเป็นจริง มันไม่ได้เกือบจะผ่านไม่ได้อย่างที่เห็น",
  ui_story_5051_50510402_27_dialog_content = "เอ่อ คุณคาเลบ...",
  ui_story_5051_50510402_28_dialog_content = "คุณบังเอิญเจอคนอื่นก่อนที่เราจะบังเอิญเจอกันหรือเปล่า?",
  ui_story_5051_50510402_29_dialog_content = "ไม่ อันที่จริง ฉันเพิ่งตื่นตอนที่เส้นทางของเราตัดกัน",
  ui_story_5051_50510402_30_dialog_content = "โอ้. ฮ่าฮ่าฮ่า... อืม คาถาควรจะเทเลพอร์ตพวกเราทั้งหมดไปที่เดียวกัน",
  ui_story_5051_50510402_31_dialog_content = "ยิ่งไปกว่านั้น Eclipsites ที่นี่ไม่น่าจะสังเกตเห็นเรา",
  ui_story_5051_50510402_32_dialog_content = "ดูเหมือนว่าฉันจะทำผิดพลาดเล็กน้อย!",
  ui_story_5051_50510402_33_dialog_content = "... คุณจาคีน ฉันรู้สึกว่าฉันต้องถามอะไรคุณสักอย่าง",
  ui_story_5051_50510402_34_dialog_content = "อะแฮ่ม! แต่ไม่ต้องกังวล! ฉันจะรับผิดชอบอย่างเต็มที่และทำให้แน่ใจว่าทุกคนกลับมาอย่างปลอดภัย!",
  ui_story_5051_50510402_35_dialog_content = "นั่นไม่ใช่สิ่งที่ฉันกำลังจะถาม",
  ui_story_5051_50510402_36_dialog_content = "Lumina ของผู้ที่เปิดใช้งาน Crystal of Eternal Memory นี้... อยู่ที่ไหนสักแห่งที่นี่?",
  ui_story_5051_50510402_37_dialog_content = "ใช่แน่นอน!",
  ui_story_5051_50510402_38_dialog_content = "คุณรู้หรือไม่ว่าที่ไหนกันแน่?",
  ui_story_5051_50510402_39_dialog_content = "Y-คุณอยากรู้ว่ามันอยู่ที่ไหน? ให้ฉันดู...",
  ui_story_5051_50510402_40_dialog_content = "\"คริสตัลแห่งความทรงจำชั่วนิรันดร์ต้องเปิดใช้งานด้วย Lumina ของเจ้าของ มันเป็นแหล่งพลังงานที่รักษาโลกภายในคริสตัล\"",
  ui_story_5051_50510402_41_dialog_content = "<size=30>แค่นั้นจริงๆเหรอ?!</size>",
  ui_story_5051_50510402_42_dialog_content = "อะแฮ่ม! ในความเห็นมืออาชีพของฉัน Lumina ที่ใช้ขับเคลื่อนโลกทั้งใบน่าจะอยู่ในตำแหน่งที่สำคัญอย่างยิ่ง!",
  ui_story_5051_50510402_43_dialog_content = "และสถานที่ที่สำคัญที่สุดที่ฉันนึกออก—",
  ui_story_5051_50510402_44_dialog_content = "—เป็นคริสตัลแห่งความทรงจำชั่วนิรันดร์ในโลกนี้!",
  ui_story_5051_50510402_45_dialog_content = "ผมว่าก็ฟังดูมีเหตุผลนะ...",
  ui_story_5051_50510402_46_dialog_content = "ฉันมีคำถามอื่น ถ้าลูมิน่าเป็นสิ่งที่ค้ำจุนโลกนี้ไว้ สักวัน มันก็ต้องหมดลงเป็นธรรมดา จริงไหม?",
  ui_story_5051_50510402_47_dialog_content = "เป็นเวลาสิบสองปีแล้วที่คริสตัลนี้ถูกเปิดใช้งาน มันมีเวลาอีกนานแค่ไหน?",
  ui_story_5051_50510402_48_dialog_content = "โอ้ ไม่ต้องกังวลเรื่องนั้น!",
  ui_story_5051_50510402_49_dialog_content = "ตราบใดที่คริสตัลถูกเติมเต็มด้วยน้ำจาก Lake Mirror ทุกๆ 12 ปี Lumina ของมันจะไม่จางหายไปนานแสนนาน!",
  ui_story_5051_50510402_50_dialog_content = "อย่างไรก็ตาม การเข้าไปแก้ไขระเบียบของสิ่งต่างๆ ในโลกของคริสตัลสามารถเร่งการใช้ Lumina ของมันได้อย่างง่ายดาย",
  ui_story_5051_50510402_51_dialog_content = "ในกรณีที่รุนแรง การกระทำเพียงครั้งเดียวอาจทำให้ Lumina หมดพลังงานในทันที",
  ui_story_5051_50510402_52_dialog_content = "ถ้าอย่างนั้นรับรองไม่รอดแน่!",
  ui_story_5051_50510402_53_dialog_content = "นี่คือสิ่งที่คุณหมายถึง \"ภัยพิบัติที่ไม่อาจจินตนาการได้\" หรือไม่?",
  ui_story_5051_50510402_54_dialog_content = "ใช่มากหรือน้อย ตามธรรมชาติแล้ว อาจมีผลกระทบที่ไม่คาดคิดอื่นๆ ตามมาเช่นกัน...",
  ui_story_5051_50510402_55_dialog_content = "ดังนั้นเราจึงต้องหาคนอื่นทันที!",
  ui_story_5051_50510402_56_dialog_content = "เราไม่สามารถอยู่ในที่ที่เราไม่สามารถซ่อนตัวได้นาน",
  ui_story_5051_50510402_57_dialog_content = "คุณพูดถูก นั่นเป็นเหตุผลที่ฉันทิ้งงานสำคัญนี้ไว้ในมือ \"ที่มีความสามารถ\" ของคุณ มิสจาคิน",
  ui_story_5051_50510402_58_dialog_content = "ฉันมีเรื่องอื่นที่ต้องจัดการ ขอให้โชคดี",
  ui_story_5051_50510402_59_dialog_content = "ฮะ?! เดี๋ยวก่อน คุณจะโยนสิ่งนี้ใส่ฉันแล้วปล่อยไว้แบบนั้นไม่ได้!",
  ui_story_5051_50510402_60_dialog_content = "อีกอย่างฉันเพิ่งบอกว่าต้องระวังไม่ใช่เหรอ? การเปลี่ยนแปลงแม้แต่สิ่งเล็กน้อยที่สุดในโลกนี้อาจสร้างหายนะให้กับพวกเราทุกคน!",
  ui_story_5051_50510402_61_dialog_content = "คุณทำได้ และฉันไม่มีเจตนาที่จะละเมิดกฎ อย่างไรก็ตาม ส่วนที่เหลือต้องการการดูแลอย่างใกล้ชิดจากคุณ",
  ui_story_5051_50510402_62_dialog_content = "Lumina ยังหลงเหลืออยู่ในโลกนี้ ฉันอยากจะเก็บไว้อย่างนั้นจนกว่าเราจะปลอดภัย",
  ui_story_5051_50510402_63_dialog_content = "เอ่อ คุณไม่ได้ฟังเหรอ คุณพูดเอง: นี่คือ Lumopolis! คุณจะทำอย่างไรถ้าคุณพบเจอกับตัวตนในอดีตของคุณ!",
  ui_story_5051_50510402_64_dialog_content = "ไม่ต้องกังวลเกี่ยวกับเรื่องนั้น ในวันนี้ ฉันพาหลานสาวของฉันไปที่ Umbraton พร้อมกับอัศวินของเราจำนวนหนึ่ง ฉันไม่ได้อยู่ใกล้เมือง",
  ui_story_5051_50510402_65_dialog_content = "แน่นอนว่าระยะของ Crystal of Eternal Memory นั้นไปไม่ถึงขนาดนั้น?",
  ui_story_5051_50510402_66_dialog_content = "อืม ถูก...",
  ui_story_5051_50510402_67_dialog_content = "ฉันวางแผนที่จะเข้าเมืองโดยปลอมตัวเป็นแขก ฉันจะมาหาเธอเมื่อฉันมีโอกาสเจอใครซักคน",
  ui_story_5051_50510402_68_dialog_content = "คุณยอมเสี่ยงทั้งชีวิตเพื่อเจอคนๆ นี้เหรอ?",
  ui_story_5051_50510402_69_dialog_content = "แม่นยำ. แม้ว่าเราจะไม่สามารถย้อนกลับไปสู่อดีตได้อย่างแท้จริง แต่เรามีโอกาสที่จะได้สิ่งที่สูญเสียไปกลับคืนมาบ่อยแค่ไหน?",
  ui_story_5051_50510402_70_dialog_content = "โปรดรวบรวมคนอื่นๆ ให้เร็วที่สุดเท่าที่จะทำได้ คุณจาคีน ลา.",
  ui_story_5051_50510402_71_dialog_content = "รอ! คุณยังไม่ได้บอกฉันด้วยซ้ำว่าเราจะพบกันที่ไหนในภายหลัง!",
  ui_story_5051_50510402_72_dialog_content = "หวัดดี เขาไปแล้ว...",
  ui_story_5051_50510402_73_dialog_content = "เกิดอะไรขึ้นกับคนที่สุภาพเรียบร้อยและเป็นสุภาพบุรุษ? มันเป็นเพียงการแสดงหรือไม่?",
  ui_story_5051_50510402_74_dialog_content = "เขาจะเห็นแก่ตัวและไม่เกรงใจใครในเวลาแบบนี้ได้อย่างไร!",
  ui_story_5051_50510402_75_dialog_content = "Ahhh—ฉันบ้าจนแทบสำลัก!",
  ui_story_5051_50510402_76_dialog_content = "เฮ้อ... \"ได้โอกาสทวงของที่เสียไปคืน\" เหรอ?",
  ui_story_5051_50510402_77_dialog_content = "ฉันสงสัยว่าฉันจะได้รับโอกาสแบบนั้นด้วยเหรอ?",
  ui_story_5051_50510402_78_dialog_content = "แม่... เมื่อ 12 ปีก่อน คุณมาที่ลูโมโปลิสเพื่อมอบคริสตัลแห่งความทรงจำชั่วนิรันดร์นี้ให้กับเจ้าเมือง จากนั้นคุณก็ตรงกลับไปที่นอร์ธแลนด์",
  ui_story_5051_50510402_79_dialog_content = "พ่อพูดเสมอว่าเขาไม่มีวันเข้าใจคุณ ทิ้งครอบครัวไว้เบื้องหลังเพื่อฝึกฝนการทำนาย วิ่งขึ้นภูเขาโดยไม่ได้ร่ำลา",
  ui_story_5051_50510402_80_dialog_content = "แต่สมเด็จบอกว่าท่านเป็นอัจฉริยะและอยู่เหนือข้อจำกัดทางโลกของเรา... ในแง่นั้น ข้าเดาว่าเราไม่มีอะไรเหมือนกัน",
  ui_story_5051_50510402_81_dialog_content = "ฉันสงสัยว่าคุณจะพูดอะไรถ้าเราเจอกันที่นี่?",
  ui_story_5051_50510402_82_dialog_content = "...อ้าว นี่ฉันคิดอะไรอยู่เนี่ย?!",
  ui_story_5051_50510402_83_dialog_content = "โฟกัส จาคีน! คุณมาที่นี่ในฐานะทูตของนอร์ธแลนด์ จำได้ไหม?",
  ui_story_5051_50510402_84_dialog_content = "คุณไม่สามารถพึ่งพาใครได้นอกจากตัวคุณเองในตอนนี้! เป็นหน้าที่ของคุณที่จะต้องพาทุกคนออกจากที่นี่อย่างปลอดภัย!",
  ui_story_5051_50510402_85_dialog_content = "*หายใจเข้าลึก ๆ*",
  ui_story_5051_50510402_86_dialog_content = "ใช้ได้! Jakine ทูตแห่ง Northland พร้อมแล้ว!",
  ui_story_5051_50510501_1_dialog_content = "(มีสถานที่ไม่มากนักที่ Schwartz สามารถซ่อน Crystal of Eternal Memory ได้ ถ้าฉันพูดถูก มันควรจะอยู่ที่ไหนสักแห่งในบ้านของเขา)",
  ui_story_5051_50510501_2_dialog_content = "(งานเลี้ยงวันครอบครัวปีนี้มีขนาดใหญ่กว่ามาก ดังนั้นทหารยามส่วนใหญ่จึงถูกส่งไปประจำการที่นั่นเพื่อช่วยรักษาความสงบเรียบร้อย)",
  ui_story_5051_50510501_3_dialog_content = "(เมื่อพิธีวันหยุดเริ่มขึ้น ฉันควรจะแอบเข้าไปในพื้นที่ที่มีการป้องกันน้อย)",
  ui_story_5051_50510501_4_dialog_content = "(จนกว่าจะถึงตอนนั้น ฉันแค่ต้องเก็บรายละเอียดไว้เล็กน้อยและรออย่างอดทน)",
  ui_story_5051_50510501_5_dialog_content = "(สวนตรงนั้นน่าจะว่างพอสมควร...)",
  ui_story_5051_50510501_6_dialog_content = "(ดอกไอริส... สัญลักษณ์ของข่าวดีและความปรารถนาดี)",
  ui_story_5051_50510501_7_dialog_content = "(ฉันจำได้ว่าพี่สาวของฉันปลูกมันไว้สำหรับลูกสาวคนโตของเธอเท่านั้น)",
  ui_story_5051_50510501_8_dialog_content = "... ฉันรู้ว่าเวลาของคุณใกล้จะหมดลงแล้ว เด็กๆ",
  ui_story_5051_50510501_9_dialog_content = "แต่คุณช่วยเก็บดอกไม้ของคุณไว้อีกสองสามวันได้ไหม",
  ui_story_5051_50510501_10_dialog_content = "ลูกสาวของฉันจะกลับบ้านเร็ว ๆ นี้ ฉันชอบมากถ้าเธอมีโอกาสได้เห็นความงามของคุณ",
  ui_story_5051_50510501_11_dialog_content = "เธอเคยชอบดอกไม้มาก ฉันแน่ใจว่าเธอจะยิ้มอีกครั้งเมื่อเห็นคุณ",
  ui_story_5051_50510501_12_dialog_content = "ใช่... ใช่คุณจริงๆหรือเปล่า...?",
  ui_story_5051_50510501_13_dialog_content = "<color=#FFB400>โจชัว</color>...?",
  ui_story_5051_50510501_14_dialog_content = "โอ้!",
  ui_story_5051_50510501_15_dialog_content = "สวัสดีทำไมคุณนาย",
  ui_story_5051_50510501_16_dialog_content = "อะไรนำคุณมาที่สวนของฉันในช่วงบ่ายที่น่ารักนี้",
  ui_story_5051_50510501_17_dialog_content = "เอ่อ ขอโทษที่ถาม แต่...",
  ui_story_5051_50510501_18_dialog_content = "เราเคยเจอกันมาก่อนเหรอ?",
  ui_story_5051_50510501_19_dialog_content = "... ฉันเกรงว่าจะไม่. ฉันเป็นแค่ขุนนางชั้นต่ำ ไม่สมควรได้รับเกียรติเช่นนี้",
  ui_story_5051_50510501_20_dialog_content = "แต่ถึงอย่างนั้น ก็ยินดีที่ได้พบคุณ เลดี้โจชัว",
  ui_story_5051_50510501_21_dialog_content = "งั้นเหรอ",
  ui_story_5051_50510501_22_dialog_content = "ฉันสาบานได้... ไม่เป็นไร สายตาของฉันต้องหลอกฉันแน่ๆ",
  ui_story_5051_50510501_23_dialog_content = "(โจชัว...)",
  ui_story_5051_50510501_24_dialog_content = "(ฉันแค่โกหกหมอดูชาวเหนือคนนั้นว่าเจอใครซักคน)",
  ui_story_5051_50510501_25_dialog_content = "(ที่จริงฉันไม่เคยคิดว่าจะได้พบคุณที่นี่)",
  ui_story_5051_50510501_26_dialog_content = "(หลังจากสิบสองปี ในที่สุดฉันก็มีโอกาสได้คุยกับคุณอีกครั้ง)",
  ui_story_5051_50510501_27_dialog_content = "(และถึงกระนั้น ฉันทำได้ในขณะที่แสร้งทำเป็นคนแปลกหน้าเท่านั้น...)",
  ui_story_5051_50510501_28_dialog_content = "(ฉันมาที่โลกนี้เพื่อทวงคืน Lumina น้องสาวของฉันที่ทิ้งเอาไว้)",
  ui_story_5051_50510501_29_dialog_content = "(ทั้งหมดนี้เป็นเพียงภาพลวงตาที่สร้างขึ้นโดยเล่ห์ลับของนอร์ธแลนด์ ฉันไม่สามารถปล่อยให้มันหันเหความสนใจจากเป้าหมายของฉันได้)",
  ui_story_5051_50510501_30_dialog_content = "(ฉันต้องยุติเรื่องตลกนี้ให้สิ้นซาก...!)",
  ui_story_5051_50510501_31_dialog_content = "คุณสบายดีหรือเปล่า? คุณดูราวกับว่าคุณกำลังเจ็บปวด...",
  ui_story_5051_50510501_32_dialog_content = "ต้องขออภัยด้วย",
  ui_story_5051_50510501_33_dialog_content = "ฉันแค่ไม่เชื่อในความโชคดีของตัวเองที่ฉันได้รับพรที่มีโอกาสได้พบคุณ",
  ui_story_5051_50510501_34_dialog_content = "ของฉัน นั่นเป็นเรื่องโกหกที่ประจบสอพลอทีเดียว",
  ui_story_5051_50510501_35_dialog_content = "น้ำตาที่มุมตาของคุณบอกเป็นอย่างอื่น คุณกำลังทำร้ายที่ไหนสักแห่งโดยบังเอิญหรือไม่? หรือบางทีความเจ็บปวดของคุณอาจอยู่ในหัวใจของคุณ?",
  ui_story_5051_50510501_36_dialog_content = "คุณไม่ควรแบกรับทั้งหมดไว้คนเดียว คุณรู้ไหม",
  ui_story_5051_50510501_37_dialog_content = "...",
  ui_story_5051_50510501_38_dialog_content = "ฉันบอกว่าฉันสบายดี!",
  ui_story_5051_50510501_39_dialog_content = "ฉันแค่มีอะไรเข้าตา!",
  ui_story_5051_50510501_40_dialog_content = "พวกเขารู้อะไรอีกบ้าง... ทุกคนในสถาบันนั้นงี่เง่า! อาจารย์ นักศึกษา ทุกคน!",
  ui_story_5051_50510501_41_dialog_content = "มักพูดทำนองว่า \"คุณอาจจะฉลาดนะ คาเลบ แต่ถ้าไม่มีพ่อแม่ คุณจะกลายเป็นคนที่หยิ่งยโสและหยิ่งยโส!\"",
  ui_story_5051_50510501_42_dialog_content = "<size=30>ถ้าฉันไม่มีพ่อแม่แล้วจะเป็นอย่างไร คนเดียวที่ฉันต้องการคือน้องสาวของฉัน...</size>",
  ui_story_5051_50510501_43_dialog_content = "สักวันฉันจะเปลี่ยนทุกอย่างเกี่ยวกับที่นี่! แค่คุณรอ!",
  ui_story_5051_50510501_44_dialog_content = "ฉันเชื่อในตัวคุณ คาเลบ",
  ui_story_5051_50510501_45_dialog_content = "คุณไม่เคยเป็นคนที่คุยโม้ ฉันรู้ว่าคุณสามารถทำทุกอย่างที่คุณตั้งใจให้สำเร็จได้",
  ui_story_5051_50510501_46_dialog_content = "คุณเชื่อในตัวฉันจริงๆเหรอ?",
  ui_story_5051_50510501_47_dialog_content = "แน่นอนฉันทำ.",
  ui_story_5051_50510501_48_dialog_content = "ขอบคุณ... บอกฉันหน่อย โจชัว หากมีวันที่ไม่มีใครต้องมากังวลเรื่องอาหารการกินหรือความปลอดภัยอีกต่อไป...",
  ui_story_5051_50510501_49_dialog_content = "หมายความว่าคุณจะไม่ต้องช่วยดาเนียลอีกต่อไป?",
  ui_story_5051_50510501_50_dialog_content = "อืม... ถึงมันจะเป็นเรื่องจริงที่ชีวิตของพวกเราจะเรียบง่ายกว่านี้มากหากเป็นแบบนั้น ฉันมีหน้าที่ที่จะต้องอยู่กับเขา เขาเป็นสามีของฉันหลังจากทั้งหมด",
  ui_story_5051_50510501_51_dialog_content = "...",
  ui_story_5051_50510501_52_dialog_content = "แต่ถ้าวันนั้นมาถึง ฉันสัญญาว่าจะช่วยคุณในการค้นคว้าทั้งหมด และเข้าร่วมการนำเสนอของคุณทุกครั้ง คุณคิดว่าดีไหม?",
  ui_story_5051_50510501_53_dialog_content = "จริงเหรอ",
  ui_story_5051_50510501_54_dialog_content = "จริงสิ",
  ui_story_5051_50510501_55_dialog_content = "ถ้าอย่างนั้น...แล้วฉันจะนำเสนองานวิจัยของฉันให้ทั่วโลกเห็น!",
  ui_story_5051_50510501_56_dialog_content = "คุณเคยพูดว่าคุณอยากไปเที่ยวรอบโลกตลอดเวลา แต่คุณไม่ได้พูดถึงมันเลยตั้งแต่คุณแต่งงาน",
  ui_story_5051_50510501_57_dialog_content = "ดังนั้นฉันจะทำให้ดีที่สุดเพื่อทำให้ความฝันของคุณเป็นจริง",
  ui_story_5051_50510501_58_dialog_content = "โอ้ย เหมือนโดนหลอกอีกแล้ว ฉันจะทำอย่างไรกับคุณ คาเลบ?",
  ui_story_5051_50510501_59_dialog_content = "คุณสัญญาแล้วว่าจะมาดูการนำเสนอทั้งหมดของฉัน! ไม่กลับคำตอนนี้!",
  ui_story_5051_50510501_60_dialog_content = "ฉันรู้ว่าฉันรู้ว่า. มันเป็นข้อตกลงแล้ว",
  ui_story_5051_50510501_61_dialog_content = "ฉัน... ฉันแค่มีอะไรเข้าตา",
  ui_story_5051_50510501_62_dialog_content = "ฉันไม่คิดอย่างนั้น แค่มองคุณ ย่นจมูกเพื่อปกปิดความเศร้า",
  ui_story_5051_50510501_63_dialog_content = "คุณดูเหมือนน้องชายของฉัน ...",
  ui_story_5051_50510501_64_dialog_content = "เขามีสติปัญญาเกินกว่าอายุของเขา แต่เขาก็ไม่ต่างจากเด็กน้อยที่น่ารักในหลายๆ ด้าน",
  ui_story_5051_50510501_65_dialog_content = "เช่น ทุกครั้งที่เขาร้องไห้ เขาโกหกว่ามีอะไรเข้าตา",
  ui_story_5051_50510501_66_dialog_content = "...อ้าว แต่มารยาทฉันอยู่ไหนเนี่ย?",
  ui_story_5051_50510501_67_dialog_content = "โปรดยกโทษให้ฉันที่พูดจาไม่สุภาพกับคุณ แค่คุณทำให้ฉันนึกถึงพี่ชายของฉันมาก",
  ui_story_5051_50510501_68_dialog_content = "ฉันควรจะอายที่ปฏิบัติต่อคุณอย่างไม่ให้เกียรติ",
