  ui_story_5051_50510501_71_dialog_content = "ยังไงก็ตาม ฉันสัมผัสได้ถึงการมีอยู่ของเขาเกี่ยวกับคุณ",
  ui_story_5051_50510501_72_dialog_content = "ยังไงก็ตาม ฉันอยากจะชดเชยความหยาบคายของฉันในตอนนี้ ขอเชิญร่วมเป็นแขกผู้มีเกียรติในงานเลี้ยงคืนนี้",
