  ui_story_5051_50510501_74_dialog_content = "และถ้าคุณพบว่าตัวเองมีปัญหาอะไร คุณสามารถมาหาฉันได้เสมอ",
  ui_story_5051_50510501_75_dialog_content = "ไม่มีใครควรแบกรับความทุกข์ใด ๆ ไว้คนเดียว",
  ui_story_5051_50510501_76_dialog_content = "ขอบคุณสำหรับข้อเสนอที่ดีของคุณ แต่ฉันรู้สึกว่าฉันต้องปฏิเสธ ฉันมาที่นี่เพื่อทำธุรกิจ และไม่มีความตั้งใจที่จะเข้าร่วมงานเลี้ยงตั้งแต่แรก",
  ui_story_5051_50510501_77_dialog_content = "เป็นเพียงดอกไม้เหล่านี้ที่เรียกความทรงจำดีๆ บางอย่างให้นึกถึง และฉันก็อดไม่ได้ที่จะรอต่อไปอีกสักพัก ขออภัยที่รบกวนท่าน ฝ่าบาท",
  ui_story_5051_50510501_78_dialog_content = "ด้วยการจากลาของคุณ ฉันต้องไปแล้ว... ดูแลคุณเลดี้โจชัว",
