  ui_story_5051_50510501_93_dialog_content = "ครั้งล่าสุดที่ฉันโดนจับที่ประตู ฉันต้องใช้ชื่อคาร์ลีนเพื่อผ่านเข้าไปด้วย...",
  ui_story_5051_50510501_94_dialog_content = "ทุกอย่างปกติดี, PlayerName. คุณเป็นคนดี ซึ่งเป็นเหตุผลที่ทุกคนเต็มใจช่วยเหลือคุณเสมอ",
