  ui_story_5051_50510501_98_dialog_content = "โอ้ มีปรมาจารย์ผมแดงจากแดนเหนืออยู่กับพวกเขาด้วย! คุณรู้หรือไม่ว่าพวกเขาอยู่ใน Lumopolis?",
