  ui_story_5051_50510501_100_dialog_content = "แต่นักการทูตจากนอร์ธแลนด์มาถึงเมื่อวานนี้ และดูเหมือนว่าเธอจะเหมาะสมกับคำอธิบายของคุณ",
  ui_story_5051_50510501_101_dialog_content = "(ทูตจากนอร์ธแลนด์? นั่นต้องเป็นบรรพบุรุษของจาคีนแน่ๆ)",
