  ui_story_5051_50510502_2_dialog_content = "กัปตัน <color=#FFB400>ละครใบ้</color>! Eclipsites จำนวนหนึ่งถูกซ่อนอยู่ในพัสดุที่เพิ่งได้รับ และซุ่มโจมตีเราเมื่อถูกค้นพบ!",
  ui_story_5051_50510502_3_dialog_content = "ผู้ขายที่รับผิดชอบการจัดส่งได้ถูกนำตัวไปสอบปากคำแล้ว ไม่มีรายงานผู้เสียชีวิต",
