  ui_story_5051_50510502_11_dialog_content = "แต่ฉันคิดว่าเจ้าหญิงคาร์ลีนคือนักรบระหว่างพวกเขาสองคน?",
  ui_story_5051_50510502_12_dialog_content = "ไม่ไม่ไม่! นั่นคือเจ้าหญิงเวโรนิกาเมื่อครู่ ไม่ต้องสงสัยเลย!",
  ui_story_5051_50510502_13_dialog_content = "ฉันไม่รู้ว่าเธอมีพรสวรรค์เช่นกัน ครอบครัวชวาร์ตษ์มีความสุขอย่างแท้จริงที่มีลูกๆ ที่มีความสามารถเช่นนี้...",
  ui_story_5051_50510502_14_dialog_content = "<size=30>เอ่อ PlayerName? ทุกคนเอาแต่จ้องมอง...มันเริ่มทำให้ฉันกลัว</size>",
