  ui_story_5051_50510502_25_dialog_content = "หากคุณต้องการความช่วยเหลือ คุณต้องถามเท่านั้น ฉันอาจจะเป็นแค่อัศวินสำรอง แต่ฉันก็มีภาระหน้าที่ที่จะต้องช่วยเหลือฉันเหมือนกัน",
  ui_story_5051_50510502_26_dialog_content = "หากคุณไม่มีธุระอะไรเพิ่มเติมที่นี่ ฉันขอแนะนำให้คุณไปเดี๋ยวนี้",
  ui_story_5051_50510502_27_dialog_content = "(บ้าไปแล้ว เธอเห็นฉันแล้ว! เราต้องออกไปจากที่นี่ก่อนที่เราจะเข้าไปยุ่งกับอดีตมากเกินไป!)",
  ui_story_5051_50510502_28_dialog_content = "(ถึงกระนั้น ถ้าเมื่อสิบสองปีที่แล้ว ก็ไม่ได้หมายความว่าชาโรน่าอายุแค่สิบสี่ปีหรอก เดาว่าเธอจริงจังขนาดนี้มาตลอด หึ)",
  ui_story_5051_50510502_29_dialog_content = "ฉัน-ไม่เป็นอะไร ขอโทษด้วย ดวงตาของคุณดูคุ้นเคยดี นั่นคือทั้งหมด",
  ui_story_5051_50510502_30_dialog_content = "ตาของฉันคุณพูด? วิธีคิดโบราณ",
  ui_story_5051_50510502_31_dialog_content = "คุณควรบันทึกคำพูดแบบนั้นไว้สำหรับคนที่อยากฟังจริงๆ",
  ui_story_5051_50510502_32_dialog_content = "ฮ่าฮ่า... ขอโทษอีกครั้งที่รบกวนคุณ",
  ui_story_5051_50510502_33_dialog_content = "ถ้าเส้นทางของเรากลับมาบรรจบกันอีกครั้ง บางทีฉันอาจมีเวลามากขึ้นที่จะฟังการเที่ยวบ้าๆ บอๆ ของคุณ",
  ui_story_5051_50510502_34_dialog_content = "อย่าลังเลที่จะหวังว่าวันนั้นจะมาถึง คนแปลกหน้า",
  ui_story_5051_50510502_35_dialog_content = "ไม่ต้องห่วง ฉันรู้ว่าสักวันเราจะได้พบกันอีก!",
  ui_story_5051_50510502_36_dialog_content = "(ท้ายที่สุดฉันก็เป็นเพื่อนที่ดีกับคุณในอนาคต!)",
  ui_story_5051_50510502_37_dialog_content = "หืม คนบ้า...",
  ui_story_5051_50510502_38_dialog_content = "เฮ้ ดูนั่นสิ ชาโรน่าเริ่มบทสนทนาระหว่างการลาดตระเวนของเธอ!",
  ui_story_5051_50510502_39_dialog_content = "เธอเป็นแค่วัยรุ่น มันเท่าทุนสำหรับหลักสูตรนี้",
  ui_story_5051_50510502_40_dialog_content = "คุณถูก. เธอมักจะแก่เกินวัยจนรู้สึกเจ็บใจที่เห็นเธอตื่นตระหนก",
  ui_story_5051_50510502_41_dialog_content = "เฮ้อ อยากแอบไปดูขบวนพาเหรดจัง...",
  ui_story_5051_50510502_42_dialog_content = "<size=45>อัศวิน!</size>",
  ui_story_5051_50510502_43_dialog_content = "วันนี้เป็นช่วงเวลาแห่งการเฉลิมฉลองที่สนุกสนานสำหรับทั้งเมืองของเรา ในฐานะสมาชิกของตระกูล Kartima อันทรงเกียรติ เราได้รับความไว้วางใจให้ดูแลความปลอดภัยของบุคลากรของเรา",
  ui_story_5051_50510502_44_dialog_content = "ดังนั้นคุณต้องมีศักดิ์ศรีและความเป็นมืออาชีพในขณะที่คุณทำตามคำสั่งของคุณ!",
  ui_story_5051_50510502_45_dialog_content = "...",
  ui_story_5051_50510502_46_dialog_content = "(ฮ่าฮ่าฮ่า... แม้จะผ่านมาหลายปี ดูเหมือนชาโรน่าจะไม่เปลี่ยนไปเลยสักนิด)",
  ui_story_5051_50510502_47_dialog_content = "อืม PlayerName? มิสเตอร์มีมบอกว่าจะพาเราไปพบแม่ได้",
  ui_story_5051_50510502_48_dialog_content = "เราไม่ควรเสียเวลาคุยกับผู้หญิงคนนั้นอีกต่อไป ไปกันเถอะ.",
  ui_story_5051_50510502_49_dialog_content = "(อ๊ะ เดาว่าฉันปล่อยให้บรรยากาศเทศกาลเข้าข้างฉันดีกว่า...)",
  ui_story_5051_50510502_50_dialog_content = "(เรายังตกอยู่ในอันตรายร้ายแรง ฉันปล่อยยามไว้แบบนี้ไม่ได้แล้ว)",
  ui_story_5051_50510502_51_dialog_content = "ขอโทษ ฉันสะเพร่าเมื่อกี้ ฉันจะทำให้ดีที่สุดที่จะไม่คุยกับใครถ้าไม่จำเป็น",
  ui_story_5051_50510502_52_dialog_content = "นั่นไม่ใช่สิ่งที่ฉันหมายถึง ก็แค่... เอ่อ ฉันไม่รู้จะอธิบายความรู้สึกนี้ยังไงจริงๆ",
  ui_story_5051_50510502_53_dialog_content = "หน้าอกของฉันรู้สึกแน่น และหัวใจของฉัน... มันเจ็บนิดหน่อย",
  ui_story_5051_50510502_54_dialog_content = "อ๊ะ ไม่เป็นไรนะ?! อา ถ้าเพียงฉันสามารถใช้พลังของฉันตอนนี้!",
  ui_story_5051_50510502_55_dialog_content = "แล้วฉันจะได้มองเข้าไปในจิตใจของเธอ และดูว่าเธอสบายดีไหม...",
  ui_story_5051_50510502_56_dialog_content = "น-ไม่มีทาง! โปรดอย่ามองเข้าไปในใจฉันในตอนนี้...!",
  ui_story_5051_50510502_57_dialog_content = "โอ้, PlayerName! เพราะคุณฉลาดแค่ไหน บางครั้งคุณก็เข้มเเข็งได้!",
  ui_story_5051_50510502_58_dialog_content = "ที่ดี โอ้ ฉันมีเรื่องจะขอร้องอัศวินลูโม่ ฉันจะกลับมา!",
  ui_story_5051_50510502_59_dialog_content = "หา? PlayerName?",
  ui_story_5051_50510502_60_dialog_content = "สวัสดี! นาย Mime ฉันคิดว่า?",
  ui_story_5051_50510502_61_dialog_content = "อันเดียวกัน. คุณต้องการอะไรไหม",
  ui_story_5051_50510502_62_dialog_content = "ฉันกำลังมองหาเพื่อนสามคนของฉัน เราทุกคนล้วนเป็นแขกของเจ้าหญิงเวโรนิกา แต่ระหว่างทางมาที่นี่",
  ui_story_5051_50510502_63_dialog_content = "เป็นไปได้ไหมที่คุณและอัศวินของคุณจะช่วยเราค้นหาพวกเขา? นี่คือคำอธิบายของสิ่งที่พวกเขาดูเหมือน...",
  ui_story_5051_50510502_64_dialog_content = "ดีมาก เราจะทำเท่าที่ทำได้ ฉันยังต้องรายงานต่อ City Lord ดังนั้นถ้าคุณจะขอโทษ",
  ui_story_5051_50510502_65_dialog_content = "ขอบคุณ คุณมิมมี่",
  ui_story_5051_50510502_66_dialog_content = "เอ่อ เจอพ่อทีหลัง ช่วยอย่าพูดถึงเพื่อนฉันได้ไหมว่าเกิดอะไรขึ้น...?",
  ui_story_5051_50510502_67_dialog_content = "ถ้านั่นคือทั้งหมดที่คุณขอจากฉัน ฉันก็ไม่มีปัญหาในการทำตามที่คุณต้องการ",
  ui_story_5051_50510502_68_dialog_content = "อย่างไรก็ตาม อัศวินของฉันยังคงมีหน้าที่ในการลาดตระเวนเมืองในช่วงวันหยุด ในทางกลับกัน ฉันต้องขอให้คุณและเพื่อนของคุณหลีกเลี่ยงการก่อปัญหาในวันนี้",
  ui_story_5051_50510502_69_dialog_content = "ฉันเข้าใจ. ฉันสัญญาว่าเราจะประพฤติตนให้ดีที่สุด",
  ui_story_5051_50510502_70_dialog_content = "คุณทำเสร็จแล้ว Mia?",
  ui_story_5051_50510502_71_dialog_content = "ใช่! ฉันแค่แน่ใจว่าคุณไมม์จะไม่พูดถึงเรากับพ่อของฉันในรายงานของเขา",
  ui_story_5051_50510502_72_dialog_content = "ท้ายที่สุดวันนี้ฉันควรจะมีปัญหามาก ถ้าเขารู้ว่าฉันกลับมาที่เมืองนี้ เขาจะโกรธมาก...",
  ui_story_5051_50510502_73_dialog_content = "เวโรนิก้า?",
  ui_story_5051_50510502_74_dialog_content = "แม่...?",
  ui_story_5051_50510502_75_dialog_content = "แม่!",
  ui_story_5051_50510502_76_dialog_content = "โอ้แม่สาวน้อย! เกิดอะไรขึ้น?",
  ui_story_5051_50510502_77_dialog_content = "แม่เจ้า... นี่เจ้าจริงๆ! โอ้ยคิดถึงจังแม่...",
  ui_story_5051_50510502_78_dialog_content = "ฉันด้วยที่รักของฉัน แต่ไม่ต้องห่วง ฉันอยู่ที่นี่แล้ว",
  ui_story_5051_50510502_79_dialog_content = "ให้ฉันดูที่คุณ Lumo Knights ทำร้ายคุณระหว่างการฝึกหรือไม่?",
  ui_story_5051_50510502_80_dialog_content = "หรือบางที... คุณทะเลาะกับเพื่อนคนหนึ่งของคุณหรือเปล่า?",
  ui_story_5051_50510502_81_dialog_content = "(เธอมองมาที่ฉัน! แม่ของ Mia คิดว่าฉันทำแบบนั้นกับเธอ! ไม่ ไม่ คุณเข้าใจผิดแล้ว! ไม่ใช่ฉัน!!!)",
  ui_story_5051_50510502_82_dialog_content = "ไม่นะแม่ PlayerName จะไม่ทำอะไรแบบนั้น เขาพาฉันมาที่นี่เพื่อพบคุณ ...",
  ui_story_5051_50510502_83_dialog_content = "ฉันเห็น. ดูเหมือนว่าคุณเป็นเพื่อนที่ดีมาก ที่รัก",
  ui_story_5051_50510502_84_dialog_content = "อืม? เกิดอะไรขึ้นกับหัวเข่าของคุณ เวโรนิก้า? ลายเหล่านี้คืออะไร...?",
  ui_story_5051_50510502_85_dialog_content = "ฉันสบายดี แม่! จริงหรือ! ฉันเคย...",
  ui_story_5051_50510502_86_dialog_content = "ฉันกล้าหาญขึ้นกว่าเดิมมาก",
  ui_story_5051_50510502_87_dialog_content = "ตอนนี้... ตอนนี้คุณไม่ต้องกังวลเกี่ยวกับฉัน!",
  ui_story_5051_50510502_88_dialog_content = "อย่างนั้นเหรอ? ใบหน้าเล็กๆ ที่ดูเศร้าๆ ของคุณดูไม่ค่อยน่าเชื่อถือเลย",
  ui_story_5051_50510502_89_dialog_content = "มาล้างหน้ากันเถอะ แล้วบอกฉันว่าตอนนี้คุณกล้าหาญแค่ไหน",
  ui_story_5051_50510601_1_dialog_content = "(ผู้หญิงเข้าไปข้างใน...)",
  ui_story_5051_50510601_2_dialog_content = "(แม่ของมีอายิ้มให้ฉันเมื่อพวกเขาจากไป อาจบอกใบ้ให้ฉันรออยู่ตรงนี้)",
  ui_story_5051_50510601_3_dialog_content = "(ว่าไงอีกล่ะ \"ห้ามแอบดูผู้หญิงเตรียมตัว\" งั้นก็ต้องรอกันต่อไป)",
  ui_story_5051_50510601_4_dialog_content = "(ฉันได้พบกับอิสต์วานและชาโรน่าระหว่างทาง และตอนนี้แม่ของมีอา...)",
  ui_story_5051_50510601_5_dialog_content = "(ทุกคนคุยกับเราเหมือนเป็นคนจริงๆ)",
  ui_story_5051_50510601_6_dialog_content = "(คริสตัลแห่งความทรงจำชั่วนิรันดร์นั้นยอดเยี่ยมมาก...)",
  ui_story_5051_50510601_7_dialog_content = "(แต่มันไม่ได้ออกแบบมาให้เราโต้ตอบกับพวกเขา)",
  ui_story_5051_50510601_8_dialog_content = "(ผู้ติดต่อเช่นนี้ต้องเสียภาษีตามขีดจำกัดของคริสตัล)",
  ui_story_5051_50510601_9_dialog_content = "(เฮ้อ มันยากที่จะวัดว่าสถานการณ์ดีหรือไม่ดี ฉันหวังว่าเราจะพบ Jakine และคนอื่นๆ ในเร็วๆ นี้...)",
  ui_story_5051_50510601_10_dialog_content = "คุณอยู่ที่นั่น",
  ui_story_5051_50510601_11_dialog_content = "นี่เป็นทรัพย์สินส่วนตัวของตระกูล Schwartz",
  ui_story_5051_50510601_12_dialog_content = "คุณแอบเข้ามาที่นี่ได้อย่างไร?",
  ui_story_5051_50510601_13_dialog_content = "ฮะ? นั่นใคร?",
  ui_story_5051_50510601_14_dialog_content = "ดูถูกคนโง่อวดดี! คาร์ลีนกำลังพูดกับคุณ!",
  ui_story_5051_50510601_15_dialog_content = "<size=45>คาร์ลีน?!</size>",
  ui_story_5051_50510601_16_dialog_content = "คุณกล้าเรียกฉันด้วยชื่อ?",
  ui_story_5051_50510601_17_dialog_content = "ฉันไม่สนุกกับการโอ้อวดความสูงศักดิ์บนพื้นดินนี้ การดูถูกฉันก็เท่ากับการดูถูก House Schwartz!",
  ui_story_5051_50510601_18_dialog_content = "ย่องเข้ามาในดินแดนของเราในวันครอบครัวชวาร์ตษ์...",
  ui_story_5051_50510601_19_dialog_content = "... และแสดงความหยาบคายและดูถูกสมาชิก คุณจะต้องทนทุกข์ทรมานกับผลที่ตามมา!",
  ui_story_5051_50510601_20_dialog_content = "เดี๋ยวก่อน ฉันถูกจับได้โดยไม่ระวัง!",
  ui_story_5051_50510601_21_dialog_content = "โปรดให้ฉันอธิบาย เจ้าหญิงคาร์ลีน!",
  ui_story_5051_50510601_22_dialog_content = "ทายซิว่าใคร?",
  ui_story_5051_50510601_23_dialog_content = "<size=45>เหวอ!</size>",
  ui_story_5051_50510601_24_dialog_content = "อะ-อะไรนะ!",
  ui_story_5051_50510601_25_dialog_content = "คุณยังนำผู้สมรู้ร่วมคิดผู้บุกรุกที่น่ารังเกียจมาด้วย?!",
  ui_story_5051_50510601_26_dialog_content = "หืม? ช่ายย...",
  ui_story_5051_50510601_27_dialog_content = "ใช่แล้ว เรากำลังทำงานร่วมกันเพื่อไปหาคุณ คาร์ลีนน้อย!",
  ui_story_5051_50510601_28_dialog_content = "D-น่ารังเกียจ! แลนซ์ของฉันอยู่ที่ไหน เฮ้ ปล่อยนะ ฉันหาลูกไม้ไม่เจอ!",
  ui_story_5051_50510601_29_dialog_content = "รอสักครู่... คุณฟังดูคุ้นๆ ไหม คุณคือเวโรนิกาใช่ไหม",
  ui_story_5051_50510601_30_dialog_content = "อาฮ่า! ไม่ ฉันไม่ใช่เวโรนิก้าแน่นอน!",
  ui_story_5051_50510601_31_dialog_content = "ได้โปรดอย่าพยายามหลอกฉันด้วยการปลอมเสียงที่น่าสงสาร! ฉันไม่ใช่เด็กแล้ว!",
  ui_story_5051_50510601_32_dialog_content = "แน่ใจนะ คาร์ลีนตัวน้อย?",
  ui_story_5051_50510601_33_dialog_content = "เฮ้ แม้จะโตเกินวัย แต่คาร์ลีนก็ยังตื่นตระหนกเมื่อถูกปิดตา",
  ui_story_5051_50510601_34_dialog_content = "แม่? คุณอยู่ที่นี่ด้วยเหรอแม่? ได้โปรดขอให้เวโรนิกาปล่อยฉัน!",
  ui_story_5051_50510601_35_dialog_content = "โอ้? ทำไมคุณถึงเรียกฉันว่าแม่อีกครั้ง ฉันชอบที่จะได้ยินคุณเรียกฉันว่าแม่ ไม่อย่างนั้นฉันจะไม่ช่วยคุณ",
  ui_story_5051_50510601_36_dialog_content = "ท-ทำไม?!",
  ui_story_5051_50510601_37_dialog_content = "นั่นคือสิ่งที่คุณได้รับจากการใจร้ายกับแขก คาร์ลีน",
  ui_story_5051_50510601_38_dialog_content = "คุณรู้สึกไม่พอใจกับคนที่คุณพบกันเป็นครั้งแรก นั่นไม่ใช่เรื่องดีเลย",
  ui_story_5051_50510601_39_dialog_content = "ทั้งหมดเป็นความผิดของคุณ ผู้บุกรุกหน้าด้าน! คุณทำอะไรเพื่อล่อลวงน้องสาวและแม่ของฉัน!",
  ui_story_5051_50510601_40_dialog_content = "ไม่มีอะไร ฉันไม่ได้ทำอะไร!",
  ui_story_5051_50510601_41_dialog_content = "ฮี่ฮี่ ฉันสงสัยว่าคุณจะอดทนได้นานแค่ไหน",
  ui_story_5051_50510601_42_dialog_content = "Boo-hoo— ฉันขอโทษที่ฉันใจร้าย ปล่อยฉันออกจากเบ็ดได้โปรด!",
  ui_story_5051_50510601_43_dialog_content = "ฮี่ฮี่ ไม่ได้แกล้งคาร์ลีนแบบนี้มานานแล้ว หัวเราะหนักมากจนแทบหยุดหายใจ...",
  ui_story_5051_50510601_44_dialog_content = "อืม... Bad Veronica...",
  ui_story_5051_50510601_45_dialog_content = "เอาล่ะเวโรนิกา คุณน่ารักที่สุดเมื่อคุณหัวเราะ",
  ui_story_5051_50510601_46_dialog_content = "แต่คาร์ลีนยังคงไม่พอใจ...",
  ui_story_5051_50510601_47_dialog_content = "ไม่ ไม่ ไม่จำเป็น!",
  ui_story_5051_50510601_48_dialog_content = "นี่คือสิ่งที่ครอบครัวควรเป็น ถ้าแดเนียลอยู่ที่นี่ด้วย...",
  ui_story_5051_50510601_49_dialog_content = "ขอโทษสำหรับปัญหา.",
  ui_story_5051_50510601_50_dialog_content = "ฉันได้ยินเวโรนิก้าเรียกคุณ PlayerName. ฉันขอพูดกับคุณเหมือนกันได้ไหม",
  ui_story_5051_50510601_51_dialog_content = "ไม่มีปัญหา เรียกฉันตามที่คุณต้องการ",
  ui_story_5051_50510601_52_dialog_content = "คล้ายกับที่คุณเรียก Veronica ว่าเป็น Mia?",
  ui_story_5051_50510601_53_dialog_content = "อะไร เอ่อ...",
  ui_story_5051_50510601_54_dialog_content = "(แม่ของเธอได้ยินการสนทนาระหว่าง Mia กับฉัน?!)",
  ui_story_5051_50510601_X54_dialog_content = "จริงค่ะแม่... PlayerName เป็นเพื่อนที่ฉันรู้จักใน Umbraton...",
  ui_story_5051_50510601_56_dialog_content = "ไม่เป็นไร ฉันก็จะวิ่งเล่นโดยใช้นามแฝงตอนเด็กๆ เหมือนกัน",
  ui_story_5051_50510601_57_dialog_content = "ฉันเข้าใจ. มีที่ว่างสำหรับความลับที่ไม่เป็นอันตรายเสมอ ไม่ว่าจะเป็นใครก็ตาม",
  ui_story_5051_50510601_58_dialog_content = "ขอบคุณแม่...",
  ui_story_5051_50510601_59_dialog_content = "อา ฉันเข้าใจแล้ว Mia ตัวน้อยเห็นเพื่อนของเราที่นี่เป็นอัศวินผู้กล้าหาญในชุดเกราะที่ส่องแสง",
  ui_story_5051_50510601_60_dialog_content = "การปรากฏตัวของใครก็เพียงพอที่จะพาเจ้าหญิงที่สาบสูญกลับบ้านได้ จริงไหม?",
  ui_story_5051_50510601_61_dialog_content = "โอ้แม่...",
  ui_story_5051_50510601_62_dialog_content = "คุณเป็นราชองครักษ์ของพี่สาวฉันเหรอ? แต่คุณแน่ใจหรือว่าคุณสามารถปกป้องเธอด้วยร่างกายที่ผอมแห้งและขี้ขลาดของคุณได้?",
  ui_story_5051_50510601_63_dialog_content = "คุณเข้าใจผิดแล้ว คาร์ลีนตัวน้อย ไม่ใช่ราชองครักษ์ แต่อาจเป็นเจ้าชายชาร์มมิ่ง!",
  ui_story_5051_50510601_64_dialog_content = "แม่! PlayerName เป็นแค่เพื่อนที่ฉันพบใน Umbraton!",
  ui_story_5051_50510601_65_dialog_content = "เป็นคนอ่อนโยน อดทน ช่วยเหลือผมมาก แค่นั้นแหละ...",
  ui_story_5051_50510601_66_dialog_content = "ความลับที่ไม่เป็นอันตราย? ฉันไม่เข้าใจ...",
  ui_story_5051_50510601_67_dialog_content = "เปิดเผยความลับของคุณ ผู้บุกรุกที่น่ารังเกียจ!",
  ui_story_5051_50510601_68_dialog_content = "เอ่อ ฉันชื่อ PlayerName...",
  ui_story_5051_50510601_69_dialog_content = "(เธอกระทืบเท้าฉัน...!)",
  ui_story_5051_50510601_70_dialog_content = "(คาร์ลีนที่อายุน้อยกว่าคนนี้ก็จริงจังและแก่แดดเช่นกัน แต่ใบหน้าของเธอดูมีชีวิตชีวาและมีชีวิตชีวามากขึ้น)",
  ui_story_5051_50510601_71_dialog_content = "(แม่ของเธอเสียชีวิต พี่สาวของเธอหายตัวไป และความสัมพันธ์กับพ่อของเธอ... เธอผ่านความเศร้าโศกมามาก)",
  ui_story_5051_50510601_72_dialog_content = "(หากไม่มีทั้งหมดนั้น Carleen คงจะยิ้มมากกว่านี้)",
  ui_story_5051_50510601_73_dialog_content = "(และบางทีเธออาจจะยังคงกระทืบเท้าของฉันเมื่อเธอโกรธ)",
  ui_story_5051_50510601_74_dialog_content = "ทำไมคุณถึงจ้องมองมาที่ฉัน คุณต้องการกระทืบอีกไหม?",
  ui_story_5051_50510601_75_dialog_content = "ไม่เลย. โปรดไว้ชีวิตข้าด้วย เจ้าหญิงคาร์ลีน",
  ui_story_5051_50510601_76_dialog_content = "ขอโทษนะ คาร์ลีนออกจะขวานผ่าซากเพียงเพราะเธอไม่รู้วิธีแสดงออกอย่างเหมาะสม เธอหมายความว่าไม่มีความอาฆาตพยาบาท",
  ui_story_5051_50510601_77_dialog_content = "คุณสามารถฟื้นความทรงจำของครอบครัวได้อย่างเต็มที่ มิ... เวโรนิก้า?",
  ui_story_5051_50510601_78_dialog_content = "ใช่. หลังจากได้พบกับแม่และคาร์ลีนอีกครั้ง ความทรงจำก็กลับมาท่วมท้น",
  ui_story_5051_50510601_79_dialog_content = "คาร์ลีนกับฉันชอบไปสวิงกิ้งในสวนด้วยกัน...",
  ui_story_5051_50510601_80_dialog_content = "เราจะไม่เบื่อที่จะเล่น Guess Who?",
  ui_story_5051_50510601_81_dialog_content = "ความทรงจำ อารมณ์ ความสุข... ล้วนมีอยู่จริง ท้ายที่สุด...",
  ui_story_5051_50510601_82_dialog_content = "จริงหรือ นั่นช่างวิเศษสุด ๆ!",
  ui_story_5051_50510601_83_dialog_content = "(แต่มีอายังไม่ได้พูดถึงพ่อของเธอเลย และมันก็ค่อนข้างกระอักกระอ่วนเมื่อพวกเขาพบกันในห้องรับแขก)",
  ui_story_5051_50510601_84_dialog_content = "(เป็นไปได้ไหมว่าเธอมีความสัมพันธ์จืดชืดกับเขาเหมือนคาร์ลีน?)",
  ui_story_5051_50510601_85_dialog_content = "ฉันขอขนมหรือเครื่องดื่มให้คุณได้ไหม มีให้บริการในห้องโถง",
  ui_story_5051_50510601_86_dialog_content = "เอาเลย เวโรนิก้า ไปหาของว่างกัน",
  ui_story_5051_50510601_87_dialog_content = "อ๊ะ อย่าดึงฉันแรงนักสิ...",
  ui_story_5051_50510601_88_dialog_content = "อย่ายืนเฉยๆ PlayerName, มาพร้อมกับเรา.",
  ui_story_5051_50510601_89_dialog_content = "ฮ่าๆ... หายากนะที่ทั้งครอบครัวจะได้อยู่พร้อมหน้าพร้อมตากัน ฉันไม่ควรก้าวก่าย",
  ui_story_5051_50510601_90_dialog_content = "ไม่เป็นไรลูก",
  ui_story_5051_50510601_91_dialog_content = "ฉันคุ้นเคยกับสายตานั้นของคุณมาก",
  ui_story_5051_50510601_92_dialog_content = "มันอาจจะดูเด็ดเดี่ยว แต่มันก็เสียไปด้วยสายตาของเด็กที่หลงทาง",
  ui_story_5051_50510601_93_dialog_content = "คุณไม่ได้อยู่อย่างลำบากใน Umbraton ใช่ไหม?",
  ui_story_5051_50510601_94_dialog_content = "เลขที่! ที่จริงฉันไม่ได้มาจาก Umbraton ฉัน...",
  ui_story_5051_50510601_95_dialog_content = "(ไม่ ไม่สามารถบอกความจริงได้ Caelesite เป็นสังคมปิด คนนอกน้อยมากที่รู้อะไรเกี่ยวกับเรา)",
  ui_story_5051_50510601_96_dialog_content = "(ดังนั้น การพูดว่าฉันเป็นชาวคาเลสไทต์มีแต่จะทำให้คริสตัลยิ่งตอกย้ำ)",
  ui_story_5051_50510601_97_dialog_content = "ฉันเป็นแค่โจเฉลี่ยนิรนามของคุณ",
  ui_story_5051_50510601_98_dialog_content = "ฉันไม่มีครอบครัว ดังนั้นฉันจึงชอบท่องเที่ยวและหาเพื่อนใหม่",
  ui_story_5051_50510601_99_dialog_content = "การท่องเที่ยว? ฉันยังชอบการเดินทาง น่าเสียดายที่ฉันไม่ได้รับโอกาสตอนนี้",
  ui_story_5051_50510601_100_dialog_content = "มีความสุขกับชีวิตตอนนี้มั้ยลูก?",
  ui_story_5051_50510601_101_dialog_content = "ใช่ ฉันรู้สึกมีความสุขมาก",
  ui_story_5051_50510601_102_dialog_content = "ดี",
  ui_story_5051_50510601_103_dialog_content = "คุณเป็นเพื่อนของ Veronica และเป็นเด็กที่ใจดี",
  ui_story_5051_50510601_104_dialog_content = "รู้สึกอิสระที่จะทำให้ตัวเองเหมือนอยู่บ้านระหว่างที่คุณอยู่ที่นี่",
  ui_story_5051_50510601_105_dialog_content = "ขอบคุณ มายเลดี้...",
  ui_story_5051_50510601_106_dialog_content = "ฉันชื่อโจชัว คุณสามารถเรียกฉันว่า",
  ui_story_5051_50510601_107_dialog_content = "ใช่. ฉันรู้สึกดีกว่าที่จะเรียกคุณว่า Lady Joshua",
  ui_story_5051_50510601_108_dialog_content = "คุณไปทำภารกิจลับใน Umbraton กับ Lumo Knights เหรอ Veronica?",
  ui_story_5051_50510601_109_dialog_content = "ภารกิจแบบนั้นคืออะไร? แล้วคุณกับ Lumo Knights จะต่อสู้กันอย่างไร? คุณช่วยเล่าให้ฟังหน่อยได้ไหม?",
  ui_story_5051_50510601_110_dialog_content = "อืม...",
  ui_story_5051_50510601_111_dialog_content = "ใช่ เวโรนิก้า คุณช่วยอธิบายให้ฉันฟังได้ไหม",
  ui_story_5051_50510601_112_dialog_content = "<size=45>ฟ-พ่อ!</size>",
  ui_story_5051_50510601_113_dialog_content = "ข้าจะไม่คัดค้านหากท่านมีความกล้าหาญของนักรบที่จะอาสาออกรบ",
  ui_story_5051_50510601_114_dialog_content = "แต่คุณละทิ้งโพสต์ของคุณอีกครั้งและกลับบ้านเพื่อเข้าร่วมเทศกาล",
  ui_story_5051_50510601_115_dialog_content = "คุณจะชดใช้เรื่องตลกโดยเฉพาะอย่างยิ่งในวันรำลึกได้อย่างไร?",
  ui_story_5051_50510601_116_dialog_content = "...",
  ui_story_5051_50510601_117_dialog_content = "ฉันนึกถึงเวโรนิกาที่รัก",
  ui_story_5051_50510601_118_dialog_content = "วันนี้เป็นวันที่สมาชิกทุกคนในบ้าน Schwartz กลับมารวมตัวกัน เธอควรจะอยู่ที่นี่กับเราไม่ใช่เหรอ?",
  ui_story_5051_50510601_119_dialog_content = "โจชัว ก็อย่างที่คุณบอก บ้านชวาร์ตษ์ ไม่ใช่ครอบครัว",
  ui_story_5051_50510601_120_dialog_content = "บ้านชวาร์ตษ์ไม่เคยมีเด็กนิสัยเสียมาก่อนและจะไม่มีวันทำแบบนั้น",
  ui_story_5051_50510601_121_dialog_content = "ใช่ เราเป็นบ้าน แต่เป็นครอบครัวมากกว่า",
  ui_story_5051_50510601_122_dialog_content = "เราจะรักษาบ้านได้อย่างไร ถ้าเราไม่สามารถแม้แต่จะรักษาหัวใจของคนใกล้ชิดเราได้?",
  ui_story_5051_50510601_123_dialog_content = "(นั่นคือชวาร์ตษ์?)",
  ui_story_5051_50510601_124_dialog_content = "(เขาไม่น่าประทับใจในอนาคต แต่เขาอายุมากกว่าหลายปีและแตกต่างจากนี้โดยสิ้นเชิง)",
  ui_story_5051_50510601_125_dialog_content = "(ความตึงเครียดมีมาก และ Mia ดูไม่อยากอยู่ที่นี่เลย... และตอนนี้พลังจิตของฉันเลือกที่จะละทิ้งฉัน!)",
  ui_story_5051_50510601_126_dialog_content = "ขอโทษที",
  ui_story_5051_50510601_127_dialog_content = "(คุณบลองก์! ในชุดเดียวกับที่ฉันเห็นก่อนหน้านี้! ดังนั้นเธอจึงทำงานให้กับท่านเจ้าเมืองเมื่อสิบสองปีก่อนด้วย)",
  ui_story_5051_50510601_128_dialog_content = "คุณเป็นใครน่ะ",
  ui_story_5051_50510601_129_dialog_content = "ฉัน? ฉันเป็นเพื่อนของเวโรนิก้า...",
  ui_story_5051_50510601_130_dialog_content = "เพื่อนเหรอ",
  ui_story_5051_50510601_131_dialog_content = "ดาเนียล.",
  ui_story_5051_50510601_132_dialog_content = "ดี. ปฏิบัติต่อบุคคลดังกล่าวในฐานะแขกผู้มีเกียรติ คุณโรจน์",
  ui_story_5051_50510601_133_dialog_content = "ได้สิ",
  ui_story_5051_50510601_134_dialog_content = "สภาผู้อาวุโสยังคงรอคอยการมาของคุณ ท่านลอร์ด",
  ui_story_5051_50510601_135_dialog_content = "ตั้งแต่คุณพาเวโรนิกากลับมา โจชัว ดูแลเธอ",
  ui_story_5051_50510601_136_dialog_content = "อย่าปล่อยให้เธอและเพื่อนของเธอสร้างปัญหาอื่นใด",
  ui_story_5051_50510601_137_dialog_content = "ไม่มีปัญหา ฉันจะดูแลเด็กๆ เหล่านี้เอง",
  ui_story_5051_50510601_138_dialog_content = "ถ้าอย่างนั้น คุณเลิกทำตัวร้ายกาจได้แล้วเหรอ?",
  ui_story_5051_50510601_139_dialog_content = "ก็ได้...",
  ui_story_5051_50510601_140_dialog_content = "ขบวนพาเหรดกำลังจะเริ่มขึ้น เตรียมเด็กๆให้พร้อม",
  ui_story_5051_50510601_141_dialog_content = "เฮ้อ...",
  ui_story_5051_50510601_142_dialog_content = "คุณรู้สึกสบายดีไหม เวโรนิก้า?",
  ui_story_5051_50510601_143_dialog_content = "พ่อของคุณไม่ได้โกรธคุณ เขาแค่มีหลายอย่างบนโต๊ะของเขาในวันนี้",
  ui_story_5051_50510601_144_dialog_content = "ฉัน... ฉัน...",
  ui_story_5051_50510601_145_dialog_content = "ไม่เป็นไรแล้วลูก...",
  ui_story_5051_50510601_146_dialog_content = "เวโรนิก้า...",
  ui_story_5051_50510601_147_dialog_content = "มีเวลาก่อนขบวนพาเหรด My Lady คุณยังมีโอกาสติดต่อกับครอบครัวของคุณ ที่เหลือปล่อยให้ฉันจัดการเอง",
  ui_story_5051_50510601_148_dialog_content = "ขอบคุณคุณร็อต",
  ui_story_5051_50510601_149_dialog_content = "แค่ทำงานของฉัน",
  ui_story_5051_50510601_150_dialog_content = "สำหรับคุณ โปรดมากับฉันเพื่อทำความเคยชินกับขบวนพาเหรดและเตรียมพร้อมสำหรับกิจกรรมที่จะเกิดขึ้น",
  ui_story_5051_50510601_151_dialog_content = "มั่นใจได้เลยว่า Lady Joshua เชี่ยวชาญในการปลอบโยนผู้อื่น เจ้าหญิงเวโรนิกาอยู่ในมือที่ดี",
