  ui_story_5051_50510601_153_dialog_content = "นางสาวบล็องก์? ฉันไม่ได้คาดหวังว่าใครจะเรียกฉันด้วยชื่อนั้นที่นี่",
  ui_story_5051_50510601_154_dialog_content = "ฉันขอถามคุณรู้จักชื่อนั้นได้อย่างไร",
  ui_story_5051_50510601_155_dialog_content = "(คุณบลองก์ไม่ได้ไปที่นั่นเมื่อ 12 ปีที่แล้วเหรอ?)",
  ui_story_5051_50510601_156_dialog_content = "(ลองคิดดูสิ ลอร์ดในโลกแห่งความจริงก็เรียกเธอว่านางสาวร็อตเหมือนกัน)",
  ui_story_5051_50510601_157_dialog_content = "(นั่นต้องเป็นชื่อตอนที่เธอทำงานให้กับ City Lord... แล้วฉันจะปล่อยมันไปได้อย่างไร?)",
  ui_story_5051_50510601_158_dialog_content = "มันโอเค. เช่นเดียวกับที่ฉันมีความลับให้เก็บ คุณมีของคุณ นั่นยุติธรรมเท่านั้น",
  ui_story_5051_50510601_159_dialog_content = "คุณเป็นแขกผู้มีเกียรติที่ได้รับมอบหมายให้ดูแลเป็นการส่วนตัวจากท่านเจ้าเมือง ดังนั้นจึงเป็นหน้าที่ของฉันที่จะต้องดูแลให้วันของคุณมีความสุข",
  ui_story_5051_50510601_160_dialog_content = "อย่างไรก็ตาม ฉันหวังว่าคุณจะโทรหาฉันคุณร็อตในระหว่างนี้เพื่อเร่งรัดภาระหน้าที่ของฉัน",
  ui_story_5051_50510601_161_dialog_content = "แน่นอน คุณร็อต ฉันจะไม่สร้างปัญหาให้คุณ",
  ui_story_5051_50510601_162_dialog_content = "ขอขอบคุณสำหรับความเข้าใจของคุณ. เชิญทางนี้ครับ",
  ui_story_5051_50510701_1_dialog_content = "อินเวเนียร์ เอิ่ม! อินเวเนียร์ เอิ่ม! อินเวเนียร์ เอิ่ม!",
  ui_story_5051_50510701_2_dialog_content = "ช่วยบอกทีว่าตอนนี้คนในใจอยู่ที่ไหน?",
  ui_story_5051_50510701_3_dialog_content = "<size=45>อับราฮาดะบรา!</size>",
  ui_story_5051_50510701_4_dialog_content = "อ๊ะ คราวหน้า!",
  ui_story_5051_50510701_5_dialog_content = "ฉันได้ยินมาว่าหน่วยอัศวินอื่นถูกย้ายไปที่ Umbraton",
  ui_story_5051_50510701_6_dialog_content = "อะไร พวกเขากำลังทำอะไรใน Umbraton?",
  ui_story_5051_50510701_7_dialog_content = "ฉันเดาว่าต่อสู้กับการรุกรานของ Eclipsite Umbraton อยู่ภายใต้การป้องกันของ Lumopolis หลังจากนั้น",
  ui_story_5051_50510701_8_dialog_content = "แล้วทำไมเราไม่ไปล่ะ?",
  ui_story_5051_50510701_9_dialog_content = "คุณโง่? พวกเราคืออัศวินของ <color=#FFB400>คาร์ติมา</color>. เราจะไปที่ทิ้งขยะแบบนั้นไม่ได้!",
  ui_story_5051_50510701_10_dialog_content = "จุ๊ จุ๊ จุ๊! อย่าปล่อยให้ Sharona จับได้ว่าพวกเราหย่อนยานอีก",
  ui_story_5051_50510701_11_dialog_content = "Kartima ยังคงดีที่สุด เรากำลังไล่ตาม City Lord อยู่",
  ui_story_5051_50510701_12_dialog_content = "อ้อเหรอ...",
  ui_story_5051_50510701_13_dialog_content = "อ้อเหรอ...",
  ui_story_5051_50510701_14_dialog_content = "เฮ้ คุณเป็นใคร?",
  ui_story_5051_50510701_15_dialog_content = "บุคคลต้องสงสัย! เร็วเข้า!",
  ui_story_5051_50510701_16_dialog_content = "ขออภัย ผิดที่ ลาก่อน!",
  ui_story_5051_50510701_17_dialog_content = "อับราฮาดาบรา!",
  ui_story_5051_50510701_18_dialog_content = "ตอนนี้ฉันอยู่ที่ไหน",
  ui_story_5051_50510701_19_dialog_content = "Irridon ได้ที่หนึ่งประจำภาคเรียนอีกแล้ว...",
  ui_story_5051_50510701_20_dialog_content = "Irridon ไม่ใช่แค่สวยและเป็นนักเรียนที่ดี เธอยังมีเกียรติต่อหน้าอาจารย์ผู้สอนของ Dawn Academy",
  ui_story_5051_50510701_21_dialog_content = "ฉันเขียวด้วยความอิจฉา",
  ui_story_5051_50510701_22_dialog_content = "บางทีเธออาจจะข้ามเกรดและไปเรียนต่อในภายหลัง",
  ui_story_5051_50510701_23_dialog_content = "เธอสมบูรณ์แบบเกินไป",
  ui_story_5051_50510701_24_dialog_content = "อิริดอน? นั่นใครน่ะ?",
  ui_story_5051_50510701_25_dialog_content = "ผู้หญิงคนนั้นเป็นใครในการลุกขึ้นแปลกๆ? ผมสีแดงของเธอมีเสน่ห์แม้ว่า",
  ui_story_5051_50510701_26_dialog_content = "เครื่องแต่งกายแบบไหนกันนะ? ฉันจะต้องรายงานเธอไปที่ Hall of Justice!",
  ui_story_5051_50510701_27_dialog_content = "อ๊ะ ผิดที่อีกแล้ว ขออภัย!",
  ui_story_5051_50510701_28_dialog_content = "อับรา...ฮาดาบรา...",
  ui_story_5051_50510701_29_dialog_content = "นี่... ร้านอาหารเหรอ?",
  ui_story_5051_50510701_30_dialog_content = "แต่ฉันไม่เห็นใครที่นี่",
  ui_story_5051_50510701_31_dialog_content = "<color=#e8d9bb>คำราม—</color>",
  ui_story_5051_50510701_32_dialog_content = "ลูกแก้วคริสตัล เธอพาฉันมาที่นี่เพราะรู้ว่าฉันหิวใช่ไหม?",
  ui_story_5051_50510701_33_dialog_content = "แต่ต้องรีบไปหาทุกคน! ไม่ต้องพูดถึงมันไม่มีประโยชน์ที่จะกินในคริสตัล!",
  ui_story_5051_50510701_34_dialog_content = "อีกที!",
  ui_story_5051_50510701_35_dialog_content = "อินเวเนียร์ เอิ่ม! อินเวเนียร์ เอิ่ม! อินเวเนียร์ เอิ่ม!",
  ui_story_5051_50510701_36_dialog_content = "ช่วยบอกทีว่าตอนนี้คนในใจอยู่ที่ไหน?",
  ui_story_5051_50510701_37_dialog_content = "อับราฮาดะบรา!",
  ui_story_5051_50510701_38_dialog_content = "<size=45>ฮ่าฮ่าฮ่าฮ่า!</size>",
  ui_story_5051_50510701_39_dialog_content = "ว-ใครอยู่นั่น?! คุณหัวเราะดังเกินไปและทำให้ฉันสติแตก!",
  ui_story_5051_50510701_40_dialog_content = "ทักษะการทำนายของคุณ *สะอึก* ง่อยมาก สาวน้อย",
  ui_story_5051_50510701_41_dialog_content = "กล้าดียังไงมาเรียกการทำนายของฉันว่าง่อย!",
  ui_story_5051_50510701_42_dialog_content = "ฉันเรียนรู้มาจากแม่ของฉัน และเธอก็เป็นปรมาจารย์ด้านการทำนายที่เก่งที่สุด!",
  ui_story_5051_50510701_43_dialog_content = "อย่าบอกฉันว่าคุณไม่เคยได้ยิน <color=#FFB400>โบอาส</color> แห่งแดนเหนือ!",
  ui_story_5051_50510701_44_dialog_content = "โบราส? ฟังดูคุ้นเคย... *สะอึก*",
  ui_story_5051_50510701_45_dialog_content = "แล้วไง! ง่อยก็ยังง่อย คุณควรยอมรับมัน!",
  ui_story_5051_50510701_46_dialog_content = "หยาบคาย! ฉันจะแสดงให้คุณเห็น—!",
  ui_story_5051_50510701_47_dialog_content = "*สะอึก* คุณพูดมากสำหรับคนที่ไม่สามารถสำรองข้อมูลได้",
  ui_story_5051_50510701_48_dialog_content = "แล้วเรามาดูกันว่าดวงชะตาของใครแม่นยำกว่ากัน?",
  ui_story_5051_50510701_49_dialog_content = "คุณอยู่!",
  ui_story_5051_50510701_50_dialog_content = "กรุณาจ่ายเช็คของคุณผู้หญิง",
  ui_story_5051_50510701_51_dialog_content = "ฮะ? เอ่อ ฉันไม่มีเงินติดตัวเลย... *สะอึก*",
  ui_story_5051_50510701_52_dialog_content = "แล้วเธอล่ะ",
  ui_story_5051_50510701_53_dialog_content = "ฉัน? ฉันไม่รู้จักเธอทำไมฉันต้องจ่ายเงิน?",
  ui_story_5051_50510701_54_dialog_content = "ถ้าจ่ายไม่ได้ก็รอเจ้าหน้าที่พาเข้าไป",
  ui_story_5051_50510701_55_dialog_content = "อะไร ไม่มีทาง ฉันมีเรื่องสำคัญที่ต้องทำ!",
  ui_story_5051_50510701_56_dialog_content = "คุณกำลังพูดบางอย่าง! คุณเริ่มต้นทั้งหมดนี้!",
  ui_story_5051_50510701_57_dialog_content = "ฟู่...",
  ui_story_5051_50510701_58_dialog_content = "เธอหลับไป...",
  ui_story_5051_50510701_59_dialog_content = "จ่ายหรือไปกับยาม ทางเลือกของคุณ",
  ui_story_5051_50510701_60_dialog_content = "เอาล่ะ... ราคาเท่าไหร่?",
  ui_story_5051_50510701_61_dialog_content = "127,938 ไนเทียม",
  ui_story_5051_50510701_62_dialog_content = "<size=45>เท่าไร?!</size>",
  ui_story_5051_50510701_63_dialog_content = "ผู้หญิงคนนี้ได้ดื่มน้ำสำรองที่ดีที่สุดของเราไปมากมาย และรวมส่วนลดวันหยุดไว้แล้ว",
  ui_story_5051_50510701_64_dialog_content = "คำสาป... งบประมาณการเดินทางของฉัน... แคชของฉัน...",
  ui_story_5051_50510701_65_dialog_content = "(แต่ทั้งหมดนี้ใน Crystal of Eternal Memory อาจไม่มีจริง ดังนั้นฉันควรจะยังมีเงินอยู่หลังจากออกไป ใช่ไหม?)",
  ui_story_5051_50510701_66_dialog_content = "เอาล่ะ...",
  ui_story_5051_50510701_67_dialog_content = "ขอบคุณ",
  ui_story_5051_50510701_68_dialog_content = "เฮ้ ฉันเพิ่งจ่ายเงินให้คุณ ตอนนี้คุณไม่มีข้อแก้ตัวอีกแล้ว",
  ui_story_5051_50510701_69_dialog_content = "วันนี้ฉันจะสู้เพื่อเกียรติของแม่!",
  ui_story_5051_50510701_70_dialog_content = "เฮ้ เธออยู่ไหน...?",
  ui_story_5051_50510701_71_dialog_content = "ตรงนี้... *สะอึก*",
  ui_story_5051_50510701_72_dialog_content = "อย่าหนีนะ!",
  ui_story_5051_50510701_73_dialog_content = "อย่าพยายามหลีกหนีจากฝูงชน!",
  ui_story_5051_50510701_74_dialog_content = "เอาล่ะ นี่มัน...",
  ui_story_5051_50510701_75_dialog_content = "เจอดีแน่!",
  ui_story_5051_50510701_76_dialog_content = "ไม่ใช่แค่ฉันถูกบังคับให้จ่ายเงินเพื่อคุณ ตอนนี้คุณพยายามหนี...",
  ui_story_5051_50510701_77_dialog_content = "มาดูกันว่าตอนนี้คุณจะวิ่งไปถึงไหนแล้ว?",
  ui_story_5051_50510701_78_dialog_content = "ทำไมต้องวิ่ง? ดูสิ ที่คุณกำลังมองหาอยู่ตรงนั้น",
  ui_story_5051_50510701_79_dialog_content = "ที่ฉันตามหา...?",
  ui_story_5051_50510701_80_dialog_content = "ดูสิ ขบวนพาเหรดกำลังมาทางนี้!",
  ui_story_5051_50510701_81_dialog_content = "ดูว่า City Lord น่าประทับใจแค่ไหน?",
  ui_story_5051_50510701_82_dialog_content = "และเจ้าหญิงคาร์ลีนและเจ้าหญิงเวโรนิกาก็อยู่กับพระองค์ด้วย!",
  ui_story_5051_50510701_83_dialog_content = "เลดี้โจชัว—!",
  ui_story_5051_50510701_84_dialog_content = "บ้านชวาร์ตษ์จงเจริญ!",
  ui_story_5051_50510701_85_dialog_content = "เงยหน้าขึ้น เวโรนิก้า ทุกคนทักทายคุณ",
  ui_story_5051_50510701_86_dialog_content = "ใช่ถูกต้อง.",
  ui_story_5051_50510701_87_dialog_content = "ผ่อนคลายตรงนี้ จับมือฉันไว้",
  ui_story_5051_50510701_88_dialog_content = "(มีอายังคงดูค่อนข้างประหม่า)",
  ui_story_5051_50510701_89_dialog_content = "(ขบวนพาเหรดจะดำเนินต่อไปอีกระยะหนึ่ง เธอจะไหวไหม...?)",
  ui_story_5051_50510701_90_dialog_content = "(ไม่เคยคิดเลยว่า Schwartz Family Day จะเป็นงานเฉลิมฉลองที่ยิ่งใหญ่ในตอนนั้น)",
  ui_story_5051_50510701_91_dialog_content = "(แม้ว่างานเลี้ยงจะหรูหราเพียงพอ แต่ก็ยังไม่สามารถจุดเทียนเพื่อเฉลิมฉลองเมื่อสิบสองปีก่อนได้)",
  ui_story_5051_50510701_92_dialog_content = "(เกิดอะไรขึ้นในช่วงสิบสองปีเพื่อเปลี่ยนแปลงสิ่งนั้น)",
  ui_story_5051_50510701_93_dialog_content = "(นอกจากนี้ Eclipsites ที่ฉันเจอที่ประตูวันนี้ไม่ได้ถูกขนส่งโดยบังเอิญอย่างแน่นอน)",
  ui_story_5051_50510701_94_dialog_content = "(มีคนใช้ประโยชน์จากเทศกาลเพื่อลักลอบนำ Eclipsites เข้าสู่ Lumopolis)",
  ui_story_5051_50510701_95_dialog_content = "(Lumo Knights จะรับมือไหวหรือไม่ หรือสุดท้ายจะกลายเป็นหายนะครั้งใหญ่?)",
  ui_story_5051_50510701_96_dialog_content = "(ฉันหวังว่ามันจะไม่เป็นอันตรายต่อใคร)",
  ui_story_5051_50510701_97_dialog_content = "(อืม ทำไมฉันรู้สึกว่ามีคนมองฉันอยู่นะ?)",
  ui_story_5051_50510701_98_dialog_content = "(ไม่ได้ ทำไมดูฉันเมื่อฉันเป็นเพียงการนั่ง?)",
  ui_story_5051_50510701_99_dialog_content = "(และคุณร็อตเตือนฉันว่าอย่าเดินเตร็ดเตร่และทำลายขบวนพาเหรด)",
  ui_story_5051_50510701_100_dialog_content = "(หยุดสงสัย!)",
  ui_story_5051_50510701_101_dialog_content = "เฮ้, PlayerName! เมียหลวง!",
  ui_story_5051_50510701_102_dialog_content = "อืม เสียงดังเกินไปสำหรับพวกเขาที่จะได้ยินฉัน!",
  ui_story_5051_50510701_103_dialog_content = "อา—หยุดเสียแรงเสียที",
  ui_story_5051_50510701_104_dialog_content = "แม้ว่าพวกเขาจะได้ยินเสียงคุณ แต่พวกเขาก็ทิ้งขบวนพาเหรดไว้ให้คุณไม่ได้!",
  ui_story_5051_50510701_105_dialog_content = "ก็คงได้มั้ง...",
  ui_story_5051_50510701_106_dialog_content = "พูดสิ คุณรู้ได้อย่างไรว่าพวกเขาคือคนที่ฉันตามหา",
  ui_story_5051_50510701_107_dialog_content = "และคุณรู้ได้อย่างไรว่าพวกเขาจะอยู่ที่นี่?",
  ui_story_5051_50510701_108_dialog_content = "คุณไม่ได้ท้าทายฉันในการประลองดวงชะตาเหรอ?",
  ui_story_5051_50510701_109_dialog_content = "ฉันเพิ่งชนะ!",
  ui_story_5051_50510701_110_dialog_content = "...",
  ui_story_5051_50510701_111_dialog_content = "<size=45>อัศจรรย์!</size>",
  ui_story_5051_50510701_112_dialog_content = "<size=45>โปรดรับข้าเป็นลูกศิษย์ของท่าน!</size>",
  ui_story_5051_50510701_113_dialog_content = "โห ไม่ค่อยดัง คุณทำให้ฉันปวดหัว...",
  ui_story_5051_50510701_114_dialog_content = "ฉันไม่รับนักเรียน ฉันแค่มาที่นี่เพื่อทำงานแปลกๆ และหาเงินจากการดื่มเหล้า",
  ui_story_5051_50510701_115_dialog_content = "คืนนี้... พรุ่งนี้ หรืออาจจะเป็นวันถัดไป? อย่างไรก็ตาม ฉันจะไปทุกครั้งที่มีพอดื่ม",
  ui_story_5051_50510701_116_dialog_content = "อย่างน้อยโปรดบอกชื่อของคุณ!",
  ui_story_5051_50510701_117_dialog_content = "(เพื่อที่ฉันจะได้ตามหาเธอหลังจากที่ฉันออกมาจากคริสตัลนี้ได้แล้ว!)",
  ui_story_5051_50510701_118_dialog_content = "เอาล่ะ ตั้งแต่คุณลุกไปกินข้าว...",
  ui_story_5051_50510701_119_dialog_content = "ฉันชื่อโบอาส",
  ui_story_5051_50510701_120_dialog_content = "หา?",
