  ui_story_5051_50510701_199_dialog_content = "เข้าร่วม Lumo Knights ไหม ฉันไม่ได้คาดหวังให้คุณโดดเด่น เวโรนิก้า เพียงเพื่อคุณเท่านั้นที่ไม่ต้องเป็นห่วงแม่ของคุณ!",
  ui_story_5051_50510701_200_dialog_content = "รีบออกไป Mia!",
  ui_story_5051_50510701_201_dialog_content = "PlayerName...",
  ui_story_5051_50510701_202_dialog_content = "คุณไม่ต้องการกิ่งมะกอกของพ่อคุณเพื่อพิสูจน์ตัวเอง Mia",
  ui_story_5051_50510701_203_dialog_content = "City Lord มีอำนาจมาก แต่นั่นไม่ได้หมายความว่าเขาจะสามารถดูแลชีวิตคุณได้",
  ui_story_5051_50510701_204_dialog_content = "ไม่รู้ว่าคิดอะไรอยู่ในใจคุณ...",
  ui_story_5051_50510701_205_dialog_content = "แต่ฉันรู้ว่าคุณไม่ใช่คนที่คุณเมื่อสิบสองปีที่แล้ว!",
  ui_story_5051_50510701_206_dialog_content = "ฉัน...",
  ui_story_5051_50510701_207_dialog_content = "ฉันแน่ใจว่าคุณเกลียดความจริงที่ว่าชัยชนะนี้ถูกกำหนดไว้แล้ว",
  ui_story_5051_50510701_208_dialog_content = "ดังนั้นพิสูจน์ให้ทุกคนเห็นว่าคุณสามารถชนะได้ด้วยตัวคุณเอง",
  ui_story_5051_50510701_209_dialog_content = "แต่คู่ต่อสู้ของฉัน...",
  ui_story_5051_50510701_210_dialog_content = "หากเขาไม่เต็มใจที่จะต่อสู้กับคุณจริง ๆ ก็ทำให้เขา!",
  ui_story_5051_50510701_211_dialog_content = "ทำให้เขา? ผลักเขาออกไปทั้งหมด? แต่ฉันสามารถจัดการได้หรือไม่",
  ui_story_5051_50510701_212_dialog_content = "แน่นอน! พวกเขาไม่ได้บอกว่าเรื่องที่คุณกวาดล้าง Eclipsites ก่อนที่อัศวินจะปรากฏตัวก็กระจายไปทั่วเมืองแล้วไม่ใช่หรือ?",
  ui_story_5051_50510701_213_dialog_content = "แล้วยามธรรมดาจะเหมาะกับคุณได้อย่างไร!",
  ui_story_5051_50510701_214_dialog_content = "อะแฮ่ม เอ่อ ฉันยังอยู่ที่นี่...",
  ui_story_5051_50510701_215_dialog_content = "อ๊ะ อ๊ะ ขอโทษ...",
  ui_story_5051_50510701_216_dialog_content = "เนื่องจากคุณได้ยินทั้งหมดแล้ว ฉันเดาว่าเราจะต้องเปิดเผยมันออกมา",
  ui_story_5051_50510701_217_dialog_content = "คุณพร้อมไหม มีอา?",
  ui_story_5051_50510701_218_dialog_content = "คุณเชื่อในตัวฉันมาก PlayerName... นี่เป็นครั้งแรกที่มีคนเชื่อในตัวฉันมากขนาดนี้!",
  ui_story_5051_50510701_219_dialog_content = "ฉันพร้อม!",
  ui_story_5051_50510701_220_dialog_content = "ดีละถ้าอย่างนั้น-",
  ui_story_5051_50510701_221_dialog_content = "“White Night Up High นักรบผู้กล้าหาญ ฉันขอท้าประลองกับนาย!”",
  ui_story_5051_50510701_222_dialog_content = "\"รับดาบหรือเสียเกียรติของคุณ\"",
  ui_story_5051_50510701_223_dialog_content = "“คุณยอมรับคำท้าของฉันไหม ถือเป็นการประกาศว่าจะไม่เสียใจแม้ในกรณีที่ต้องตาย!”",
  ui_story_5051_50510701_224_dialog_content = "เอ่อ ความตายไม่ได้ไปไกลเกินไปหน่อยเหรอ...?",
  ui_story_5051_50510701_225_dialog_content = "ใช่ ได้โปรดละเว้นฉันด้วยผลที่ฉันไม่สามารถแบกรับความรับผิดชอบสำหรับ...",
  ui_story_5051_50510701_226_dialog_content = "ว-ก็ ฉันแค่พูดซ้ำจากนิยาย...",
  ui_story_5051_50510701_227_dialog_content = "เฮ้อ... เอาล่ะ ฉันสัญญาว่าจะไม่ยอมแพ้ง่ายๆ",
  ui_story_5051_50510701_228_dialog_content = "แต่ถ้าคุณเอาชนะฉันไม่ได้ ฉันก็ยังยอมทำตามคำสั่ง เพราะฉันแค่ทำงาน",
  ui_story_5051_50510701_229_dialog_content = "นั่นจะดีมาก ขอบคุณ!",
  ui_story_5051_50510701_230_dialog_content = "ดังนั้น ดาบพิธีการ...",
  ui_story_5051_50510701_231_dialog_content = "คุณควรทำอย่างนั้น Mia",
  ui_story_5051_50510701_232_dialog_content = "ขวา. โปรดอย่าทำร้ายตัวเอง",
  ui_story_5051_50510701_233_dialog_content = "ฉันคิดว่า Mia อาจทำร้ายคุณ!",
  ui_story_5051_50510701_234_dialog_content = "ว-อะไร?",
  ui_story_5051_50510701_235_dialog_content = "นั่นสิ",
  ui_story_5051_50510701_236_dialog_content = "คุณเอาแต่พูดชื่อมีอา...",
  ui_story_5051_50510701_237_dialog_content = "เด็กสาวซุกซนตรงหน้าฉันคนนี้คือเจ้าหญิงเวโรนิกาผู้อ่อนโยนจริงๆ หรือ?",
  ui_story_5051_50510701_238_dialog_content = "ว-ทำไม แน่นอน! เมียหลวงก็แค่...",
  ui_story_5051_50510701_239_dialog_content = "เมียเป็นแค่ชื่อเล่นระหว่างเรา!",
  ui_story_5051_50510701_240_dialog_content = "อ่อ ค่ะ...",
  ui_story_5051_50510701_241_dialog_content = "มันขึ้นอยู่กับเวลา. เจอกันที่สนามเร็วๆ นี้ ฝ่าบาท",
  ui_story_5051_50510701_242_dialog_content = "ตกลง. เพียงให้แน่ใจว่าคุณไม่มีอะไรค้างคาจนจบ!",
  ui_story_5051_50510701_243_dialog_content = "ฉันจะ...",
  ui_story_5051_50510701_244_dialog_content = "(ไม่ได้แค่ส่งไปทำงานเหรอ ทำไมรู้สึกเหมือนเพิ่งดูละครวัยรุ่นมา)",
  ui_story_5051_50510802_1_dialog_content = "(ฉันได้ยินเสียงฝูงชนคำรามแม้จากที่นี่)",
  ui_story_5051_50510802_2_dialog_content = "(เดาว่าการเฉลิมฉลองได้เริ่มขึ้นแล้ว)",
  ui_story_5051_50510802_3_dialog_content = "(ได้เวลาขโมย Crystal of Eternal Memory...)",
  ui_story_5051_50510802_4_dialog_content = "เฮ้ คุณอยู่ตรงนั้น หยุด",
  ui_story_5051_50510802_5_dialog_content = "(ทำไมยังมียามอยู่ที่นี่?)",
  ui_story_5051_50510802_6_dialog_content = "ฉันต้องขอให้คุณเคลียร์ตัวตนของคุณ",
  ui_story_5051_50510802_7_dialog_content = "ตัวตนของฉัน? ฉันเซอร์คาเลบ แม็กนัส! ฉันไม่จำเป็นต้องพิสูจน์ว่าฉันเป็นใคร!",
  ui_story_5051_50510802_8_dialog_content = "เซอร์ คาเลบ แม็กนัส...?!",
  ui_story_5051_50510802_9_dialog_content = "ไม่ เขาไปเยี่ยมเลดี้โจชัวเมื่อสองสามวันก่อน",
  ui_story_5051_50510802_10_dialog_content = "คุณมีความคล้ายคลึงกันบางอย่าง แต่ผมของเขาสั้นกว่ามากและเขามีโครงสร้างที่แตกต่างออกไป!",
