  ui_story_5051_50510802_17_dialog_content = "เฮ้ ทำไมมันเมาค้าง?",
  ui_story_5051_50510802_18_dialog_content = "ก็นายยังหน้าบึ้งไม่ยอมคุยกับฉันตรงๆ...",
  ui_story_5051_50510802_19_dialog_content = "นั่นเป็นเพราะคุณเพิ่งจัดการกับฉันทั้งน้ำตาและน้ำมูกไหล",
