  ui_story_5051_50510802_25_dialog_content = "คุณรู้เกี่ยวกับคาถาเพื่อเข้าสู่ Crystal of Eternal Memory มากแค่ไหน?",
  ui_story_5051_50510802_26_dialog_content = "เหตุใดผู้ที่เข้าไปจึงไม่เพียงมองไม่เห็น แต่ยังกระจัดกระจายไปทั่วโลก",
