  ui_story_5051_50510802_32_dialog_content = "จริงอยู่ว่าฉันแทบไม่ได้กลับบ้านเลย แต่มันเป็นไปไม่ได้สำหรับ Jakine ที่เดินไม่ได้ด้วยซ้ำ...",
