  ui_story_5051_50510802_34_dialog_content = "ฉันเป็นคนหนึ่งที่คิดว่าเรื่องทั้งหมดนี้เป็นเรื่องตลก!",
  ui_story_5051_50510802_35_dialog_content = "แต่แม่คะ คุณเป็นผู้ทำนายที่ลึกลับ น่าทึ่ง และเหนือธรรมชาติไม่ใช่เหรอ?",
  ui_story_5051_50510802_36_dialog_content = "ทำไมคุณถึงเป็นวินโดว์ตัวใหญ่?",
