  ui_story_5051_50510802_46_dialog_content = "เพื่อเข้าสู่โลกนี้ ฉันแต่งคาถาตามบันทึกที่คุณทิ้งไว้",
  ui_story_5051_50510802_47_dialog_content = "แต่เมื่อฉันมาถึงที่นี่ ไม่เพียงแต่ไม่ได้สวมเสื้อผ้าเท่านั้น แต่ยังถูกแยกจากเพื่อนๆ...",
