  ui_story_5051_50510802_49_dialog_content = "อ้อเหรอ...",
  ui_story_5051_50510802_50_dialog_content = "คุณได้รับมัน?",
  ui_story_5051_50510802_51_dialog_content = "ฉันเห็นแม่ของคุณและฉันไม่เพียงแต่ใช้ชื่อเดียวกันเท่านั้น แต่เธอยังขโมยผลงานของฉันด้วย!",
  ui_story_5051_50510802_52_dialog_content = "ชื่อของฉันน่าจะนำโชคมาให้ผู้คน แต่แม่คุณ... ไม่ซะทีเดียว",
