  ui_story_5051_50510802_61_dialog_content = "ฉันเป็นอัจฉริยะที่ไม่เคยมีมาก่อน?",
  ui_story_5051_50510802_62_dialog_content = "ฮ่า ฮ่า ฮ่า ถ้าฉันเป็นแม่ของเธอ ฉันคงดีใจเหมือนหอย!",
