  ui_story_5051_50510802_67_dialog_content = "ได้สิ",
  ui_story_5051_50510802_68_dialog_content = "โฆษณาชวนเชื่อ! โฆษณาชวนเชื่อ! โฆษณาชวนเชื่อ!",
