  ui_story_5051_50510802_90_dialog_content = "ถ้าคุณไม่สวมเสื้อผ้า แม้แต่ลมหายใจของคุณก็อาจเปลี่ยนโลกได้",
  ui_story_5051_50510802_91_dialog_content = "ว่าไง",
  ui_story_5051_50510802_92_dialog_content = "หากคุณถูกสังเกตเห็นที่นี่ ทุกสิ่งรอบตัวคุณจะถูกปรับเปลี่ยน",
