  ui_story_5051_50510802_94_dialog_content = "จนในที่สุด อะไรนะ?",
  ui_story_5051_50510802_95_dialog_content = "คุณกลายเป็นส่วนหนึ่งของโลกนี้และ <color=#FFB400>ไม่สามารถออกไปได้</color>.",
