  ui_story_5051_50510802_100_dialog_content = "ตราบใดที่ยังไม่หมดวัน คุณก็น่าจะโอเค! อาจจะ.",
  ui_story_5051_50510802_101_dialog_content = "เรายังทำได้! ต้องกลับไปพบกับทุกคนและออกไปจากที่นี่!",
  ui_story_5051_50510802_102_dialog_content = "ขอบคุณแม่! ลาก่อน แล้ววันหนึ่งฉันจะพาเธอกลับบ้าน!",
