  ui_story_5051_50510901_7_dialog_content = "<anim type=Shake><size=42>แดเนียล! เวโรนิก้า! คาร์ลีน!</size></anim>",
  ui_story_5051_50510901_8_dialog_content = "<color=#e8d9bb>ครืน!</color>",
  ui_story_5051_50510901_9_dialog_content = "อะไรนะ!",
  ui_story_5051_50510901_10_dialog_content = "PlayerName เป็นอะไรรึเปล่า?",
  ui_story_5051_50510901_11_dialog_content = "ทำไมจู่ๆคุณถึงดูป่วย?",
  ui_story_5051_50510901_12_dialog_content = "N-ไม่มีอะไร เสียงฟ้าร้องทำให้ฉันกระโดด นั่นคือทั้งหมด",
  ui_story_5051_50510901_13_dialog_content = "ฟ้าผ่า?",
  ui_story_5051_50510901_14_dialog_content = "ฉันได้ยินเมื่อเช้านี้ แต่อันนี้ดังกว่านั้น",
  ui_story_5051_50510901_15_dialog_content = "บางทีพายุกำลังมา",
  ui_story_5051_50510901_16_dialog_content = "ทำไมฉันไม่ได้ยินเสียงฟ้าร้องเลย",
  ui_story_5051_50510901_17_dialog_content = "อะไร มันไม่ดังพอที่คุณจะได้ยินเหรอ?",
  ui_story_5051_50510901_18_dialog_content = "ถึงมีฉันก็ไม่กลัว",
  ui_story_5051_50510901_19_dialog_content = "เอ๊ะ ฮ่าฮ่า คาร์ลีน... เจ้าหญิงคาร์ลีนเป็นเด็กที่กล้าหาญจริงๆ",
