  ui_story_5051_50510901_21_dialog_content = "...",
  ui_story_5051_50510901_22_dialog_content = "คาร์ลีน?",
  ui_story_5051_50510901_23_dialog_content = "(เธอวิ่งกลับไปหาเลดี้โจชัวอีกครั้ง)",
  ui_story_5051_50510901_24_dialog_content = "(สายตาของเธอยังคงเหมือนเดิมในตอนนี้)",
  ui_story_5051_50510901_25_dialog_content = "นั่นคือสิ่งที่เจ้าหญิงคาร์ลีนเป็น เธออาจจะไม่พอใจถ้าคุณปฏิบัติกับเธอเหมือนเด็ก",
  ui_story_5051_50510901_26_dialog_content = "อย่างไรก็ตาม คุณอาจเป็นคนแรกที่เธอสนใจ",
  ui_story_5051_50510901_27_dialog_content = "สนใจอะไร",
  ui_story_5051_50510901_28_dialog_content = "เจ้าไม่สังเกตหรือว่าฝ่าบาทเฝ้าสังเกตเจ้ามานานแล้ว?",
  ui_story_5051_50510901_29_dialog_content = "เธอยังเตือนฉันอยู่หรือเปล่า...?",
  ui_story_5051_50510901_30_dialog_content = "เอ่อ มีอา... เวโรนิก้ายังคงต่อสู้กับทหาร ฉันต้องฝังรากลึกเธอ!",
  ui_story_5051_50510901_31_dialog_content = "นี่คือสิ่งที่ฉันทำได้!",
  ui_story_5051_50510901_32_dialog_content = "อึก...ไอ ไอ ไอ",
  ui_story_5051_50510901_33_dialog_content = "เจ้าหญิงเวโรนิกายังคงใช้กำลังไม่เต็มที่ แต่เธอก็เหนือกว่าคู่ต่อสู้ของเธอ",
  ui_story_5051_50510901_34_dialog_content = "เพียงไม่กี่วันเธอก็ก้าวหน้าอย่างน่าประหลาดใจ",
  ui_story_5051_50510901_35_dialog_content = "ฉันสงสัยว่าคุณทำอะไรให้เจ้าหญิงเวโรนิกา PlayerName.",
  ui_story_5051_50510901_36_dialog_content = "(มีอาแทบไม่เชื่อในตัวเองเลยตลอดทาง)",
  ui_story_5051_50510901_37_dialog_content = "(ดังนั้นเธอจึงไม่เคยมีตัวแทนเป็นนักสู้ที่ดีมาก่อนในอดีต?)",
  ui_story_5051_50510901_38_dialog_content = "การรักษาความเงียบ? ฉันเดาว่ามันเป็นอีกหนึ่งความลับที่ฉันไม่ควรรู้",
  ui_story_5051_50510901_39_dialog_content = "จริงๆแล้วมันไม่ใช่ความลับ",
  ui_story_5051_50510901_40_dialog_content = "เวโรนิกานั้นน่าเกรงขามเสมอ เธอไม่เคยตระหนักถึงมันในอดีต",
  ui_story_5051_50510901_41_dialog_content = "งั้นเหรอ",
  ui_story_5051_50510901_42_dialog_content = "มันปิด! เจ้าหญิงเวโรนิกาเกือบฟาดยามคนนั้น",
  ui_story_5051_50510901_43_dialog_content = "ฉันสามารถเห็นประกายไฟจากดาบที่กระทบกันจากที่นี่... ช่างเป็นการดวลที่แท้จริง!",
  ui_story_5051_50510901_44_dialog_content = "จากนี้ไป เราจะเป็นกำลังใจให้คุณเท่านั้น เจ้าหญิงเวโรนิกา!",
  ui_story_5051_50510901_45_dialog_content = "เย่!",
  ui_story_5051_50510901_46_dialog_content = "เจ้าหญิงเวโรนิกาได้รับเสียงปรบมือและเสียงเชียร์จากทักษะการต่อสู้ด้วยดาบของเธอ",
  ui_story_5051_50510901_47_dialog_content = "เมื่อพูดถึงเรื่องนี้ คุณคิดผิดหรือเปล่าว่าเสียงปรบมือเป็นเสียงฟ้าร้อง?",
  ui_story_5051_50510901_48_dialog_content = "งั้นเหรอครับ...?",
  ui_story_5051_50510901_49_dialog_content = "(เดี๋ยวก่อน!)",
  ui_story_5051_50510901_50_dialog_content = "(ทำไมฉันถึงรู้สึกเย็นลงกระดูกสันหลังของฉัน?)",
  ui_story_5051_50510901_51_dialog_content = "(มีคนกำลังดูฉันอยู่!)",
  ui_story_5051_50510901_52_dialog_content = "(ไม่ใช่ Carleen, City Lord หรือ Lady Joshua ที่ต่างก็จับจ้องไปที่การต่อสู้ของลูกสาว)",
  ui_story_5051_50510901_53_dialog_content = "(อย่าบอกนะว่าบรรยากาศนี้คือ...)",
  ui_story_5051_50510901_54_dialog_content = "จะไปไหนน่ะ PlayerName?",
