  ui_story_5051_50510901_65_dialog_content = "คนหนุ่มสาวชอบการเฉลิมฉลอง ดังนั้นฉันคิดว่าจะพบคุณที่นี่",
  ui_story_5051_50510901_66_dialog_content = "ฉันแค่ไม่คิดว่าคุณจะได้เจอ <color=#FFB400>ฉันในเวอร์ชั่นโลกนี้</color> เร็ว ๆ นี้.",
