  ui_story_5051_50510901_81_dialog_content = "อะแฮ่ม. ถ้าคุณหมายถึงเลดี้โจชัว คาร์ลีนในวัยเยาว์ และลอร์ดชวาร์ตซ์แห่งโลกนี้...",
  ui_story_5051_50510901_82_dialog_content = "ใช่ พวกเขาพบและยอมรับ Mia แม้กระทั่งเรียกเธอว่า Veronica",
