  ui_story_5051_50510901_86_dialog_content = "การกระทำของเราทำให้อาณาจักรนี้หยุดชะงัก",
  ui_story_5051_50510901_87_dialog_content = "แล้วคุณล่ะ... ทำไมคุณถึงทำให้ Mia ตกอยู่ในอันตรายโดยปล่อยให้เธอต่อสู้กับผู้คุม?",
  ui_story_5051_50510901_88_dialog_content = "คุณเคยคิดที่จะแตกกิ่งก้านสาขาไหมถ้าเธอเจ็บปวด?",
  ui_story_5051_50510901_89_dialog_content = "ในฐานะลูกสาวของ Lumopolis City Lord มีอาถูกซ่อนตัวอยู่ใน Umbraton",
  ui_story_5051_50510901_90_dialog_content = "พ่อของเธอเคยพิจารณาถึงผลกระทบหรือไม่หากมีอาได้รับบาดเจ็บในอัมบราตัน",
  ui_story_5051_50510901_91_dialog_content = "จำไว้นะหนุ่มๆ",
  ui_story_5051_50510901_92_dialog_content = "หากคุณไม่รู้ทุกแง่มุมของเรื่องราว อย่าตัดสินก่อนเวลาอันควร",
