  ui_story_5051_50510901_96_dialog_content = "ย้ายที่ดี!",
  ui_story_5051_50510901_97_dialog_content = "เจ้าหญิงเวโรนิก้า! เจ้าหญิงเวโรนิก้า! เจ้าหญิงเวโรนิก้า!",
