  ui_story_5051_50510901_99_dialog_content = "เมียหลวงที่ฉันเคยรู้จักไม่สามารถต่อสู้ได้",
  ui_story_5051_50510901_100_dialog_content = "แต่ตอนนี้เธอกลายเป็นคนที่น่าเกรงขามในการต่อสู้แล้ว...",
  ui_story_5051_50510901_101_dialog_content = "มีอาต้องการคว้าโอกาสนี้เพื่อแสดงให้พ่อเห็นว่าเธอสามารถทำได้มากกว่านี้",
  ui_story_5051_50510901_102_dialog_content = "อย่างไรก็ตาม ตอนนี้ยังไม่ใช่เวลาที่เหมาะสม",
  ui_story_5051_50510901_103_dialog_content = "เราต้องยุติการแข่งขันเพื่อ Mia นี้โดยเร็ว PlayerName.",
