  ui_story_5051_50510901_106_dialog_content = "คุณรู้ไหมว่าเกิดอะไรขึ้นในพิธีในปีนั้น PlayerName?",
  ui_story_5051_50510901_107_dialog_content = "หา?",
  ui_story_5051_50510901_108_dialog_content = "ฉันจะให้ทุกอย่างที่มีตอนนี้ เจ้าหญิงเวโรนิกา!",
