  ui_story_5051_50510901_111_dialog_content = "<color=#e8d9bb>แกล๊ง!</color>",
  ui_story_5051_50510901_112_dialog_content = "อะไรนะ... คุณบล็อกมันด้วยเหรอ?",
  ui_story_5051_50510901_113_dialog_content = "ฉันโชคดี",
  ui_story_5051_50510901_114_dialog_content = "(เขาทุ่มเทมากในการระเบิดฉันแทบจะไม่สามารถต่อสู้กับมันได้)",
  ui_story_5051_50510901_115_dialog_content = "(สงสัยว่าถ้า PlayerName เห็นว่า?)",
  ui_story_5051_50510901_116_dialog_content = "(เฮ้ย..อยู่ไหน. PlayerName?)",
  ui_story_5051_50510901_117_dialog_content = "(โดนชะมัด!แต่คนข้างๆ...)",
  ui_story_5051_50510901_118_dialog_content = "ระวังเวโรนิก้า!",
  ui_story_5051_50510901_119_dialog_content = "สวัสดี!",
  ui_story_5051_50510901_120_dialog_content = "(ว่าไงนะ ฉันไม่คิดว่าฉันจะเอาอันนี้ไปได้)",
