  ui_story_5051_50510901_125_dialog_content = "(ไม่สิ ฉันจะลืมความจริงที่ว่าพ่อไม่ให้ฉันเรียกฮิปโปคาได้ยังไง...)",
  ui_story_5051_50510901_126_dialog_content = "(แต่พลังงานที่ฉันชาร์จไปแล้วล่ะ มันจะลงเอยด้วยการทำร้ายผู้พิทักษ์)",
  ui_story_5051_50510901_127_dialog_content = "(สิ่งที่ต้องทำในสิ่งที่จะทำอย่างไร?)",
  ui_story_5051_50510901_128_dialog_content = "(กล่องพวกนั้นคืออะไร? บางทีพวกมันอาจทนแรงได้!)",
