  ui_story_5051_50510901_134_dialog_content = "คุณตั้งชื่อแมงมุมที่มีหัวเป็นม้า?",
  ui_story_5051_50510901_135_dialog_content = "คาร์ลีนมีม้าด้วยไม่ใช่เหรอ?",
  ui_story_5051_50510901_136_dialog_content = "คุณไม่มีพรสวรรค์ในการต่อสู้ เวโรนิก้า เถียงเกี่ยวกับเรื่องนี้ไม่เพิ่มเติม",
  ui_story_5051_50510901_137_dialog_content = "เฮ้อ...",
