  ui_story_5051_50510901_148_dialog_content = "<anim type=Shake>ก๊ากกก!</anim>",
  ui_story_5051_50510901_149_dialog_content = "ฉันรู้ว่าฉันไม่ควรพยายามอวดที่นี่...",
