  ui_story_5051_50511001_24_dialog_content = "ฉันสอนความลับของฉันให้คุณ!",
  ui_story_5051_50511001_25_dialog_content = "ใช่แล้ว คุณพูดถูก!",
  ui_story_5051_50511001_26_dialog_content = "และนี่เป็นครั้งแรกที่ฉันสามารถระบุที่อยู่ของใครบางคนได้อย่างแม่นยำ!",
  ui_story_5051_50511001_27_dialog_content = "แต่กลับ...",
  ui_story_5051_50511001_28_dialog_content = "บอกฉันได้ไหมว่า \"Abracadabra\" หมายถึงอะไรในตอนนี้?",
