  ui_story_5051_50511001_32_dialog_content = "มันควรจะดีที่นี่ใช่มั้ย?",
  ui_story_5051_50511001_33_dialog_content = "เราควรถอยห่างออกมาหน่อยเพื่อความปลอดภัย ติดตามต่อไป!",
