  ui_story_5051_50511001_36_dialog_content = "ขออนุญาต-",
  ui_story_5051_50511001_37_dialog_content = "ว่าไง",
  ui_story_5051_50511001_38_dialog_content = "โอ้ คุณดูเด็กกว่าฉัน!",
  ui_story_5051_50511001_39_dialog_content = "มีอะไรให้ช่วยไหม",
  ui_story_5051_50511001_40_dialog_content = "โอ้ ฉันแค่สงสัยว่าเกิดอะไรขึ้นที่จัตุรัส",
  ui_story_5051_50511001_41_dialog_content = "ยังไม่มีอะไรเจาะจง แต่ฉันได้รับคำสั่งให้เป็นผู้นำการอพยพ",
