  ui_story_5051_50511001_43_dialog_content = "รอสักครู่ ลักษณะของคุณ...",
  ui_story_5051_50511001_44_dialog_content = "โอ้ ทุกคนบอกฉันว่าฉันดูเหมือนแม่ของฉัน... เอ่อ ฉันหมายถึงโบอาส",
  ui_story_5051_50511001_45_dialog_content = "ผมยาวสีแดงและดวงตาสีเขียว... คุณคือ Jakine หรือเปล่า?",
