  ui_story_5051_50511101_75_dialog_content = "เราต้องออกจากที่นี่วันนี้!",
  ui_story_5051_50511101_76_dialog_content = "ชู่วว...",
  ui_story_5051_50511101_77_dialog_content = "ปัญหา, PlayerName?",
  ui_story_5051_50511101_78_dialog_content = "โอ้ อยากรู้ไหมว่าใครคือผู้หญิงที่เมากับฉัน?",
  ui_story_5051_50511101_79_dialog_content = "มันค่อนข้างซับซ้อน แต่ฉันสามารถแนะนำอัศวินที่ช่วยเราได้อย่างแน่นอน!",
  ui_story_5051_50511101_80_dialog_content = "เฮ้เธออยู่ที่ไหน",
  ui_story_5051_50511101_81_dialog_content = "เธอเพิ่งออกไปหลังจากเห็นว่าฉันพบเพื่อนของฉันแล้วเหรอ?",
  ui_story_5051_50511101_82_dialog_content = "เอาล่ะ ทุกคนในลูโมโปลิสจะบอกลาเหมือนคนทั่วไปไม่ได้เหรอ?",
  ui_story_5051_50511101_83_dialog_content = "เฮ้ เขาคือคนที่เธอตามหาใช่ไหม สาวน้อย?",
  ui_story_5051_50511101_84_dialog_content = "ทำไมเขาถึงดูคุ้นเคยกับฉัน?",
  ui_story_5051_50511101_85_dialog_content = "โบอาส? เมื่อคืนคุณไม่ได้ออกเดินทางไปนอร์ธแลนด์ตามกำหนดใช่ไหม",
  ui_story_5051_50511101_86_dialog_content = "ฉันไม่ได้มาที่ลูโมโปลิสบ่อยๆ *สะอึก* ฉันเลยคิดว่าฉันจะผ่อนคลายสักหน่อย",
  ui_story_5051_50511101_87_dialog_content = "โอ้ ฉันจำได้แล้ว จากเมื่อวานนี้...",
  ui_story_5051_50511101_88_dialog_content = "คุณคือเจ้าเมืองคนนั้น!",
  ui_story_5051_50511101_89_dialog_content = "(อะไรนะ นี่คือเจ้าเมืองเหรอ)",
  ui_story_5051_50511101_90_dialog_content = "(ไม่แปลกใจ. PlayerName กำลังขยิบตาให้ฉัน...)",
  ui_story_5051_50511101_91_dialog_content = "<size=30>PlayerName, มานี่สิ!</size>",
  ui_story_5051_50511101_92_dialog_content = "หึ ใจเย็นๆ...",
  ui_story_5051_50511101_93_dialog_content = "พูดว่าเกิดอะไรขึ้นกับทั้งหมดนี้?",
  ui_story_5051_50511101_94_dialog_content = "นั่นคือสิ่งที่ฉันพยายามแก้ไข แต่ตอนนี้มันซับซ้อนมากขึ้นเมื่อคุณปรากฏตัวด้วย...",
  ui_story_5051_50511101_95_dialog_content = "จะมีอะไรซับซ้อนได้อย่างไร มันอาจจะอยู่ในหัวของคุณ",
  ui_story_5051_50511101_96_dialog_content = "อย่างไรก็ตาม City Lord เพิ่งสังเกตเห็น City Lord และเข้าใจผิดว่าเขาเป็นผู้ลักพาตัว...",
  ui_story_5051_50511101_97_dialog_content = "ทำไมฉันยิ่งรู้สึกสูญเสียจากสิ่งนั้น?",
  ui_story_5051_50511101_98_dialog_content = "เลยบอกว่าซับซ้อนมาก...",
  ui_story_5051_50511101_99_dialog_content = "ปัญหาคือเราจะบอก City Lord จากอีกคนหนึ่งได้อย่างไร",
  ui_story_5051_50511101_100_dialog_content = "ฉันเพิ่งบอกพวกเขาว่าเจ้าเมืองที่มาที่นี่กับเราคือพ่อของฉัน โซรอซ...",
  ui_story_5051_50511101_101_dialog_content = "โซรอซ? นั่นไม่ใช่ชื่อของยักษ์ใหญ่ของคุณหรือ PlayerName?",
  ui_story_5051_50511101_102_dialog_content = "ตอนนั้นกำลังกดชื่อ...",
  ui_story_5051_50511101_103_dialog_content = "คนหนึ่งคือชวาร์ตษ์แก่ อีกคนหนึ่งคือชวาร์ตษ์หนุ่ม มันจะไม่ง่ายกว่าเหรอ?",
  ui_story_5051_50511101_104_dialog_content = "นั่นอาจไม่สุภาพต่อ City Lord แต่เพื่อความสะดวก...",
  ui_story_5051_50511101_105_dialog_content = "ดังนั้น Schwartz ชราจึงพยายามพา Mia ออกไป แต่ Schwartz วัยเยาว์เท่านั้นที่เข้าใจผิดว่าเขาเป็นผู้ลักพาตัว",
  ui_story_5051_50511101_106_dialog_content = "ตอนนี้เรากำลังพยายามออกจากการผูกมัด!",
  ui_story_5051_50511101_107_dialog_content = "อา ฉันเข้าใจแล้วตั้งแต่คุณพูดแบบนั้น!",
  ui_story_5051_50511101_108_dialog_content = "ไหวสิ!",
  ui_story_5051_50511101_109_dialog_content = "ฉันไม่เป็นไร ฉันไม่... เสียเปล่าเลย!",
  ui_story_5051_50511101_110_dialog_content = "เอาล่ะ ช่วยบอกฉันทีว่าหญิงสาวคนนั้นคือใคร?",
  ui_story_5051_50511101_111_dialog_content = "ฉันทำเองได้! ฉัน ลูกศิษย์ของโบอาส!",
  ui_story_5051_50511101_112_dialog_content = "ข้าพเจ้าไม่ทราบว่าพระองค์ได้ส่งคณะทูตมาสองครั้งในครั้งนี้",
  ui_story_5051_50511101_113_dialog_content = "แน่นอนว่าเจ้าเมืองจะไม่รู้ เนื่องจากมีทูตเพียงคนเดียว",
  ui_story_5051_50511101_114_dialog_content = "ฉันเป็นแค่ผู้ติดตาม! ลูกน้องก็มีงานให้ทำ!",
  ui_story_5051_50511101_115_dialog_content = "งานของฉันแตกต่างจากงานของโบอาส ดังนั้นฉันจึงไม่ได้พบคุณและผู้หญิงของคุณ",
