  ui_story_5051_50511101_122_dialog_content = "<size=30>*กระแอม* บอกว่าใช่! *ไอ*</size>",
  ui_story_5051_50511101_123_dialog_content = "ฮะ? โอ้...",
  ui_story_5051_50511101_124_dialog_content = "ฉันจะไม่ปฏิเสธคำเชิญจากราชินีอย่างแน่นอน!",
  ui_story_5051_50511101_125_dialog_content = "นั่นถูกต้องใช่ไหม? เยี่ยมมาก!",
  ui_story_5051_50511101_126_dialog_content = "เจ้านายของฉันทำงานของเธอ และฉันก็ทำงานของฉัน",
  ui_story_5051_50511101_127_dialog_content = "เราทุกคนสามารถกลับไปที่ Northland อย่างมีความสุขได้แล้ว!",
