  ui_story_5051_50511101_143_dialog_content = "(หมายความว่ายังไง ตอนนี้พวกเราทุกคนเป็นเบี้ยของชวาร์ตษ์หนุ่มหรือเปล่า?)",
  ui_story_5051_50511101_144_dialog_content = "(แต่พวกเราไม่กี่คนสามารถให้ประโยชน์อะไรกับเขาได้บ้าง?)",
