  ui_story_5051_50511101_146_dialog_content = "(เพราะเขาปฏิบัติต่อผู้อื่นเหมือนตัวหมากรุกด้วยวิธีนี้?)",
  ui_story_5051_50511101_147_dialog_content = "<size=30>PlayerNameคุณควรรู้ว่าตอนนี้หมากรุกเป็นมากกว่าเกม</size>",
