  ui_story_5051_50511101_160_dialog_content = "คุณโรจน์ไม่ได้ละเลยหน้าที่ของเธอ เมื่อเทียบกับฉัน พลเรือนต้องการความช่วยเหลือจากเธอมากกว่า",
