  ui_story_5051_50511102_15_dialog_content = "เราหมดเวลาแล้ว เดอะ <color=#FFB400>การจลาจล</color> กำลังเกิดขึ้น ทุกวินาทีที่นี่มีแต่จะเพิ่มอันตราย!",
  ui_story_5051_50511102_16_dialog_content = "จลาจล?",
  ui_story_5051_50511102_17_dialog_content = "ทำไมฉันจำอะไรไม่ได้เลย ฉันรู้เรื่องนี้ในตอนนั้นหรือไม่?",
  ui_story_5051_50511102_18_dialog_content = "อย่ากดดันตัวเอง Mia!",
  ui_story_5051_50511102_19_dialog_content = "<color=#e8d9bb>ฟิ้วววว!</color>",
  ui_story_5051_50511102_20_dialog_content = "นั่นคือใคร?",
  ui_story_5051_50511102_21_dialog_content = "ดูเหมือนว่าจะบินลงมาจากท้องฟ้าและติดตามเป้าหมายที่เฉพาะเจาะจง?",
  ui_story_5051_50511102_22_dialog_content = "เป้าหมายได้หรือไม่ <color=#FFB400>หนุ่มชวาร์ตษ์</color>?",
  ui_story_5051_50511102_23_dialog_content = "Young Schwartz ให้ความสนใจกับศัตรูมากเกินไปจนสังเกตเห็นอันตรายจากเบื้องบน!",
  ui_story_5051_50511102_24_dialog_content = "ไม่มีทาง แม้แต่เจ้าเมืองคนเก่าของเราก็จะได้เห็นมัน!",
