  ui_story_5051_50511102_39_dialog_content = "A-คุณเป็นคนเลวด้วยเหรอ?",
  ui_story_5051_50511102_40_dialog_content = "สวัสดีเจ้าหญิงน้อย!",
  ui_story_5051_50511102_41_dialog_content = "D-อย่าคิดว่าฉันกลัวคุณ!",
