  ui_story_5051_50511201_29_dialog_content = "ยกเว้นว่าอาการบาดเจ็บของคาร์ลีนจะแย่กว่านั้น และฉันไม่ได้อยู่ที่นั่นเพื่อปกป้องเธอ",
  ui_story_5051_50511201_30_dialog_content = "นั่นเป็นเหตุผลที่คุณไปไม่ได้เมื่อได้ยินเสียงของเธอ",
