  ui_story_5051_50511301_16_dialog_content = "<size=30>ไม่ต้องกลัว มีอา ฉันไม่ได้มาที่นี่เพื่อพาคุณกลับ</size>",
  ui_story_5051_50511301_17_dialog_content = "<size=30>ฉันไตร่ตรองแล้วและคุณมีสิทธิ์ที่จะรู้ประวัติศาสตร์ส่วนนี้</size>",
  ui_story_5051_50511301_18_dialog_content = "นายโซรอซ? ฉันรู้ว่าเราจะได้พบกันอีกในไม่ช้า",
  ui_story_5051_50511301_19_dialog_content = "แม้ว่าฉันไม่ได้คาดหวังว่ามันจะเร็วขนาดนี้",
  ui_story_5051_50511301_20_dialog_content = "ทันใดนั้นฉันก็นึกขึ้นได้ว่าฉันอาจมีโอกาสในการขายที่คุณกำลังมองหา",
  ui_story_5051_50511301_21_dialog_content = "ฉันหวังว่าคุณจะไม่ทำให้ฉันล่าช้าโดยเจตนา",
  ui_story_5051_50511301_22_dialog_content = "ไม่แน่นอน ฉันยังหวังว่าลูกที่ดื้อรั้นของฉันจะกลับบ้านพร้อมกับฉันด้วยความเต็มใจ",
  ui_story_5051_50511301_23_dialog_content = "อย่างไรก็ตาม ฉันขอให้คุณสัญญาว่าคุณจะไม่ติดตามแหล่งข้อมูลของฉัน",
  ui_story_5051_50511301_24_dialog_content = "แน่นอน ฉันสัญญาว่าจะไม่ไล่ตามแหล่งที่มาของคุณ บอกฉันที คุณมีเบาะแสอะไรบ้าง?",
  ui_story_5051_50511301_25_dialog_content = "มีร่องรอยของกองทัพส่วนตัวตั้งค่ายบนสนามที่ยังไม่ได้รับการพัฒนาในลูโมโพลิสตอนล่าง",
  ui_story_5051_50511301_26_dialog_content = "คุณได้ยินไหม คุณร็อต?",
  ui_story_5051_50511301_27_dialog_content = "ถิ่นทุรกันดารใกล้ชานเมือง...",
  ui_story_5051_50511301_28_dialog_content = "เนินหินขนาดนั้นได้ไหมครับ?",
  ui_story_5051_50511301_29_dialog_content = "ฉันเคยได้ยินเรื่องราวเกี่ยวกับเสียงร้องแปลกๆ ของสัตว์เป็นครั้งคราว แต่มันรกร้าง",
  ui_story_5051_50511301_30_dialog_content = "คุณกำลังพูดว่า คุณโซรอซ นั่นคือที่ที่พวกคาร์ติมาสซ่อนตัวอยู่เหรอ?",
  ui_story_5051_50511301_31_dialog_content = "ฉันมั่นใจร้อยเปอร์เซ็นต์",
  ui_story_5051_50511301_32_dialog_content = "ทำไมคุณมั่นใจจัง คุณได้ข้อมูลนั้นมาจากไหน?",
  ui_story_5051_50511301_33_dialog_content = "คุณสัญญากับฉันว่าจะไม่ถาม",
  ui_story_5051_50511301_34_dialog_content = "แต่คุณสามารถลงโทษฉันตามที่คุณต้องการหากข้อมูลเป็นเท็จ",
  ui_story_5051_50511301_35_dialog_content = "เอาล่ะ. คุณร็อต ให้เรามุ่งหน้าไปยังพื้นที่นั้น",
