  ui_story_5051_50511501_12_dialog_content = "ฉันต้องปรึกษากับสภาผู้อาวุโสและหอยุติธรรมเกี่ยวกับเรื่องนี้กับเฮาส์คาร์ติมาโดยเร็วที่สุด",
  ui_story_5051_50511501_13_dialog_content = "ขอโทษนะโจชัว",
  ui_story_5051_50511501_14_dialog_content = "ครั้งหน้า หลังจากฉันทำสิ่งนี้เสร็จ เราทั้งสี่คนจะนั่งทานอาหารเย็นกับครอบครัว ตกลงไหม?",
  ui_story_5051_50511501_15_dialog_content = "แดเนียล คุณบอกฉันได้ไหมว่าพวกเขากำลังจะทำอะไรกับเฮาส์คาร์ติมา?",
  ui_story_5051_50511501_16_dialog_content = "อย่าแม้แต่จะกังวลกับมัน Kartimas จะได้รับสิ่งที่พวกเขาสมควรได้รับ",
