  ui_story_5051_50511501_20_dialog_content = "วันนี้ คนเหล่านั้นจากบ้าน Kartima ชี้มีดเย็นมาที่เรา ลูกสาวที่รักของเรา",
  ui_story_5051_50511501_21_dialog_content = "พวกเขาไม่เคยถือว่าลูกสาวของเราบริสุทธิ์เมื่อพวกเขาทรยศเรา",
