  ui_story_5051_50511501_245_dialog_content = "ไอ้พวกสารเลวทั้งหลาย...",
  ui_story_5051_50511501_246_dialog_content = "<size=45>ไม่แอบมองแล้ว!</size>",
  ui_story_5051_50511601_1_dialog_content = "แฮ่ก... แฮ่ก... แฮ่ก...",
