  ui_story_5051_50511601_12_dialog_content = "ที่น่าแปลกใจยิ่งกว่าคือคุณดูเหมือน... ไม่น่าเชื่อถือ!",
  ui_story_5051_50511601_13_dialog_content = "แต่เมื่อเทียบกับสิ่งที่ฉันจำได้ คุณยังคงเข้ากับคนง่าย น่ารัก ร่าเริงมากกว่า...",
