  ui_story_5051_50511601_78_dialog_content = "ฉันไม่เชื่อถือการตัดสินใจของคุณ เลือกที่จะเพิกเฉยต่อคำแนะนำของคุณ...",
  ui_story_5051_50511601_79_dialog_content = "ฉันไม่ชื่นชมความพยายามของคุณ มอบหมายภาระหน้าที่ทุกอย่างในครอบครัวให้คุณ...",
  ui_story_5051_50511601_80_dialog_content = "ฉันไม่ได้อยู่เคียงข้างคุณในเวลาที่คุณต้องการฉันมากที่สุด...",
  ui_story_5051_50511601_81_dialog_content = "ฉันขอโทษ!",
  ui_story_5051_50511601_82_dialog_content = "<color=#e8d9bb>เพล้ง!</color>",
  ui_story_5051_50511601_83_dialog_content = "<anim type=Shake>แดเนียล...</anim>",
  ui_story_5051_50511601_84_dialog_content = "ฉันอยู่นี่ ฉันอยู่นี่ โจชัว!",
  ui_story_5051_50511601_85_dialog_content = "<anim type=Shake>แดเนียล...เวโรนิก้า...คาร์ลีน...</anim>",
  ui_story_5051_50511601_86_dialog_content = "<anim type=Shake>อื้อหือ!!!</anim>",
  ui_story_5051_50511601_87_dialog_content = "โจชัว!",
  ui_story_5051_50511601_88_dialog_content = "แม่? เกิดอะไรขึ้นกับแม่?",
  ui_story_5051_50511601_89_dialog_content = "<color=#e8d9bb>เสียงดังก้อง</color>",
  ui_story_5051_50511601_90_dialog_content = "<color=#e8d9bb>รัมเบิ้ล—!!!</color>",
  ui_story_5051_50511601_91_dialog_content = "เสียงฟ้าร้องนั่นอีกแล้วเหรอ?",
  ui_story_5051_50511601_92_dialog_content = "แผ่นดินไหว? แผ่นดินไหวเหรอ?",
  ui_story_5051_50511601_93_dialog_content = "ไม่ ไม่มีแผ่นดินไหวในคืนนั้นในประวัติศาสตร์ที่แท้จริง",
  ui_story_5051_50511601_94_dialog_content = "ไม่คิดว่าจะได้เห็นอะไร...",
  ui_story_5051_50511601_95_dialog_content = "ฉันด้วย! ฉันกำลังใช้พลังจิตอันน้อยนิดที่ฉันมีเหลืออยู่เพื่อหยั่งรู้ทิศทาง",
  ui_story_5051_50511601_96_dialog_content = "ใกล้หมดเวลาแล้ว Jakine?",
  ui_story_5051_50511601_97_dialog_content = "ไม่ เราควรมีเวลาอีกมากจนกว่าจะหมดวัน นี้ไม่ได้?!",
