  ui_story_5051_50511601_99_dialog_content = "คุณกำลังรออะไรอยู่ จาคีน?",
  ui_story_5051_50511601_100_dialog_content = "นำพวกเราทุกคนออกไป!",
  ui_story_5051_50511601_101_dialog_content = "มาล้อมฉันไว้นะทุกคน!",
  ui_story_5051_50511601_102_dialog_content = "แต่เราคิดถึงพ่อ...",
  ui_story_5051_50511601_103_dialog_content = "มันเหมาะแล้วที่คนอหังการจะถูกขังอยู่ที่นี่ ลืมเขาไปเถอะ!",
  ui_story_5051_50511601_104_dialog_content = "ถึงจะเป็นวายร้ายที่ร้ายกาจที่สุด เราก็ไม่ควรทิ้งเขาไว้แบบนี้...",
  ui_story_5051_50511601_105_dialog_content = "โทรไปหาเจ้าเมือง",
