  ui_story_5051_50511601_114_dialog_content = "เกิดอะไรขึ้นมีอา?",
  ui_story_5051_50511601_115_dialog_content = "ที่ว่างข้างหลังเรา... มันค่อยๆ ยุบลงไปในความว่างเปล่า!",
  ui_story_5051_50511601_116_dialog_content = "ต้องเร่งรีบ PlayerName!",
  ui_story_5051_50511601_117_dialog_content = "ตามฉันมาและมุ่งหน้าไปยังตำแหน่งที่เจ้าเมืองเคยอยู่!",
  ui_story_5051_50511601_118_dialog_content = "จาคีน ถ้าเรายังไม่เห็นเขาในวินาทีสุดท้าย...",
