  ui_story_5051_50511601_129_dialog_content = "โอ้ว...",
  ui_story_5051_50511601_130_dialog_content = "เข้ามา!",
  ui_story_5051_50511601_131_dialog_content = "พ่อ!",
  ui_story_5051_50511601_132_dialog_content = "ระวัง เรามีแขกที่ไม่ได้รับเชิญมาที่นี่",
